window.LIB_LAZY=window.LIB_LAZY||{};window.LIB_LAZY["tanakh-genesis-comentatori-onkelos"]={"chapters":[{"num":1,"title":"Pereq 1 - Capitolul 1","verses":[{"v":1,"t":"La început a creat Domnul cerurile și pământul.","notes":["În textul lui Onkelos, atât YHVH, cât și Elohim din ebraică sunt redate aici cu numele divin prescurtat (doi yod), de aceea traducerea are „Domnul”, chiar unde textul ebraic al Torei are „Dumnezeu”. Unde Onkelos păstrează Elohim (de exemplu „Domnul Dumnezeu” din capitolele 2–3), traducerea are „Dumnezeu”."]},{"v":2,"t":"Și pământul era pustiu și gol, și întunericul era întins peste fața adâncului, iar un vânt de la Domnul sufla peste fața apelor.","notes":["„un vânt de la Domnul” (ruḥa min qodam Adonai): Onkelos evită expresia „duhul lui Dumnezeu” și scrie literal „vânt/duh dinaintea Domnului”."]},{"v":3,"t":"Și a zis Domnul: „Să fie lumină!” Și a fost lumină."},{"v":4,"t":"Și a văzut Domnul lumina, că era bună; și a despărțit Domnul între lumină și întuneric."},{"v":5,"t":"Și a numit Domnul lumina zi, iar întunericul l-a numit noapte. Și a fost seară și a fost dimineață: ziua întâi."},{"v":6,"t":"Și a zis Domnul: „Să fie o întindere (sau „tărie”) în mijlocul apelor și să despartă între ape și ape.”"},{"v":7,"t":"Și a făcut Domnul întinderea și a despărțit între apele care sunt sub întindere și apele care sunt deasupra întinderii. Și a fost așa."},{"v":8,"t":"Și a numit Domnul întinderea ceruri. Și a fost seară și a fost dimineață: ziua a doua."},{"v":9,"t":"Și a zis Domnul: „Să se adune apele de sub ceruri într-un singur loc și să se arate uscatul.” Și a fost așa."},{"v":10,"t":"Și a numit Domnul uscatul pământ, iar locul de adunare al apelor l-a numit mări. Și a văzut Domnul că era bine."},{"v":11,"t":"Și a zis Domnul: „Să facă pământul să răsară verdeață, iarbă care face sămânță, pomi roditori care fac rod după soiul lor, care au sămânța în ei, pe pământ.” Și a fost așa."},{"v":12,"t":"Și pământul a scos verdeață, iarbă care face sămânță după soiul ei și pomi care fac rod, care au sămânța în ei, după soiul lor. Și a văzut Domnul că era bine."},{"v":13,"t":"Și a fost seară și a fost dimineață: ziua a treia."},{"v":14,"t":"Și a zis Domnul: „Să fie luminători în întinderea cerurilor, ca să despartă între zi și noapte; și să fie semne și vremuri hotărâte și să se numere prin ei zile și ani."},{"v":15,"t":"Și să fie luminători în întinderea cerurilor, ca să lumineze pământul.” Și a fost așa."},{"v":16,"t":"Și a făcut Domnul cei doi luminători mari: luminătorul cel mare, ca să stăpânească ziua, și luminătorul cel mic, ca să stăpânească noaptea; și stelele."},{"v":17,"t":"Și i-a pus Domnul în întinderea cerurilor, ca să lumineze pământul,"},{"v":18,"t":"și să stăpânească ziua și noaptea și să despartă între lumină și întuneric. Și a văzut Domnul că era bine."},{"v":19,"t":"Și a fost seară și a fost dimineață: ziua a patra."},{"v":20,"t":"Și a zis Domnul: „Să mișune apele de vietăți, suflet viu, iar păsările să zboare deasupra pământului, pe fața întinderii cerurilor.”"},{"v":21,"t":"Și a creat Domnul peștii cei mari (taninaya) și orice suflet viu care se mișcă, cu care au mișunat apele, după soiul lor, și orice pasăre care zboară, după soiul ei. Și a văzut Domnul că era bine."},{"v":22,"t":"Și i-a binecuvântat Domnul, zicând: „Creșteți și înmulțiți-vă și umpleți apele mărilor, iar păsările să se înmulțească pe pământ.”"},{"v":23,"t":"Și a fost seară și a fost dimineață: ziua a cincea."},{"v":24,"t":"Și a zis Domnul: „Să scoată pământul suflet viu după soiul lui: vite, târâtoare și fiare ale pământului după soiul lor.” Și a fost așa."},{"v":25,"t":"Și a făcut Domnul fiarele pământului după soiul lor, vitele după soiul lor și toate târâtoarele pământului după soiul lor. Și a văzut Domnul că era bine."},{"v":26,"t":"Și a zis Domnul: „Să facem om după chipul nostru, după asemănarea noastră; și să stăpânească peste peștii mării, peste păsările cerurilor, peste vite, peste tot pământul și peste toate târâtoarele care se târăsc pe pământ.”"},{"v":27,"t":"Și a creat Domnul pe om după chipul lui; după chipul Domnului l-a creat; parte bărbătească și parte femeiască i-a creat."},{"v":28,"t":"Și i-a binecuvântat Domnul și le-a zis Domnul: „Creșteți și înmulțiți-vă, umpleți pământul și supuneți-l; și stăpâniți peste peștii mării, peste păsările cerurilor și peste toată vietatea care se târăște pe pământ.”"},{"v":29,"t":"Și a zis Domnul: „Iată, v-am dat toată iarba care face sămânță, care este pe fața întregului pământ, și toți pomii în care este rod de pom care face sămânță; vouă să vă fie de mâncare."},{"v":30,"t":"Și tuturor fiarelor pământului, tuturor păsărilor cerurilor și tuturor celor ce se târăsc pe pământ, în care este suflet viu, le-am dat toată verdeața ierbii de mâncare.” Și a fost așa."},{"v":31,"t":"Și a văzut Domnul tot ce făcuse, și iată, era foarte bun. Și a fost seară și a fost dimineață: ziua a șasea."}]},{"num":2,"title":"Pereq 2 - Capitolul 2","verses":[{"v":1,"t":"Și s-au desăvârșit cerurile și pământul și toate oștile lor."},{"v":2,"t":"Și a isprăvit Domnul în ziua a șaptea lucrarea pe care o făcuse și S-a odihnit în ziua a șaptea de toată lucrarea pe care o făcuse."},{"v":3,"t":"Și a binecuvântat Domnul ziua a șaptea și a sfințit-o, căci în ea S-a odihnit de toată lucrarea pe care o crease Domnul ca s-o facă."},{"v":4,"t":"Acestea sunt istorisirile cerurilor și ale pământului, când au fost create, în ziua în care a făcut Domnul Dumnezeu pământul și cerurile."},{"v":5,"t":"Și niciun copac al câmpului nu era încă pe pământ și nicio iarbă a câmpului nu răsărise încă, căci Domnul Dumnezeu nu coborâse ploaie pe pământ și nu era om ca să lucreze pământul."},{"v":6,"t":"Și un nor se ridica de pe pământ și uda toată fața pământului."},{"v":7,"t":"Și a creat Domnul Dumnezeu pe om din țărâna pământului și i-a suflat în nări suflare de viață, și a fost în om un duh care vorbește.","notes":["„un duh care vorbește” (ruaḥ memallela): așa redă Onkelos „suflet viu” din ebraică."]},{"v":8,"t":"Și a sădit Domnul Dumnezeu o grădină în Eden, de la început, și a pus acolo pe omul pe care îl crease."},{"v":9,"t":"Și a făcut Domnul Dumnezeu să răsară din pământ tot pomul plăcut la vedere și bun de mâncat, și pomul vieții în mijlocul grădinii, și pomul din ale cărui roade cei care mănâncă devin înțelepți să deosebească între bine și rău."},{"v":10,"t":"Și un râu ieșea din Eden ca să ude grădina, și de acolo se despărțea și devenea patru capete de râuri."},{"v":11,"t":"Numele celui dintâi este Pison; el înconjoară toată țara Havila, unde este aur."},{"v":12,"t":"Și aurul țării aceleia este bun; acolo se află bdeliu (bedolḥa) și pietre de beril.","notes":["bedolḥa = bdeliu (rășină aromatică sau piatră prețioasă; identificare nesigură)."]},{"v":13,"t":"Și numele râului al doilea este Ghihon; el înconjoară toată țara Cuș."},{"v":14,"t":"Și numele râului al treilea este Tigrul (Diglat); el curge la răsărit de Asiria. Iar râul al patrulea este Eufratul."},{"v":15,"t":"Și a luat Domnul Dumnezeu pe om și l-a așezat în grădina Edenului, ca s-o lucreze și s-o păzească."},{"v":16,"t":"Și Domnul Dumnezeu i-a poruncit omului, zicând: „Din orice pom al grădinii poți să mănânci;"},{"v":17,"t":"dar din pomul din ale cărui roade cei care mănâncă devin înțelepți să deosebească între bine și rău să nu mănânci, căci în ziua în care vei mânca din el vei muri negreșit.”"},{"v":18,"t":"Și a zis Domnul Dumnezeu: „Nu este bine ca omul să fie singur; îi voi face un sprijin potrivit pentru el.”"},{"v":19,"t":"Și a creat Domnul Dumnezeu din pământ toate fiarele câmpului și toate păsările cerurilor și le-a adus la om, ca să vadă cum le va numi; și orice nume pe care omul îl dădea unui suflet viu, acela îi era numele."},{"v":20,"t":"Și omul a pus nume tuturor vitelor, păsărilor cerurilor și tuturor fiarelor câmpului; dar pentru om nu a găsit un sprijin potrivit pentru el."},{"v":21,"t":"Și Domnul Dumnezeu a trimis un somn peste om, și el a adormit; și a luat una din coastele lui și a umplut cu carne locul ei."},{"v":22,"t":"Și Domnul Dumnezeu a zidit coasta pe care o luase din om într-o femeie și a adus-o la om."},{"v":23,"t":"Și omul a zis: „De data aceasta, aceasta este os din oasele mele și carne din carnea mea; aceasta se va numi femeie, căci din bărbatul ei a fost luată aceasta.”"},{"v":24,"t":"De aceea va lăsa bărbatul locul de culcare al tatălui său și al mamei sale și se va lipi de soția lui, și vor fi un singur trup."},{"v":25,"t":"Și erau amândoi goi, omul și soția lui, și nu se rușinau."}]},{"num":3,"title":"Pereq 3 - Capitolul 3","verses":[{"v":1,"t":"Și șarpele era mai înțelept decât toate fiarele câmpului pe care le făcuse Domnul Dumnezeu. Și i-a zis femeii: „Este adevărat că a zis Domnul: «Să nu mâncați din niciun pom al grădinii»?”"},{"v":2,"t":"Și femeia a zis șarpelui: „Din roadele pomilor grădinii mâncăm,"},{"v":3,"t":"dar din roadele pomului care este în mijlocul grădinii a zis Domnul: «Să nu mâncați din el și să nu vă apropiați de el, ca să nu muriți.»”"},{"v":4,"t":"Și șarpele i-a zis femeii: „Nu veți muri negreșit;"},{"v":5,"t":"căci este descoperit înaintea Domnului că, în ziua în care veți mânca din el, vi se vor deschide ochii și veți fi ca cei mari, înțelepți să deosebiți între bine și rău.”"},{"v":6,"t":"Și femeia a văzut că pomul era bun de mâncat și că era un leac pentru ochi și că pomul era de dorit ca să privești în el; și a luat din rodul lui și a mâncat; și a dat și bărbatului ei, care era cu ea, și el a mâncat."},{"v":7,"t":"Și s-au deschis ochii amândurora și au știut că erau goi; și au cusut frunze de smochin și și-au făcut brâie."},{"v":8,"t":"Și au auzit glasul Cuvântului (Memra) Domnului Dumnezeu umblând prin grădină, la odihna zilei; și omul și soția lui s-au ascuns dinaintea Domnului Dumnezeu printre pomii grădinii.","notes":["Memra = „Cuvântul”; Onkelos folosește expresia „Cuvântul Domnului” ca să evite atribuirea directă către Dumnezeu a unor acțiuni omenești."]},{"v":9,"t":"Și Domnul Dumnezeu l-a chemat pe om și i-a zis: „Unde ești?”"},{"v":10,"t":"Și el a zis: „Am auzit glasul Cuvântului Tău în grădină și m-am temut, căci sunt gol, și m-am ascuns.”"},{"v":11,"t":"Și El a zis: „Cine ți-a spus că ești gol? Nu cumva ai mâncat din pomul din care ți-am poruncit să nu mănânci?”"},{"v":12,"t":"Și omul a zis: „Femeia pe care ai dat-o să fie cu mine, ea mi-a dat din pom, și am mâncat.”"},{"v":13,"t":"Și Domnul Dumnezeu a zis femeii: „Ce este aceasta pe care ai făcut-o?” Și femeia a zis: „Șarpele m-a amăgit, și am mâncat.”"},{"v":14,"t":"Și Domnul Dumnezeu a zis șarpelui: „Pentru că ai făcut aceasta, blestemat ești mai mult decât toate vitele și decât toate fiarele câmpului; pe pântecele tău vei merge și țărână vei mânca în toate zilele vieții tale."},{"v":15,"t":"Și vrăjmășie voi pune între tine și femeie și între fiii tăi și fiii ei; el își va aminti de tine ce i-ai făcut de la început, iar tu îl vei pândi până la sfârșit.”","notes":["Versetul este o parafrază explicativă a lui Onkelos, nu traducerea literală a ebraicii."]},{"v":16,"t":"Femeii i-a zis: „Voi înmulți foarte mult durerea ta și sarcinile tale; cu durere vei naște fii; spre bărbatul tău va fi dorința ta, iar el va stăpâni peste tine.”"},{"v":17,"t":"Iar omului i-a zis: „Pentru că ai primit cuvântul soției tale și ai mâncat din pomul despre care ți-am poruncit, zicând: «Să nu mănânci din el», blestemat este pământul din pricina ta; cu trudă vei mânca din el în toate zilele vieții tale."},{"v":18,"t":"Spini și ciulini îți va face să răsară, și vei mânca iarba câmpului."},{"v":19,"t":"În sudoarea feței tale vei mânca pâine, până te vei întoarce în pământul din care ai fost creat; căci țărână ești și în țărână te vei întoarce.”"},{"v":20,"t":"Și omul a pus soției lui numele Eva, căci ea a fost mama tuturor fiilor oamenilor."},{"v":21,"t":"Și Domnul Dumnezeu a făcut pentru om și pentru soția lui haine de cinste, peste pielea trupului lor, și i-a îmbrăcat.","notes":["„haine de cinste” (levușin di-yqar): Onkelos parafrazează „haine de piele” din ebraică."]},{"v":22,"t":"Și a zis Domnul Dumnezeu: „Iată, omul a fost unic în lume, de la sine, ca să cunoască binele și răul; și acum, ca nu cumva să-și întindă mâna și să ia și din pomul vieții și să mănânce și să trăiască în veac...”"},{"v":23,"t":"Și Domnul Dumnezeu l-a trimis din grădina Edenului ca să lucreze pământul din care fusese creat."},{"v":24,"t":"Și l-a izgonit pe om și a pus de la început la grădina Edenului heruvimii și ascuțișul sabiei care se întoarce, ca să păzească drumul spre pomul vieții."}]},{"num":4,"title":"Pereq 4 - Capitolul 4","verses":[{"v":1,"t":"Și omul a cunoscut-o pe Eva, soția lui; și ea a rămas însărcinată și l-a născut pe Cain și a zis: „Am dobândit un bărbat (de) dinaintea Domnului.”","notes":["„(de)”: în ediție cuvântul min („de la”) apare între paranteze, ca variantă de text; traducerea păstrează parantezele sursei."]},{"v":2,"t":"Și a mai născut pe fratele lui, pe Abel. Și Abel era păstor de oi, iar Cain era lucrător al pământului."},{"v":3,"t":"Și a fost, la sfârșitul unor zile, că Cain a adus din roadele pământului o jertfă înaintea Domnului."},{"v":4,"t":"Și Abel a adus și el din întâii-născuți ai turmei lui și din grăsimea lor. Și a fost bunăvoință de la Domnul față de Abel și față de jertfa lui."},{"v":5,"t":"Iar față de Cain și față de jertfa lui nu a fost bunăvoință. Și Cain s-a mâniat foarte tare, și fața i s-a posomorât."},{"v":6,"t":"Și a zis Domnul lui Cain: „De ce te-ai mâniat și de ce ți s-a posomorât fața?"},{"v":7,"t":"Oare, dacă îți vei îndrepta faptele, nu ți se va ierta? Iar dacă nu îți vei îndrepta faptele, păcatul tău este păstrat pentru ziua judecății, când vei fi pedepsit, dacă nu te vei pocăi; dar dacă te vei pocăi, ți se va ierta.”"},{"v":8,"t":"Și Cain i-a vorbit lui Abel, fratele său. Și când erau ei în câmp, Cain s-a ridicat asupra lui Abel, fratele său, și l-a ucis."},{"v":9,"t":"Și a zis Domnul lui Cain: „Unde este Abel, fratele tău?” Și el a zis: „Nu știu. Sunt eu oare păzitorul fratelui meu?”"},{"v":10,"t":"Și El a zis: „Ce ai făcut? Glasul sângelui generațiilor care urmau să iasă din fratele tău strigă la Mine din pământ.","notes":["Onkelos explică pluralul ebraic „sângiuri” ca „sângele generațiilor” care urmau să se nască din Abel."]},{"v":11,"t":"Și acum, blestemat ești de pământul care și-a deschis gura și a primit din mâna ta sângele fratelui tău."},{"v":12,"t":"Când vei lucra pământul, nu-ți va mai da puterea lui; rătăcitor și pribeag vei fi pe pământ.”"},{"v":13,"t":"Și a zis Cain înaintea Domnului: „Vina mea este prea mare ca să fie iertată."},{"v":14,"t":"Iată, m-ai izgonit astăzi de pe fața pământului, și dinaintea Ta nu este cu putință să mă ascund; și voi fi rătăcitor și pribeag pe pământ, și oricine mă va găsi mă va ucide.”"},{"v":15,"t":"Și Domnul i-a zis: „De aceea, oricine îl va ucide pe Cain va fi pedepsit timp de șapte generații.” Și Domnul a pus un semn lui Cain, ca să nu-l ucidă oricine îl va găsi."},{"v":16,"t":"Și Cain a ieșit dinaintea Domnului și s-a așezat în țară, pribeag și rătăcitor, cum fusese făcut asupra lui, la răsărit de grădina Edenului."},{"v":17,"t":"Și Cain a cunoscut-o pe soția lui; și ea a rămas însărcinată și l-a născut pe Enoh. Și el zidea o cetate și a pus cetății numele fiului său, Enoh."},{"v":18,"t":"Și lui Enoh i s-a născut Irad; și Irad l-a născut pe Mehuiael, și Mehuiael l-a născut pe Metușael, și Metușael l-a născut pe Lameh.","notes":["Ediția are două grafii ale numelui (Meḥuyael și Meḥiyael), ca și textul ebraic al Torei; traducerea le păstrează."]},{"v":19,"t":"Și Lameh și-a luat două soții: numele uneia era Ada, iar numele celei de-a doua, Țila."},{"v":20,"t":"Și Ada l-a născut pe Iabal; el a fost căpetenia celor care locuiesc în corturi și au vite."},{"v":21,"t":"Și numele fratelui său era Iubal; el a fost căpetenia tuturor celor care cântă cu gura harfei, care știu să cânte din liră și din flaut."},{"v":22,"t":"Și Țila a născut și ea pe Tubal-Cain, căpetenia tuturor celor care știu lucrul aramei și al fierului. Și sora lui Tubal-Cain era Naama."},{"v":23,"t":"Și Lameh a zis soțiilor lui: „Ada și Țila, ascultați glasul meu; soții ale lui Lameh, luați aminte la cuvântul meu: nu am ucis un bărbat, ca din pricina lui să port vina, nici n-am rănit un tânăr, ca din pricina lui să fie nimicită sămânța mea."},{"v":24,"t":"Căci, dacă pentru Cain s-au amânat șapte generații, nu oare pentru Lameh, fiul lui, șaptezeci și șapte?”"},{"v":25,"t":"Și omul a cunoscut-o din nou pe soția lui; și ea a născut un fiu și i-a pus numele Set, căci a zis: „Domnul mi-a dat un alt fiu în locul lui Abel, pe care l-a ucis Cain.”"},{"v":26,"t":"Și lui Set i s-a născut și lui un fiu, și i-a pus numele Enoș. Atunci, în zilele lui, au încetat fiii oamenilor să se roage în numele Domnului.","notes":["„au încetat… să se roage” (ḥallu… mi-le-ṣallaʾa): Onkelos înțelege ebraicul huḥal ca „au încetat/au profanat”, nu „au început”."]}]},{"num":5,"title":"Pereq 5 - Capitolul 5","verses":[{"v":1,"t":"Aceasta este cartea istorisirilor lui Adam. În ziua în care a creat Domnul pe Adam, după asemănarea lui Dumnezeu l-a făcut."},{"v":2,"t":"Parte bărbătească și parte femeiască i-a creat; și i-a binecuvântat și le-a pus numele Adam, în ziua în care au fost creați."},{"v":3,"t":"Și Adam a trăit o sută treizeci de ani și a născut după asemănarea lui, care semăna cu el, și i-a pus numele Set."},{"v":4,"t":"Și zilele lui Adam după ce l-a născut pe Set au fost opt sute de ani; și a născut fii și fiice."},{"v":5,"t":"Și toate zilele pe care le-a trăit Adam au fost nouă sute treizeci de ani; și a murit."},{"v":6,"t":"Și Set a trăit o sută cinci ani și l-a născut pe Enoș."},{"v":7,"t":"Și Set a trăit, după ce l-a născut pe Enoș, opt sute șapte ani; și a născut fii și fiice."},{"v":8,"t":"Și toate zilele lui Set au fost nouă sute doisprezece ani; și a murit."},{"v":9,"t":"Și Enoș a trăit nouăzeci de ani și l-a născut pe Chenan."},{"v":10,"t":"Și Enoș a trăit, după ce l-a născut pe Chenan, opt sute cincisprezece ani; și a născut fii și fiice."},{"v":11,"t":"Și toate zilele lui Enoș au fost nouă sute cinci ani; și a murit."},{"v":12,"t":"Și Chenan a trăit șaptezeci de ani și l-a născut pe Mahalaleel."},{"v":13,"t":"Și Chenan a trăit, după ce l-a născut pe Mahalaleel, opt sute patruzeci de ani; și a născut fii și fiice."},{"v":14,"t":"Și toate zilele lui Chenan au fost nouă sute zece ani; și a murit."},{"v":15,"t":"Și Mahalaleel a trăit șaizeci și cinci de ani și l-a născut pe Iared."},{"v":16,"t":"Și Mahalaleel a trăit, după ce l-a născut pe Iared, opt sute treizeci de ani; și a născut fii și fiice."},{"v":17,"t":"Și toate zilele lui Mahalaleel au fost opt sute nouăzeci și cinci de ani; și a murit."},{"v":18,"t":"Și Iared a trăit o sută șaizeci și doi de ani și l-a născut pe Enoh."},{"v":19,"t":"Și Iared a trăit, după ce l-a născut pe Enoh, opt sute de ani; și a născut fii și fiice."},{"v":20,"t":"Și toate zilele lui Iared au fost nouă sute șaizeci și doi de ani; și a murit."},{"v":21,"t":"Și Enoh a trăit șaizeci și cinci de ani și l-a născut pe Metusala."},{"v":22,"t":"Și Enoh a umblat în frica Domnului, după ce l-a născut pe Metusala, trei sute de ani; și a născut fii și fiice."},{"v":23,"t":"Și toate zilele lui Enoh au fost trei sute șaizeci și cinci de ani."},{"v":24,"t":"Și Enoh a umblat în frica Domnului și nu a mai fost, căci (nu) l-a făcut Domnul să moară.","notes":["„(nu)”: în ediție cuvântul la („nu”) apare între paranteze, ca variantă; cu el, sensul este „Domnul nu l-a făcut să moară”, fără el, „Domnul l-a făcut să moară”."]},{"v":25,"t":"Și Metusala a trăit o sută optzeci și șapte de ani și l-a născut pe Lameh."},{"v":26,"t":"Și Metusala a trăit, după ce l-a născut pe Lameh, șapte sute optzeci și doi de ani; și a născut fii și fiice."},{"v":27,"t":"Și toate zilele lui Metusala au fost nouă sute șaizeci și nouă de ani; și a murit."},{"v":28,"t":"Și Lameh a trăit o sută optzeci și doi de ani și a născut un fiu."},{"v":29,"t":"Și i-a pus numele Noe, zicând: „Acesta ne va mângâia de lucrul nostru și de truda mâinilor noastre, din pământul pe care l-a blestemat Domnul.”"},{"v":30,"t":"Și Lameh a trăit, după ce l-a născut pe Noe, cinci sute nouăzeci și cinci de ani; și a născut fii și fiice."},{"v":31,"t":"Și toate zilele lui Lameh au fost șapte sute șaptezeci și șapte de ani; și a murit."},{"v":32,"t":"Și Noe era în vârstă de cinci sute de ani; și Noe i-a născut pe Sem, pe Ham și pe Iafet."}]},{"num":6,"title":"Pereq 6 - Capitolul 6","verses":[{"v":1,"t":"Și a fost, când au început fiii oamenilor să se înmulțească pe fața pământului și li s-au născut fiice,"},{"v":2,"t":"fiii celor mari au văzut că fiicele oamenilor erau frumoase și și-au luat soții dintre toate cele pe care le-au ales.","notes":["„fiii celor mari” (bene ravrevaya): Onkelos redă „fiii lui Dumnezeu” (bene ha-Elohim) prin „fiii celor mari/ai nobililor”."]},{"v":3,"t":"Și a zis Domnul: „Nu va dăinui înaintea Mea în veac această generație rea, pentru că ei sunt carne și faptele lor sunt rele. Un răgaz le-am dat: o sută douăzeci de ani, dacă se vor pocăi.”"},{"v":4,"t":"Uriașii erau pe pământ în zilele acelea și chiar și după aceea, când fiii celor mari intrau la fiicele oamenilor iar ele născau pentru ei; aceștia sunt uriașii din vechime, oameni cu nume."},{"v":5,"t":"Și a văzut Domnul că era mare răutatea omului pe pământ și că toată înclinația gândurilor inimii lui era numai rea în fiecare zi."},{"v":6,"t":"Și Domnul S-a răzgândit, prin Cuvântul Său, că îl făcuse pe om pe pământ, și a zis, prin Cuvântul Său, să le frângă puterea după voia Lui.","notes":["„prin Cuvântul Său” (be-memreh): parafrază prin care Onkelos evită să atribuie lui Dumnezeu direct căința sau mâhnirea."]},{"v":7,"t":"Și a zis Domnul: „Voi șterge pe omul pe care l-am creat de pe fața pământului, de la om până la vite, până la târâtoare și până la păsările cerurilor, căci M-am răzgândit, prin Cuvântul Meu, că i-am făcut.”"},{"v":8,"t":"Dar Noe a găsit îndurare înaintea Domnului."},{"v":9,"t":"Acestea sunt istorisirile lui Noe. Noe era un om drept, desăvârșit în generațiile lui; în frica Domnului a umblat Noe."},{"v":10,"t":"Și Noe a născut trei fii: pe Sem, pe Ham și pe Iafet."},{"v":11,"t":"Și pământul s-a stricat înaintea Domnului, și pământul s-a umplut de jafuri."},{"v":12,"t":"Și a văzut Domnul pământul, și iată, se stricase, căci toată făptura, fiecare om, își stricase calea pe pământ."},{"v":13,"t":"Și a zis Domnul lui Noe: „Sfârșitul a toată făptura a venit înaintea Mea, căci pământul s-a umplut de jafuri din pricina faptelor lor rele; și iată, Eu îi voi nimici împreună cu pământul."},{"v":14,"t":"Fă-ți o arcă din lemn de cedru; încăperi să faci în arcă și s-o ungi pe dinăuntru și pe dinafară cu smoală."},{"v":15,"t":"Și iată cum s-o faci: trei sute de coți lungimea arcei, cincizeci de coți lățimea ei și treizeci de coți înălțimea ei."},{"v":16,"t":"Lumină să faci arcei și s-o desăvârșești până la un cot pe deasupra; iar ușa arcei s-o pui în partea ei; încăperi de jos, de-al doilea și de-al treilea să-i faci."},{"v":17,"t":"Și Eu, iată, aduc potopul de ape pe pământ, ca să nimicesc toată făptura în care este duh de viață de sub ceruri; tot ce este pe pământ va muri."},{"v":18,"t":"Dar voi întări legământul Meu cu tine; și vei intra în arcă tu și fiii tăi și soția ta și soțiile fiilor tăi cu tine."},{"v":19,"t":"Și din tot ce trăiește, din toată făptura, câte două din toate să aduci în arcă, ca să rămână în viață cu tine; parte bărbătească și parte femeiască să fie."},{"v":20,"t":"Din păsări după soiul lor și din vite după soiul lor și din toate târâtoarele pământului după soiul lor, câte două din toate vor intra la tine, ca să rămână în viață."},{"v":21,"t":"Iar tu ia-ți din orice mâncare care se mănâncă și adun-o la tine, și să fie de mâncare pentru tine și pentru ei.”"},{"v":22,"t":"Și Noe a făcut întocmai cum îi poruncise Domnul; așa a făcut."}]},{"num":7,"title":"Pereq 7 - Capitolul 7","verses":[{"v":1,"t":"Și a zis Domnul lui Noe: „Intră tu și toți oamenii casei tale în arcă, căci pe tine te-am văzut drept înaintea Mea în generația aceasta."},{"v":2,"t":"Din toate vitele curate să iei câte șapte, parte bărbătească și parte femeiască; iar din vitele care nu sunt curate, câte două, parte bărbătească și parte femeiască."},{"v":3,"t":"De asemenea din păsările cerurilor, câte șapte, parte bărbătească și parte femeiască, ca să păstrezi în viață sămânța pe fața întregului pământ."},{"v":4,"t":"Căci peste încă șapte zile voi coborî ploaie pe pământ patruzeci de zile și patruzeci de nopți și voi șterge de pe fața pământului toată ființa pe care am făcut-o.”"},{"v":5,"t":"Și Noe a făcut întocmai cum îi poruncise Domnul."},{"v":6,"t":"Și Noe era în vârstă de șase sute de ani când potopul de ape a venit pe pământ."},{"v":7,"t":"Și Noe a intrat, și fiii lui și soția lui și soțiile fiilor lui cu el, în arcă, din fața apelor potopului."},{"v":8,"t":"Din vitele curate și din vitele care nu sunt curate și din păsări și din tot ce se târăște pe pământ,"},{"v":9,"t":"câte două au intrat la Noe în arcă, parte bărbătească și parte femeiască, așa cum îi poruncise Domnul lui Noe."},{"v":10,"t":"Și a fost, după cele șapte zile, că apele potopului au venit pe pământ."},{"v":11,"t":"În anul al șase-sutelea al vieții lui Noe, în luna a doua, în ziua a șaptesprezecea a lunii, în ziua aceea s-au spart toate izvoarele adâncului celui mare și ferestrele cerurilor s-au deschis."},{"v":12,"t":"Și ploaia a coborât pe pământ patruzeci de zile și patruzeci de nopți."},{"v":13,"t":"Chiar în ziua aceea au intrat Noe și Sem, Ham și Iafet, fiii lui Noe, și soția lui Noe și cele trei soții ale fiilor lui cu ei, în arcă,"},{"v":14,"t":"ei și toate fiarele după soiul lor și toate vitele după soiul lor și toate târâtoarele care se târăsc pe pământ după soiul lor și toate păsările după soiul lor, toată pasărea, tot ce zboară."},{"v":15,"t":"Și au intrat cu Noe în arcă câte două din toată făptura în care este duh de viață."},{"v":16,"t":"Și cele care au intrat, parte bărbătească și parte femeiască din toată făptura, au intrat așa cum îi poruncise Domnul. Și Domnul a ocrotit (prin Cuvântul Său) asupra lui.","notes":["„(prin Cuvântul Său)”: în ediție be-memreh apare între paranteze, ca variantă de text."]},{"v":17,"t":"Și potopul a fost patruzeci de zile pe pământ; și apele au crescut și au ridicat arca, și ea s-a înălțat deasupra pământului."},{"v":18,"t":"Și apele s-au întărit și au crescut foarte mult pe pământ, și arca mergea pe fața apelor."},{"v":19,"t":"Și apele s-au întărit foarte, foarte mult pe pământ, și s-au acoperit toți munții înalți care sunt sub toate cerurile."},{"v":20,"t":"Cu cincisprezece coți mai sus s-au întărit apele, și munții s-au acoperit."},{"v":21,"t":"Și a murit toată făptura care se mișca pe pământ: păsări, vite, fiare și toate târâtoarele care se târăsc pe pământ, și toți oamenii."},{"v":22,"t":"Tot ce avea în nări suflare de duh de viață, din tot ce era pe uscat, a murit."},{"v":23,"t":"Și El a șters toată ființa care era pe fața pământului, de la om până la vite, până la târâtoare și până la păsările cerurilor; și au fost șterși de pe pământ. Și a rămas doar Noe și cei care erau cu el în arcă."},{"v":24,"t":"Și apele s-au întărit pe pământ o sută cincizeci de zile."}]},{"num":8,"title":"Pereq 8 - Capitolul 8","verses":[{"v":1,"t":"Și Domnul Și-a adus aminte de Noe și de toate fiarele și de toate vitele care erau cu el în arcă; și Domnul a făcut să treacă un vânt peste pământ, și apele s-au liniștit."},{"v":2,"t":"Și s-au astupat izvoarele adâncului și ferestrele cerurilor, și ploaia a fost oprită din ceruri."},{"v":3,"t":"Și apele s-au retras de pe pământ, retrăgându-se treptat, și apele au scăzut la sfârșitul celor o sută cincizeci de zile."},{"v":4,"t":"Și arca s-a așezat în luna a șaptea, în ziua a șaptesprezecea a lunii, pe munții Kardu.","notes":["Kardu = munții Kurdistanului; Onkelos redă astfel „munții Ararat”."]},{"v":5,"t":"Și apele au tot scăzut până în luna a zecea; în luna a zecea, în ziua întâi a lunii, s-au arătat vârfurile munților."},{"v":6,"t":"Și a fost, la sfârșitul a patruzeci de zile, că Noe a deschis fereastra arcei pe care o făcuse."},{"v":7,"t":"Și a trimis corbul; și el ieșea și se întorcea, până s-au uscat apele de pe pământ."},{"v":8,"t":"Și a trimis porumbița de la el, ca să vadă dacă s-au micșorat apele de pe fața pământului."},{"v":9,"t":"Dar porumbița nu a găsit loc de odihnă pentru talpa piciorului ei și s-a întors la el în arcă, căci apele erau pe fața întregului pământ; și el și-a întins mâna, a luat-o și a adus-o la el în arcă."},{"v":10,"t":"Și a mai așteptat încă alte șapte zile și a trimis din nou porumbița din arcă."},{"v":11,"t":"Și porumbița a venit la el spre vremea serii, și iată, o frunză de măslin ruptă era în gura ei; și Noe a știut că apele se micșoraseră de pe pământ."},{"v":12,"t":"Și a mai așteptat încă alte șapte zile și a trimis porumbița, și ea nu s-a mai întors la el."},{"v":13,"t":"Și a fost, în anul al șase sute unulea, în luna întâi, în ziua întâi a lunii, că apele s-au zvântat de pe pământ; și Noe a îndepărtat acoperișul arcei și a văzut, și iată, fața pământului se zvântase."},{"v":14,"t":"Și în luna a doua, în ziua a douăzeci și șaptea a lunii, pământul s-a uscat."},{"v":15,"t":"Și Domnul i-a vorbit lui Noe, zicând:"},{"v":16,"t":"„Ieși din arcă, tu și soția ta și fiii tăi și soțiile fiilor tăi cu tine."},{"v":17,"t":"Toate fiarele care sunt cu tine, din toată făptura, păsări, vite și toate târâtoarele care se târăsc pe pământ, scoate-le cu tine, ca să se nască pe pământ și să crească și să se înmulțească pe pământ.”"},{"v":18,"t":"Și Noe a ieșit, și fiii lui și soția lui și soțiile fiilor lui cu el."},{"v":19,"t":"Toate fiarele, toate târâtoarele și toate păsările, tot ce se mișcă pe pământ, după familiile lor, au ieșit din arcă."},{"v":20,"t":"Și Noe a zidit un altar înaintea Domnului și a luat din toate vitele curate și din toate păsările curate și a adus arderi-de-tot pe altar."},{"v":21,"t":"Și Domnul a primit cu bunăvoință jertfa lui; și a zis Domnul în Cuvântul Său: „Nu voi mai blestema pământul din pricina păcatelor omului, căci înclinația inimii omului este rea din tinerețea lui; și nu voi mai lovi tot ce trăiește, cum am făcut."},{"v":22,"t":"Cât vor dăinui toate zilele pământului, semănatul și seceratul, frigul și căldura, vara și iarna, ziua și noaptea nu vor înceta.”"}]},{"num":9,"title":"Pereq 9 - Capitolul 9","verses":[{"v":1,"t":"Și Domnul l-a binecuvântat pe Noe și pe fiii lui și le-a zis: „Creșteți și înmulțiți-vă și umpleți pământul."},{"v":2,"t":"Și frica de voi și groaza de voi să fie peste toate fiarele pământului și peste toate păsările cerurilor, peste tot ce mișună pe pământ și peste toți peștii mării; în mâna voastră sunt date."},{"v":3,"t":"Toată vietatea care trăiește să vă fie de mâncare; ca pe verdeața ierbii, v-am dat totul."},{"v":4,"t":"Numai carne cu sufletul ei, cu sângele ei, să nu mâncați."},{"v":5,"t":"Și numai sângele vostru, al sufletelor voastre, îl voi cere; din mâna oricărei fiare îl voi cere; și din mâna omului, din mâna omului care varsă sângele fratelui său, voi cere sufletul omului."},{"v":6,"t":"Cine varsă sângele omului înaintea martorilor, prin hotărârea judecătorilor să i se verse sângele, căci după chipul Domnului l-a făcut pe om.","notes":["„înaintea martorilor, prin hotărârea judecătorilor”: Onkelos înțelege „prin om” (ba-adam) ca referire la pedeapsa dată de tribunal."]},{"v":7,"t":"Iar voi creșteți și înmulțiți-vă, nașteți-vă pe pământ și înmulțiți-vă pe el.”"},{"v":8,"t":"Și Domnul le-a zis lui Noe și fiilor lui cu el:"},{"v":9,"t":"„Și Eu, iată, Îmi întăresc legământul cu voi și cu urmașii voștri după voi"},{"v":10,"t":"și cu tot sufletul viu care este cu voi: păsări, vite și toate fiarele pământului care sunt cu voi, din toate cele ieșite din arcă, până la toate fiarele pământului."},{"v":11,"t":"Și voi întări legământul Meu cu voi: nu va mai fi nimicită toată făptura de apele potopului și nu va mai fi potop ca să strice pământul.”"},{"v":12,"t":"Și a zis Domnul: „Acesta este semnul legământului pe care îl pun între Cuvântul Meu și voi și tot sufletul viu care este cu voi, pentru generațiile veacului:"},{"v":13,"t":"curcubeul Meu l-am pus în nor, și el va fi semnul legământului între Cuvântul Meu și pământ."},{"v":14,"t":"Și va fi, când voi aduce nori peste pământ, se va arăta curcubeul în nor;"},{"v":15,"t":"și Îmi voi aduce aminte de legământul Meu care este între Cuvântul Meu și voi și tot sufletul viu din toată făptura; și apele nu vor mai fi potop ca să nimicească toată făptura."},{"v":16,"t":"Și curcubeul va fi în nor, și Eu îl voi vedea, ca să-Mi aduc aminte de legământul veșnic dintre Cuvântul Domnului și tot sufletul viu din toată făptura care este pe pământ.”"},{"v":17,"t":"Și a zis Domnul lui Noe: „Acesta este semnul legământului pe care l-am întărit între Cuvântul Meu și toată făptura care este pe pământ.”"},{"v":18,"t":"Și fiii lui Noe care au ieșit din arcă au fost Sem, Ham și Iafet; și Ham este tatăl lui Canaan."},{"v":19,"t":"Aceștia trei sunt fiii lui Noe, și din ei s-a răspândit tot pământul."},{"v":20,"t":"Și Noe a început să fie om lucrător al pământului și a sădit o vie."},{"v":21,"t":"Și a băut din vin și s-a îmbătat și s-a descoperit în mijlocul cortului său."},{"v":22,"t":"Și Ham, tatăl lui Canaan, a văzut goliciunea tatălui său și le-a spus celor doi frați ai săi, în piață."},{"v":23,"t":"Și Sem și Iafet au luat haina și au pus-o pe umerii amândurora și au mers cu spatele și au acoperit goliciunea tatălui lor; și fețele lor erau întoarse, și goliciunea tatălui lor n-au văzut-o."},{"v":24,"t":"Și Noe s-a trezit din vinul lui și a aflat ce-i făcuse fiul său cel mic."},{"v":25,"t":"Și a zis: „Blestemat să fie Canaan! Rob care slujește robilor să fie fraților săi.”"},{"v":26,"t":"Și a zis: „Binecuvântat este Domnul, Dumnezeul lui Sem, și Canaan să le fie rob!"},{"v":27,"t":"Să lărgească Domnul pe Iafet și să facă să locuiască Prezența Lui (Șechina) în cortul lui Sem; și Canaan să le fie rob!”","notes":["Șechina = Prezența divină care locuiește printre oameni; Onkelos redă astfel „și să locuiască în corturile lui Sem”."]},{"v":28,"t":"Și Noe a trăit după potop trei sute cincizeci de ani."},{"v":29,"t":"Și toate zilele lui Noe au fost nouă sute cincizeci de ani; și a murit."}]},{"num":10,"title":"Pereq 10 - Capitolul 10","verses":[{"v":1,"t":"Și acestea sunt istorisirile fiilor lui Noe: Sem, Ham și Iafet; și li s-au născut fii după potop."},{"v":2,"t":"Fiii lui Iafet: Gomer și Magog și Madai și Iavan și Tubal și Meșec și Tiras."},{"v":3,"t":"Și fiii lui Gomer: Așchenaz și Rifat și Togarma."},{"v":4,"t":"Și fiii lui Iavan: Elișa și Tarsis, Chitim și Dodanim."},{"v":5,"t":"Din aceștia s-au despărțit insulele neamurilor în țările lor, fiecare după limba lui, după familiile lor, în neamurile lor."},{"v":6,"t":"Și fiii lui Ham: Cuș și Mițraim și Put și Canaan."},{"v":7,"t":"Și fiii lui Cuș: Seba și Havila și Sabta și Raema și Sabteca; și fiii lui Raema: Șeba și Dedan."},{"v":8,"t":"Și Cuș l-a născut pe Nimrod; el a început să fie un om puternic pe pământ."},{"v":9,"t":"El a fost un om puternic înaintea Domnului; de aceea se zice: „Ca Nimrod, om puternic înaintea Domnului.”"},{"v":10,"t":"Și începutul împărăției lui a fost Babilonul și Erec și Acad și Calne, în țara Babilonului.","notes":["Onkelos redă Șinear prin „țara Babilonului” și Babel prin „Babilon”."]},{"v":11,"t":"Din țara aceea a ieșit Asur și a zidit Ninive și Rehobot-Ir și Calah","notes":["Ediția are aici două note de variantă între paranteze: la „țara” (o altă versiune are ʿeṣa, „sfat”) și la Reḥovot (o altă versiune are reḥove). Ele nu au fost traduse în text."]},{"v":12,"t":"și Resen, între Ninive și Calah; aceasta este cetatea cea mare."},{"v":13,"t":"Și Mițraim i-a născut pe ludiți și pe anamiți și pe lehabiți și pe naftuhiți","notes":["Ediția are o notă între paranteze: în toate cărțile apare forma ebraică Mițrayim în loc de forma aramaică. Traducerea folosește Mițraim."]},{"v":14,"t":"și pe patrusiți și pe casluhiți, din care au ieșit filistenii, și pe caftoriți."},{"v":15,"t":"Și Canaan l-a născut pe Sidon, întâiul lui născut, și pe Het"},{"v":16,"t":"și pe iebusiți și pe amoriți și pe ghirgasiți"},{"v":17,"t":"și pe heviți și pe archiți și pe siniți","notes":["„siniți”: textul aramaic are aici „antosaʾe”, redat cu ebraicul „siniți” (Sini)."]},{"v":18,"t":"și pe arvadiți și pe țemariți și pe hamatiți; și după aceea s-au risipit familiile canaaniților."},{"v":19,"t":"Și hotarul canaaniților a fost de la Sidon, ajungând până la Gherar, până la Gaza; ajungând până la Sodoma și Gomora și Adma și Țeboim, până la Leșa."},{"v":20,"t":"Aceștia sunt fiii lui Ham, după familiile lor, după limbile lor, în țările lor, în neamurile lor."},{"v":21,"t":"Și lui Sem i s-au născut și lui fii; el este tatăl tuturor fiilor lui Eber, fratele lui Iafet cel mare."},{"v":22,"t":"Fiii lui Sem: Elam și Asur și Arpacșad și Lud și Aram."},{"v":23,"t":"Și fiii lui Aram: Uț și Hul și Gheter și Maș."},{"v":24,"t":"Și Arpacșad l-a născut pe Șelah, și Șelah l-a născut pe Eber."},{"v":25,"t":"Și lui Eber i s-au născut doi fii: numele unuia era Peleg, căci în zilele lui s-a împărțit pământul; și numele fratelui său era Ioctan."},{"v":26,"t":"Și Ioctan l-a născut pe Almodad și pe Șelef și pe Hațarmavet și pe Ierah"},{"v":27,"t":"și pe Hadoram și pe Uzal și pe Dicla"},{"v":28,"t":"și pe Obal și pe Abimael și pe Șeba"},{"v":29,"t":"și pe Ofir și pe Havila și pe Iobab; toți aceștia sunt fiii lui Ioctan."},{"v":30,"t":"Și locuința lor a fost de la Meșa, ajungând până la Sefar, muntele răsăritului."},{"v":31,"t":"Aceștia sunt fiii lui Sem, după familiile lor, după limbile lor, în țările lor, în neamurile lor."},{"v":32,"t":"Acestea sunt familiile fiilor lui Noe, după istorisirile lor, în neamurile lor; și din ei s-au despărțit neamurile pe pământ după potop."}]},{"num":11,"title":"Pereq 11 - Capitolul 11","verses":[{"v":1,"t":"Și tot pământul avea o singură limbă și un singur grai."},{"v":2,"t":"Și a fost, când au pornit ei la început, că au găsit o vale în țara Babilonului și s-au așezat acolo."},{"v":3,"t":"Și au zis unul către altul: „Haideți să facem cărămizi și să le ardem în foc!” Și cărămida le-a fost în loc de piatră, iar smoala le-a fost în loc de tencuială.","notes":["Ediția are aici o notă de variantă între paranteze (o altă versiune are doar be-nura, „în foc”), netradusă în text."]},{"v":4,"t":"Și au zis: „Haideți să ne zidim o cetate și un turn al cărui vârf să ajungă până la înălțimea cerurilor, și să ne facem un nume, ca nu cumva să ne risipim pe fața întregului pământ.”"},{"v":5,"t":"Și Domnul S-a descoperit ca să pedepsească faptele cetății și ale turnului pe care îl zideau fiii oamenilor."},{"v":6,"t":"Și a zis Domnul: „Iată, ei sunt un singur popor și toți au o singură limbă, și aceasta este ce au început să facă; și acum nu va fi oprit de la ei nimic din ce plănuiesc să facă."},{"v":7,"t":"Haideți să ne descoperim și să le amestecăm acolo limba, ca să nu mai înțeleagă (fiecare) omul limba semenului său.”","notes":["„(fiecare)”: în ediție cuvântul gevar apare între paranteze, ca variantă alături de enaș; ambele înseamnă „om”."]},{"v":8,"t":"Și Domnul i-a risipit de acolo pe fața întregului pământ, și au încetat să zidească cetatea.","notes":["Ediția are o notă de variantă între paranteze: „și s-a oprit de la a zidi”. Sensul este același."]},{"v":9,"t":"De aceea i s-a pus numele Babel, căci acolo a amestecat Domnul limba întregului pământ și de acolo i-a risipit Domnul pe fața întregului pământ."},{"v":10,"t":"Acestea sunt istorisirile lui Sem: Sem era în vârstă de o sută de ani și l-a născut pe Arpacșad, la doi ani după potop."},{"v":11,"t":"Și Sem a trăit, după ce l-a născut pe Arpacșad, cinci sute de ani; și a născut fii și fiice."},{"v":12,"t":"Și Arpacșad a trăit treizeci și cinci de ani și l-a născut pe Șelah."},{"v":13,"t":"Și Arpacșad a trăit, după ce l-a născut pe Șelah, patru sute trei ani; și a născut fii și fiice."},{"v":14,"t":"Și Șelah a trăit treizeci de ani și l-a născut pe Eber."},{"v":15,"t":"Și Șelah a trăit, după ce l-a născut pe Eber, patru sute trei ani; și a născut fii și fiice."},{"v":16,"t":"Și Eber a trăit treizeci și patru de ani și l-a născut pe Peleg."},{"v":17,"t":"Și Eber a trăit, după ce l-a născut pe Peleg, patru sute treizeci de ani; și a născut fii și fiice."},{"v":18,"t":"Și Peleg a trăit treizeci de ani și l-a născut pe Reu."},{"v":19,"t":"Și Peleg a trăit, după ce l-a născut pe Reu, două sute nouă ani; și a născut fii și fiice."},{"v":20,"t":"Și Reu a trăit treizeci și doi de ani și l-a născut pe Serug."},{"v":21,"t":"Și Reu a trăit, după ce l-a născut pe Serug, două sute șapte ani; și a născut fii și fiice."},{"v":22,"t":"Și Serug a trăit treizeci de ani și l-a născut pe Nahor."},{"v":23,"t":"Și Serug a trăit, după ce l-a născut pe Nahor, două sute de ani; și a născut fii și fiice."},{"v":24,"t":"Și Nahor a trăit douăzeci și nouă de ani și l-a născut pe Terah."},{"v":25,"t":"Și Nahor a trăit, după ce l-a născut pe Terah, o sută nouăsprezece ani; și a născut fii și fiice."},{"v":26,"t":"Și Terah a trăit șaptezeci de ani și l-a născut pe Avram, pe Nahor și pe Haran."},{"v":27,"t":"Și acestea sunt istorisirile lui Terah: Terah l-a născut pe Avram, pe Nahor și pe Haran; și Haran l-a născut pe Lot."},{"v":28,"t":"Și Haran a murit în fața lui Terah, tatăl său, în țara în care se născuse, în Ur al caldeenilor."},{"v":29,"t":"Și Avram și Nahor și-au luat soții: numele soției lui Avram era Sarai, iar numele soției lui Nahor era Milca, fiica lui Haran, tatăl Milcăi și tatăl Iscăi."},{"v":30,"t":"Și Sarai era stearpă; nu avea copil."},{"v":31,"t":"Și Terah l-a luat pe Avram, fiul său, și pe Lot, fiul lui Haran, fiul fiului său, și pe Sarai, nora sa, soția lui Avram, fiul său; și au ieșit împreună din Ur al caldeenilor ca să meargă în țara Canaan; și au ajuns până la Haran și s-au așezat acolo."},{"v":32,"t":"Și zilele lui Terah au fost două sute cinci ani; și Terah a murit în Haran."}]},{"num":12,"title":"Pereq 12 - Capitolul 12","verses":[{"v":1,"t":"Și a zis Domnul lui Avram: „Du-te din țara ta și din locul nașterii tale și din casa tatălui tău, în țara pe care ți-o voi arăta."},{"v":2,"t":"Și te voi face un popor mare și te voi binecuvânta și voi face mare numele tău, și vei fi binecuvântat."},{"v":3,"t":"Și voi binecuvânta pe cei care te binecuvântează, iar pe cel care te blestemă îl voi blestema; și prin tine se vor binecuvânta toate familiile pământului.”"},{"v":4,"t":"Și Avram a plecat, așa cum îi vorbise Domnul, și Lot a plecat cu el. Și Avram era în vârstă de șaptezeci și cinci de ani când a ieșit din Haran."},{"v":5,"t":"Și Avram a luat-o pe Sarai, soția lui, și pe Lot, fiul fratelui său, și toate averile pe care le dobândiseră și sufletele pe care le aduseseră sub ascultarea Torei în Haran; și au ieșit ca să meargă în țara Canaan și au ajuns în țara Canaan.","notes":["„sufletele pe care le aduseseră sub ascultarea Torei”: Onkelos explică „sufletele pe care le făcuseră” ca pe convertiții aduși la Tora."]},{"v":6,"t":"Și Avram a trecut prin țară până la locul Sihem, până la câmpia More. Și canaanitul era atunci în țară."},{"v":7,"t":"Și Domnul i S-a descoperit lui Avram și i-a zis: „Urmașilor tăi le voi da țara aceasta.” Și a zidit acolo un altar înaintea Domnului, care i Se descoperise."},{"v":8,"t":"Și s-a mutat de acolo spre muntele de la răsărit de Betel și și-a întins cortul, cu Betelul la apus și Ai la răsărit; și a zidit acolo un altar înaintea Domnului și s-a rugat în numele Domnului."},{"v":9,"t":"Și Avram a pornit, mergând și pornind spre sud."},{"v":10,"t":"Și a fost foamete în țară, și Avram a coborât în Egipt („Mițrayim”) ca să locuiască acolo ca străin, căci foametea era grea în țară."},{"v":11,"t":"Și a fost, când s-a apropiat să intre în Egipt („Mițrayim”), că i-a zis Sarei, soției lui: „Iată, acum știu că ești o femeie frumoasă la înfățișare."},{"v":12,"t":"Și va fi, când te vor vedea egiptenii, că vor zice: «Aceasta este soția lui», și mă vor ucide pe mine, iar pe tine te vor lăsa în viață.","notes":["Ediția are o notă de variantă între paranteze: ari („că”) în loc de kad („când”), netradusă în text."]},{"v":13,"t":"Spune, te rog, că ești sora mea, ca să-mi fie bine pentru tine și să rămână sufletul meu în viață datorită cuvintelor tale.”"},{"v":14,"t":"Și a fost, când a intrat Avram în Egipt („Mițrayim”), că egiptenii au văzut că femeia era foarte frumoasă."},{"v":15,"t":"Și au văzut-o căpeteniile lui Faraon și au lăudat-o înaintea lui Faraon; și femeia a fost dusă în casa lui Faraon."},{"v":16,"t":"Și lui Avram i-a făcut bine din pricina ei; și a avut oi și boi și măgari și robi și roabe și măgărițe și cămile."},{"v":17,"t":"Și Domnul a adus lovituri mari asupra lui Faraon și asupra oamenilor casei lui, din pricina Sarei, soția lui Avram."},{"v":18,"t":"Și Faraon l-a chemat pe Avram și i-a zis: „Ce mi-ai făcut? De ce nu mi-ai spus că este soția ta?"},{"v":19,"t":"De ce ai zis: «Este sora mea», așa încât am luat-o să-mi fie soție? Și acum, iată soția ta; ia-o și du-te.”"},{"v":20,"t":"Și Faraon a poruncit unor oameni în privința lui, și l-au însoțit pe el și pe soția lui și tot ce avea."}]},{"num":13,"title":"Pereq 13 - Capitolul 13","verses":[{"v":1,"t":"Și Avram a urcat din Egipt („Mițrayim”), el și soția lui și tot ce avea, și Lot cu el, spre sud."},{"v":2,"t":"Și Avram era foarte bogat în vite, în argint și în aur."},{"v":3,"t":"Și a mers din popas în popas, din sud până la Betel, până la locul unde își întinsese cortul la început, între Betel și Ai,"},{"v":4,"t":"la locul altarului pe care îl făcuse acolo la început; și Avram s-a rugat acolo în numele Domnului."},{"v":5,"t":"Și Lot, care mergea cu Avram, avea și el oi și boi și corturi."},{"v":6,"t":"Și țara nu-i putea purta ca să locuiască împreună, căci averea lor era mare și nu puteau locui împreună."},{"v":7,"t":"Și a fost ceartă între păstorii vitelor lui Avram și păstorii vitelor lui Lot. Și canaanitul și fereziții locuiau atunci în țară."},{"v":8,"t":"Și Avram i-a zis lui Lot: „Să nu fie, te rog, ceartă între mine și tine și între păstorii mei și păstorii tăi, căci suntem oameni frați."},{"v":9,"t":"Nu este oare toată țara înaintea ta? Desparte-te, te rog, de mine: dacă tu vei merge la nord, eu voi merge la sud; iar dacă tu vei merge la sud, eu voi merge la nord.”"},{"v":10,"t":"Și Lot și-a ridicat ochii și a văzut toată câmpia Iordanului, că era toată un loc udat, înainte ca Domnul să nimicească Sodoma și Gomora, ca grădina Domnului, ca țara Egiptului („Mițrayim”), ajungând până la Țoar."},{"v":11,"t":"Și Lot și-a ales toată câmpia Iordanului; și Lot a pornit spre răsărit, și s-au despărțit unul de altul."},{"v":12,"t":"Avram a locuit în țara Canaan, iar Lot a locuit în cetățile câmpiei și și-a întins cortul până la Sodoma."},{"v":13,"t":"Și oamenii Sodomei erau răi cu averea lor și păcătoși cu trupurile lor, foarte mult, înaintea Domnului."},{"v":14,"t":"Și Domnul i-a zis lui Avram, după ce Lot se despărțise de el: „Ridică-ți, te rog, ochii și privește din locul în care ești spre nord și spre sud, spre răsărit și spre apus."},{"v":15,"t":"Căci toată țara pe care o vezi ți-o voi da ție și urmașilor tăi, pe veci."},{"v":16,"t":"Și voi face pe urmașii tăi mulți ca țărâna pământului; așa cum nu este cu putință omului să numere țărâna pământului, tot așa nici urmașii tăi nu vor putea fi numărați."},{"v":17,"t":"Ridică-te, umblă prin țară în lungul și în latul ei, căci ție ți-o voi da.”"},{"v":18,"t":"Și Avram și-a întins cortul și a venit și a locuit în câmpiile lui Mamre, care sunt la Hebron; și a zidit acolo un altar înaintea Domnului."}]},{"num":14,"title":"Pereq 14 - Capitolul 14","verses":[{"v":1,"t":"Și a fost, în zilele lui Amrafel, regele Babilonului, ale lui Arioc, regele lui Elasar, ale lui Chedorlaomer, regele Elamului, și ale lui Tidal, regele neamurilor,"},{"v":2,"t":"că au pornit război împotriva lui Bera, regele Sodomei, și împotriva lui Birșa, regele Gomorei, a lui Șineab, regele lui Adma, a lui Șemeber, regele lui Țeboim, și a regelui lui Bela, adică Țoar.","notes":["Ediția are o notă de variantă între paranteze: ʿavadu („au făcut”) în loc de sadaru („au rânduit”)."]},{"v":3,"t":"Toți aceștia s-au adunat în câmpia câmpurilor, adică locul Mării Sărate."},{"v":4,"t":"Doisprezece ani i-au slujit lui Chedorlaomer, iar în al treisprezecelea an s-au răzvrătit."},{"v":5,"t":"Și în al paisprezecelea an a venit Chedorlaomer și regii care erau cu el și i-au lovit pe uriașii din Așterot-Carnaim și pe cei puternici din Hamta și pe cei înfricoșători din Șave-Chiriataim","notes":["Onkelos redă refaim prin „uriași”, zuzim prin „cei puternici” și Ham prin Hamta; emiți (emim) este redat prin emtane.","Ebraica are „emiții”; Onkelos redă prin „cei înfricoșători”."]},{"v":6,"t":"și pe horiți în muntele lor, Seir, până la câmpia Paran, care este lângă pustiu."},{"v":7,"t":"Și s-au întors și au venit la câmpia împărțirii judecății, adică Rekam, și au lovit tot ținutul amaleciților și chiar pe amoritul care locuia în Ein-Ghedi.","notes":["„câmpia împărțirii judecății” (Mișar Pelug Dina): așa redă Onkelos En-Mișpat; Cades este numit Rekam."]},{"v":8,"t":"Și a ieșit regele Sodomei și regele Gomorei și regele lui Adma și regele lui Țeboim și regele lui Bela, adică Țoar, și s-au rânduit la luptă împotriva lor în câmpia câmpurilor,"},{"v":9,"t":"împotriva lui Chedorlaomer, regele Elamului, a lui Tidal, regele neamurilor, a lui Amrafel, regele Babilonului, și a lui Arioc, regele lui Elasar: patru regi împotriva a cinci."},{"v":10,"t":"Și câmpia câmpurilor era plină de fântâni, fântâni care scoteau smoală; și regii Sodomei și Gomorei au fugit și au căzut acolo, iar cei care au rămas au fugit la munte."},{"v":11,"t":"Și au luat ca pradă toată averea Sodomei și Gomorei și toată hrana lor și au plecat."},{"v":12,"t":"Și l-au luat ca prizonier pe Lot și averea lui, pe fiul fratelui lui Avram, și au plecat; iar el locuia în Sodoma."},{"v":13,"t":"Și a venit unul care scăpase și i-a spus lui Avram, evreul; și el locuia în câmpiile lui Mamre, amoritul, fratele lui Eșcol și fratele lui Aner; și ei erau oamenii legământului lui Avram."},{"v":14,"t":"Și Avram a auzit că fratele lui fusese luat prizonier și i-a înarmat pe tinerii lui, născuți în casa lui, trei sute optsprezece, și i-a urmărit până la Dan."},{"v":15,"t":"Și s-a împărțit împotriva lor noaptea, el și robii lui, și i-a lovit și i-a urmărit până la Hoba, care este la nord de Damasc."},{"v":16,"t":"Și a adus înapoi toată averea; și pe Lot, fiul fratelui său, și averea lui le-a adus înapoi, și pe femei și pe popor."},{"v":17,"t":"Și regele Sodomei a ieșit în întâmpinarea lui, după ce s-a întors de la lovirea lui Chedorlaomer și a regilor care erau cu el, în câmpia Mifna, adică locul hipodromului regelui.","notes":["Valea Șave este redată „câmpia Mifna”, iar „valea regelui” este „locul hipodromului (bet risa) regelui”."]},{"v":18,"t":"Și Malchițedec, regele Ierusalimului, a scos pâine și vin; și el slujea înaintea Dumnezeului Preaînalt."},{"v":19,"t":"Și l-a binecuvântat și a zis: „Binecuvântat este Avram de Dumnezeul Preaînalt, a Cărui stăpânire sunt cerurile și pământul."},{"v":20,"t":"Și binecuvântat este Dumnezeul Preaînalt, care i-a dat pe dușmanii tăi în mâna ta.” Și i-a dat zeciuială din toate."},{"v":21,"t":"Și regele Sodomei i-a zis lui Avram: „Dă-mi sufletele, iar averea (ia-o) ia-ți-o ție.”","notes":["„(ia-o)”: ediția are două verbe, sav („ia”) între paranteze și devar („ia, du”); traducerea păstrează ambele."]},{"v":22,"t":"Și Avram i-a zis regelui Sodomei: „Mi-am ridicat mâna în rugăciune înaintea Domnului, Dumnezeul Preaînalt, a Cărui stăpânire sunt cerurile și pământul,"},{"v":23,"t":"că nu voi lua nici un fir, nici o curea de încălțăminte, nimic din ce este al tău, ca să nu zici: «Eu l-am îmbogățit pe Avram»;"},{"v":24,"t":"afară (în afară) de ce au mâncat tinerii și de partea oamenilor care au mers cu mine: Aner, Eșcol și Mamre; ei să-și primească partea lor.”","notes":["„(în afară)”: ediția are bar („afară de”) între paranteze, ca variantă a lui leḥod („numai”)."]}]},{"num":15,"title":"Pereq 15 - Capitolul 15","verses":[{"v":1,"t":"După lucrurile acestea a fost cuvântul Domnului către Avram în profeție, zicând: „Nu te teme, Avram; Cuvântul Meu este tăria ta, răsplata ta este foarte mare.”"},{"v":2,"t":"Și Avram a zis: „Doamne Dumnezeule, ce-mi vei da? Eu merg fără copil, iar acest îngrijitor din casa mea este damascenul Eliezer.”"},{"v":3,"t":"Și Avram a zis: „Iată, mie nu mi-ai dat copil, și iată, un fiu al casei mele mă va moșteni.”"},{"v":4,"t":"Și iată, cuvântul Domnului a fost către el, zicând: „Nu acesta te va moșteni, ci un fiu pe care îl vei naște, el te va moșteni.”"},{"v":5,"t":"Și l-a scos afară și a zis: „Privește, te rog, la ceruri și numără stelele, dacă le poți număra.” Și i-a zis: „Așa vor fi urmașii tăi.”"},{"v":6,"t":"Și el a crezut în Cuvântul Domnului, și El i-a socotit aceasta ca merit.","notes":["„ca merit” (le-zakhu): Onkelos redă astfel ebraicul ṣedaqa („dreptate”)."]},{"v":7,"t":"Și i-a zis: „Eu sunt Domnul, care te-am scos din Ur al caldeenilor, ca să-ți dau țara aceasta s-o moștenești.”"},{"v":8,"t":"Și el a zis: „Doamne Dumnezeule, prin ce voi ști că o voi moșteni?”"},{"v":9,"t":"Și i-a zis: „Adu înaintea Mea trei viței și trei capre și trei berbeci, o turturea și un pui de porumbel.”"},{"v":10,"t":"Și a adus înaintea Lui toate acestea și le-a despicat pe din două și a pus fiecare jumătate în fața celeilalte; dar păsările nu le-a despicat."},{"v":11,"t":"Și păsările au coborât pe bucăți, și Avram le-a alungat.","notes":["Ebraica are „pe trupuri”; Onkelos are „pe bucăți” (cele despicate)."]},{"v":12,"t":"Și pe când soarele era să apună, un somn a căzut peste Avram, și iată, o groază, o mare întunecime, a căzut peste el."},{"v":13,"t":"Și i-a zis lui Avram: „Să știi bine că urmașii tăi vor fi străini într-o țară care nu este a lor și vor fi puși la muncă și asupriți patru sute de ani."},{"v":14,"t":"Dar și pe poporul căruia îi vor sluji îl voi judeca Eu, iar după aceea vor ieși cu avere mare."},{"v":15,"t":"Iar tu vei merge la părinții tăi în pace; vei fi îngropat la o bătrânețe bună."},{"v":16,"t":"Și generația a patra se va întoarce aici, căci vina amoritului nu este încă deplină.”"},{"v":17,"t":"Și a fost, după ce soarele a apus și s-a făcut întuneric, iată, un cuptor fumegând și o flacără de foc a trecut printre bucățile acestea."},{"v":18,"t":"În ziua aceea a încheiat Domnul un legământ cu Avram, zicând: „Urmașilor tăi le-am dat țara aceasta, de la râul Egiptului („Mițrayim”) până la râul cel mare, râul Eufrat:"},{"v":19,"t":"pe șalmei și pe cheniziți și pe cadmoniți","notes":["Ebraica are „chenitul”; Onkelos redă prin „șalmeii” (șalmaé), un popor arab."]},{"v":20,"t":"și pe hetiți și pe ferezi și pe uriași","notes":["Ebraica are „refaimii”; Onkelos redă prin „uriașii”."]},{"v":21,"t":"și pe amoriți și pe canaaniți și pe ghirgasiți și pe iebusiți.”"}]},{"num":16,"title":"Pereq 16 - Capitolul 16","verses":[{"v":1,"t":"Și Sarai, soția lui Avram, nu-i născuse copii; și ea avea o roabă egipteancă, al cărei nume era Agar."},{"v":2,"t":"Și Sarai i-a zis lui Avram: „Iată, Domnul m-a oprit să nasc; intră, te rog, la roaba mea; poate voi fi zidită prin ea.” Și Avram a ascultat cuvântul Sarei."},{"v":3,"t":"Și Sarai, soția lui Avram, a luat-o pe Agar egipteanca, roaba ei, după zece ani de când locuia Avram în țara Canaan, și a dat-o lui Avram, bărbatul ei, să-i fie soție."},{"v":4,"t":"Și el a intrat la Agar, și ea a rămas însărcinată; și când a văzut că a rămas însărcinată, stăpâna ei a devenit neînsemnată în ochii ei."},{"v":5,"t":"Și Sarai i-a zis lui Avram: „Judecata mea este asupra ta! Eu ți-am dat roaba mea, și ea a văzut că a rămas însărcinată, și am devenit neînsemnată în ochii ei. Să judece Domnul între mine și tine!”"},{"v":6,"t":"Și Avram i-a zis Sarei: „Iată, roaba ta este în mâna ta; fă-i ce este bine în ochii tăi.” Și Sarai a asuprit-o, și ea a fugit dinaintea ei."},{"v":7,"t":"Și un înger al Domnului a găsit-o lângă un izvor de apă în pustiu, lângă izvorul de pe drumul spre Hagra."},{"v":8,"t":"Și a zis: „Agar, roaba Sarei, de unde vii și unde mergi?” Și ea a zis: „Fug (am fugit) dinaintea Sarei, stăpâna mea.”","notes":["„(am fugit)”: ediția are două forme, ʿaraqa („fug”) și ʿaraqit („am fugit”) între paranteze; traducerea le păstrează pe amândouă."]},{"v":9,"t":"Și îngerul Domnului i-a zis: „Întoarce-te la stăpâna ta și supune-te sub mâinile ei.”"},{"v":10,"t":"Și îngerul Domnului i-a zis: „Voi înmulți foarte mult pe fiii tăi, și nu vor putea fi numărați de mulțime.”"},{"v":11,"t":"Și îngerul Domnului i-a zis: „Iată, ești însărcinată și vei naște un fiu și îi vei pune numele Ismael, căci Domnul a primit rugăciunea ta."},{"v":12,"t":"Și el va fi un răzvrătit printre oameni; el va avea nevoie de toți, și toți fiii oamenilor vor avea nevoie de el; și în fața tuturor fraților săi va locui.”"},{"v":13,"t":"Și ea s-a rugat în numele Domnului, care îi vorbise, și a zis: „Tu ești Dumnezeul care vede totul”; căci a zis: „Oare chiar aici am început să văd, după ce mi S-a descoperit?”","notes":["Ediția are o notă de variantă între paranteze (o altă versiune: ha-af ana, „oare și eu…”), netradusă în text."]},{"v":14,"t":"De aceea fântânii i s-a pus numele „Fântâna unde s-a arătat îngerul cel viu”; iată, ea este între Rekam și Hagra."},{"v":15,"t":"Și Agar i-a născut lui Avram un fiu; și Avram a pus fiului său, pe care i-l născuse Agar, numele Ismael."},{"v":16,"t":"Și Avram era în vârstă de optzeci și șase de ani când i l-a născut Agar pe Ismael lui Avram."}]},{"num":17,"title":"Pereq 17 - Capitolul 17","verses":[{"v":1,"t":"Și Avram era în vârstă de nouăzeci și nouă de ani; și Domnul i S-a descoperit lui Avram și i-a zis: „Eu sunt Dumnezeul Atotputernic (El Șadai); slujește înaintea Mea și fii desăvârșit."},{"v":2,"t":"Și voi pune legământul Meu între Cuvântul Meu și tine și te voi înmulți foarte, foarte mult.”"},{"v":3,"t":"Și Avram a căzut pe fața lui, și Domnul i-a vorbit, zicând:"},{"v":4,"t":"„Eu, iată, (încheiat este) legământul Meu cu tine, și vei fi tatăl unei mulțimi de neamuri.","notes":["„(încheiat este)”: ediția are cuvântul gezar între paranteze, ca variantă de text."]},{"v":5,"t":"Și nu se va mai numi numele tău Avram, ci numele tău va fi Avraam, căci te-am făcut tatăl unei mulțimi de neamuri."},{"v":6,"t":"Și te voi face foarte, foarte roditor și te voi face adunări de popoare, și regi care stăpânesc peste neamuri vor ieși din tine."},{"v":7,"t":"Și voi întări legământul Meu între Cuvântul Meu și tine și urmașii tăi după tine, în generațiile lor, ca legământ veșnic, ca să-ți fiu Dumnezeu ție și urmașilor tăi după tine."},{"v":8,"t":"Și îți voi da ție și urmașilor tăi după tine țara în care locuiești ca străin, toată țara Canaan, ca moștenire veșnică; și le voi fi Dumnezeu.”"},{"v":9,"t":"Și Domnul i-a zis lui Avraam: „Iar tu să păzești legământul Meu, tu și urmașii tăi după tine, în generațiile lor."},{"v":10,"t":"Acesta este legământul Meu pe care să-l păziți între Cuvântul Meu și voi și urmașii tăi după tine: să vă fie tăiată împrejur orice parte bărbătească."},{"v":11,"t":"Și să tăiați carnea prepuțului vostru, și va fi semnul legământului între Cuvântul Meu și voi."},{"v":12,"t":"Și la vârsta de opt zile să vă fie tăiată împrejur orice parte bărbătească, în generațiile voastre, cel născut în casă și cel cumpărat cu argint de la orice străin, care nu este din urmașii tăi."},{"v":13,"t":"Să fie tăiat împrejur negreșit cel născut în casa ta și cel cumpărat cu argintul tău; și legământul Meu va fi în carnea voastră ca legământ veșnic."},{"v":14,"t":"Iar cel netăiat împrejur, partea bărbătească căreia nu i se va tăia carnea prepuțului, acel suflet va fi nimicit din poporul lui; a călcat legământul Meu.”"},{"v":15,"t":"Și Domnul i-a zis lui Avraam: „Pe Sarai, soția ta, să n-o mai numești Sarai, căci Sara este numele ei."},{"v":16,"t":"Și o voi binecuvânta și îți voi da și din ea un fiu; și o voi binecuvânta, și ea va deveni adunări de popoare; regi care stăpânesc peste neamuri vor ieși din ea.”"},{"v":17,"t":"Și Avraam a căzut pe fața lui și s-a bucurat și a zis în inima lui: „Oare unui om de o sută de ani i se va naște un copil? Și Sara, care are nouăzeci de ani, va naște?”"},{"v":18,"t":"Și Avraam a zis înaintea Domnului: „O, de ar trăi Ismael înaintea Ta!”"},{"v":19,"t":"Și Domnul a zis: „Cu adevărat, Sara, soția ta, îți va naște un fiu și îi vei pune numele Isaac; și voi întări legământul Meu cu el ca legământ veșnic pentru urmașii lui după el."},{"v":20,"t":"Iar pentru Ismael ți-am primit rugăciunea: iată, l-am binecuvântat și îl voi face roditor și îl voi înmulți foarte, foarte mult; doisprezece căpetenii va naște, și îl voi face un popor mare."},{"v":21,"t":"Dar legământul Meu îl voi întări cu Isaac, pe care ți-l va naște Sara la vremea aceasta, în anul celălalt.”"},{"v":22,"t":"Și a isprăvit de vorbit cu el, și Slava Domnului S-a înălțat de la Avraam.","notes":["„Slava Domnului” (yeqara de-Adonai): Onkelos redă „Dumnezeu S-a înălțat” prin „Slava Domnului S-a înălțat”."]},{"v":23,"t":"Și Avraam l-a luat pe Ismael, fiul său, și pe toți cei născuți în casa lui și pe toți cei cumpărați cu argintul lui, pe orice parte bărbătească dintre oamenii casei lui Avraam, și le-a tăiat carnea prepuțului chiar în ziua aceea, așa cum îi vorbise Domnul."},{"v":24,"t":"Și Avraam era în vârstă de nouăzeci și nouă de ani când și-a tăiat carnea prepuțului."},{"v":25,"t":"Și Ismael, fiul său, era în vârstă de treisprezece ani când și-a tăiat carnea prepuțului."},{"v":26,"t":"Chiar în ziua aceea a fost tăiat împrejur (a tăiat împrejur) Avraam, și Ismael, fiul său.","notes":["Ediția are aici, ca și la 17:27, două forme verbale (una între paranteze): pasivă („a fost tăiat împrejur”) și activă („a tăiat împrejur”); traducerea le păstrează pe amândouă."]},{"v":27,"t":"Și toți oamenii casei lui, cei născuți în casă și cei cumpărați cu argint de la străini, au fost tăiați împrejur (au tăiat împrejur) împreună cu el."}]},{"num":18,"title":"Pereq 18 - Capitolul 18","verses":[{"v":1,"t":"Și Domnul i S-a descoperit în câmpiile lui Mamre; și el ședea la intrarea cortului, în arșița zilei."},{"v":2,"t":"Și și-a ridicat ochii și a văzut, și iată, trei oameni stăteau lângă el; și a văzut și a alergat în întâmpinarea lor de la intrarea cortului și s-a plecat până la pământ.","notes":["Ediția repetă cuvântul gavrin („oameni”) ca notă de variantă între paranteze; nu schimbă sensul."]},{"v":3,"t":"Și a zis: „Doamne, dacă am găsit acum îndurare înaintea Ta, nu trece, te rog, pe lângă robul Tău.","notes":["Ediția are o notă de variantă între paranteze: „în ochii Tăi” în loc de „înaintea Ta”."]},{"v":4,"t":"Să se ia, vă rog, puțină apă, și spălați-vă picioarele și rezemați-vă sub copac."},{"v":5,"t":"Și voi lua o bucată de pâine, și întăriți-vă inima; după aceea veți trece mai departe, căci pentru aceasta ați trecut pe la robul vostru.” Și ei au zis: „Fă așa cum ai spus.”"},{"v":6,"t":"Și Avraam s-a grăbit în cort la Sara și a zis: „Grăbește-te, trei sea de făină de grâu aleasă; frământă și fă turte.”"},{"v":7,"t":"Și Avraam a alergat la vite și a luat un vițel fraged și bun și l-a dat tânărului, și acesta s-a grăbit să-l pregătească."},{"v":8,"t":"Și a luat unt și lapte și vițelul pe care îl pregătise și le-a pus înaintea lor; și el îi slujea sub copac, și ei au mâncat."},{"v":9,"t":"Și i-au zis: „Unde este Sara, soția ta?” Și el a zis: „Iată, în cort.”"},{"v":10,"t":"Și a zis: „Mă voi întoarce negreșit la tine la vremea aceasta, când veți fi în viață, și iată, Sara, soția ta, va avea un fiu.” Și Sara asculta la intrarea cortului, care era în spatele lui."},{"v":11,"t":"Și Avraam și Sara erau bătrâni, înaintați în zile; încetase să mai fie pentru Sara rânduiala femeilor."},{"v":12,"t":"Și Sara a râs în sinea ei, zicând: „După ce am îmbătrânit, să am iar tinerețe? Și stăpânul meu este bătrân!”"},{"v":13,"t":"Și Domnul i-a zis lui Avraam: „De ce a râs Sara, zicând: «Oare cu adevărat voi naște, când sunt bătrână?»"},{"v":14,"t":"Este oare ceva ascuns dinaintea Domnului? La vremea hotărâtă Mă voi întoarce la tine, la vremea aceasta, când veți fi în viață, și Sara va avea un fiu.”"},{"v":15,"t":"Și Sara a tăgăduit, zicând: „N-am râs”, căci se temea. Și El a zis: „Nu, ci ai râs.”"},{"v":16,"t":"Și oamenii s-au ridicat de acolo și au privit spre fața Sodomei; și Avraam mergea cu ei ca să-i petreacă."},{"v":17,"t":"Și Domnul a zis: „Să ascund Eu de Avraam ce voi face,"},{"v":18,"t":"când Avraam va deveni negreșit un popor mare și puternic, și prin el se vor binecuvânta toate neamurile pământului?"},{"v":19,"t":"Căci este descoperit înaintea Mea că el va porunci fiilor lui și casei lui după el să păzească căile care sunt drepte înaintea Domnului, ca să facă dreptate și judecată, pentru ca Domnul să aducă asupra lui Avraam ce a vorbit despre el.”","notes":["Ediția are o notă între paranteze: varianta citată de Ramban (yedaʿtineh, „L-am cunoscut”). Textul principal are „este descoperit înaintea Mea”."]},{"v":20,"t":"Și Domnul a zis: „Strigătul Sodomei și Gomorei s-a înmulțit, și păcatul lor s-a îngreuiat foarte mult."},{"v":21,"t":"Mă voi descoperi acum și voi judeca: dacă au făcut după strigătul lor care a ajuns înaintea Mea, le voi face nimicire; iar dacă se pocăiesc, nu-i voi pedepsi.”"},{"v":22,"t":"Și oamenii s-au întors de acolo și s-au dus spre Sodoma; iar Avraam încă slujea în rugăciune înaintea Domnului."},{"v":23,"t":"Și Avraam s-a apropiat și a zis: „Oare în mânie îl vei nimici pe cel drept împreună cu cel rău?"},{"v":24,"t":"Poate sunt cincizeci de drepți în mijlocul cetății; oare în mânie vei nimici și nu vei ierta locul pentru cei cincizeci de drepți care sunt în ea?"},{"v":25,"t":"Adevăr este judecata Ta, departe de a face un astfel de lucru, să omori pe cel drept împreună cu cel rău, și să fie cel drept ca cel rău; adevăr este judecata Ta. Oare Judecătorul întregului pământ să nu facă judecată?”"},{"v":26,"t":"Și Domnul a zis: „Dacă voi găsi în Sodoma cincizeci de drepți în mijlocul cetății, voi ierta tot locul pentru ei.”"},{"v":27,"t":"Și Avraam a răspuns și a zis: „Iată, am început să vorbesc înaintea Domnului, deși eu sunt țărână și cenușă."},{"v":28,"t":"Poate le vor lipsi celor cincizeci de drepți cinci; vei nimici oare pentru cei cinci toată cetatea?” Și El a zis: „Nu voi nimici, dacă voi găsi acolo patruzeci și cinci.”"},{"v":29,"t":"Și a mai vorbit încă înaintea Lui și a zis: „Poate se vor găsi acolo patruzeci.” Și El a zis: „Nu voi face nimicire pentru cei patruzeci.”"},{"v":30,"t":"Și a zis: „Să nu Se mânie, te rog, Domnul, și voi vorbi: poate se vor găsi acolo treizeci.” Și El a zis: „Nu voi face nimicire, dacă voi găsi acolo treizeci.”","notes":["La 18:30 și 18:32 ediția are o notă de variantă între paranteze: „mânia Domnului”, în loc de „înaintea Domnului”. Traducerea „să nu Se mânie Domnul” redă sensul ambelor."]},{"v":31,"t":"Și a zis: „Iată, am început să vorbesc înaintea Domnului: poate se vor găsi acolo douăzeci.” Și El a zis: „Nu voi nimici pentru cei douăzeci.”"},{"v":32,"t":"Și a zis: „Să nu Se mânie, te rog, Domnul, și voi vorbi numai de data aceasta: poate se vor găsi acolo zece.” Și El a zis: „Nu voi nimici pentru cei zece.”"},{"v":33,"t":"Și Slava Domnului S-a înălțat după ce a isprăvit de vorbit cu Avraam; și Avraam s-a întors la locul lui."}]},{"num":19,"title":"Pereq 19 - Capitolul 19","verses":[{"v":1,"t":"Și cei doi îngeri au venit la Sodoma seara; și Lot ședea la poarta Sodomei. Și Lot i-a văzut și s-a ridicat în întâmpinarea lor și s-a plecat cu fața la pământ."},{"v":2,"t":"Și a zis: „Vă rog acum, domnii mei, abateți-vă, vă rog, la casa robului vostru și rămâneți peste noapte și spălați-vă picioarele; și vă veți scula devreme și vă veți duce în drumul vostru.” Și ei au zis: „Nu, ci vom înnopta în piață.”"},{"v":3,"t":"Și el a stăruit foarte mult la ei, și s-au abătut la el și au intrat în casa lui; și le-a făcut un ospăț și le-a copt azime, și au mâncat."},{"v":4,"t":"Încă nu se culcaseră, când oamenii cetății, oamenii Sodomei, au înconjurat casa, de la tânăr până la bătrân, tot poporul, de la un capăt la altul."},{"v":5,"t":"Și l-au strigat pe Lot și i-au zis: „Unde sunt oamenii care au venit la tine astă-noapte? Scoate-i la noi, ca să-i cunoaștem.”"},{"v":6,"t":"Și Lot a ieșit la ei la intrare și a închis ușa după el."},{"v":7,"t":"Și a zis: „Vă rog acum, frații mei, nu faceți rău."},{"v":8,"t":"Iată, am două fiice care n-au cunoscut bărbat; să le scot, vă rog, la voi, și faceți-le ce este bine în ochii voștri; numai oamenilor acestora să nu le faceți nimic, căci pentru aceasta au intrat sub umbra acoperișului meu.”"},{"v":9,"t":"Și ei au zis: „Dă-te la o parte!” Și au zis: „Unul singur a venit să locuiască aici ca străin și iată că judecă! Acum îți vom face mai rău decât lor.” Și au năvălit asupra omului, asupra lui Lot, foarte tare, și s-au apropiat să spargă ușa."},{"v":10,"t":"Și oamenii și-au întins mâinile și l-au adus pe Lot la ei în casă și au închis ușa."},{"v":11,"t":"Iar pe oamenii care erau la intrarea casei i-au lovit cu orbire, de la mic până la mare, și s-au trudit să găsească intrarea.","notes":["„orbire” (šabrire): orbire bruscă sau orbire a minții."]},{"v":12,"t":"Și oamenii i-au zis lui Lot: „Pe cine mai ai aici? Ginere, fiii tăi și fiicele tale și pe toți cei care sunt ai tăi în cetate, scoate-i din locul acesta,"},{"v":13,"t":"căci noi vom nimici locul acesta, pentru că strigătul lor s-a înmulțit înaintea Domnului, și Domnul ne-a trimis să-l nimicim.”"},{"v":14,"t":"Și Lot a ieșit și a vorbit cu ginerii lui, care urmau să-i ia fiicele, și a zis: „Sculați-vă, ieșiți din locul acesta, căci Domnul va nimici cetatea.” Dar el a fost în ochii ginerilor lui ca unul care glumește."},{"v":15,"t":"Și când s-a ridicat zorile, îngerii l-au zorit pe Lot, zicând: „Scoală-te, ia-ți soția și cele două fiice ale tale care se află credincioase cu tine, ca să nu pieri în păcatele cetății.”"},{"v":16,"t":"Și el zăbovea; și oamenii l-au apucat de mână, pe el și pe soția lui și pe cele două fiice ale lui, pentru că Domnul S-a îndurat de el; și l-au scos și l-au lăsat afară din cetate."},{"v":17,"t":"Și a fost, când i-au scos afară, că a zis: „Cruță-ți sufletul! Nu privi înapoia ta și nu te opri în toată câmpia; scapă la munte, ca să nu pieri.”"},{"v":18,"t":"Și Lot le-a zis: „Vă rog acum, domnii mei!"},{"v":19,"t":"Iată, robul tău a găsit acum îndurare înaintea ta și ai făcut mare bunătatea pe care ai făcut-o cu mine, păstrându-mi sufletul în viață; dar eu nu pot să scap la munte, ca nu cumva să mă ajungă nenorocirea și să mor."},{"v":20,"t":"Iată, cetatea aceasta este aproape ca să fug acolo, și este mică; să scap, te rog, acolo; nu este oare mică? Și sufletul meu va rămâne în viață.”"},{"v":21,"t":"Și i-a zis: „Iată, ți-am primit cererea și în privința aceasta, ca să nu răstorn cetatea pentru care ai cerut."},{"v":22,"t":"Grăbește-te, scapă acolo, căci nu pot face nimic până nu ajungi acolo.” De aceea s-a pus cetății numele Țoar."},{"v":23,"t":"Soarele a răsărit peste pământ, și Lot a intrat în Țoar."},{"v":24,"t":"Și Domnul a făcut să plouă peste Sodoma și peste Gomora pucioasă și foc de la Domnul, din ceruri."},{"v":25,"t":"Și a răsturnat cetățile acestea și toată câmpia și pe toți locuitorii cetăților și vegetația pământului."},{"v":26,"t":"Și soția lui a privit înapoia lui și a devenit un stâlp de sare."},{"v":27,"t":"Și Avraam s-a sculat dis-de-dimineață și a mers la locul unde slujise în rugăciune înaintea Domnului."},{"v":28,"t":"Și a privit spre fața Sodomei și Gomorei și spre toată fața țării câmpiei; și a văzut, și iată, fumul țării se ridica precum fumul unui cuptor."},{"v":29,"t":"Și a fost, când a nimicit Domnul cetățile câmpiei, că Domnul Și-a adus aminte de Avraam și l-a trimis pe Lot din mijlocul răsturnării, când a răsturnat cetățile în care locuia Lot."},{"v":30,"t":"Și Lot a urcat din Țoar și a locuit la munte, și cele două fiice ale lui cu el, căci se temea să locuiască în Țoar; și a locuit într-o peșteră, el și cele două fiice ale lui."},{"v":31,"t":"Și cea mai mare i-a zis celei mai mici: „Tatăl nostru este bătrân și nu este niciun bărbat pe pământ care să intre la noi după obiceiul întregului pământ."},{"v":32,"t":"Vino, să-i dăm tatălui nostru să bea vin și să ne culcăm cu el, ca să ridicăm urmași din tatăl nostru.”"},{"v":33,"t":"Și i-au dat tatălui lor să bea vin în noaptea aceea; și cea mai mare a intrat și s-a culcat cu tatăl ei, și el n-a știut nici când s-a culcat ea, nici când s-a sculat."},{"v":34,"t":"Și a fost, a doua zi, că cea mai mare i-a zis celei mai mici: „Iată, m-am culcat aseară cu tatăl meu; să-i dăm să bea vin și în noaptea aceasta, și intră și culcă-te cu el, ca să ridicăm urmași din tatăl nostru.”"},{"v":35,"t":"Și i-au dat tatălui lor să bea vin și în noaptea aceea; și cea mai mică s-a sculat și s-a culcat cu el, și el n-a știut nici când s-a culcat ea, nici când s-a sculat."},{"v":36,"t":"Și cele două fiice ale lui Lot au rămas însărcinate de la tatăl lor."},{"v":37,"t":"Și cea mai mare a născut un fiu și i-a pus numele Moab; el este tatăl moabiților până în ziua de azi."},{"v":38,"t":"Și cea mai mică a născut și ea un fiu și i-a pus numele Ben-Ami; el este tatăl fiilor lui Amon până în ziua de azi."}]},{"num":20,"title":"Pereq 20 - Capitolul 20","verses":[{"v":1,"t":"Și Avraam a pornit de acolo spre țara sudului și a locuit între Rekam și Hagra; și a locuit ca străin în Gherar."},{"v":2,"t":"Și Avraam a zis despre Sara, soția lui: „Este sora mea.” Și Abimelec, regele Gherarului, a trimis și a luat-o pe Sara."},{"v":3,"t":"Și a venit un cuvânt de la Domnul la Abimelec într-un vis de noapte și i-a zis: „Iată, vei muri din pricina femeii pe care ai luat-o, căci ea este soția unui bărbat.”"},{"v":4,"t":"Și Abimelec nu se apropiase de ea; și a zis: „Doamne, vei ucide oare și un popor nevinovat?"},{"v":5,"t":"Nu mi-a zis el: «Este sora mea»? Și ea însăși a zis: «Este fratele meu.» Cu inimă curată și cu mâini nevinovate am făcut aceasta.”"},{"v":6,"t":"Și un cuvânt de la Domnul i-a zis în vis: „Și înaintea Mea este descoperit că ai făcut aceasta cu inimă curată; și Eu Însumi te-am oprit să păcătuiești înaintea Mea; de aceea nu te-am lăsat să te apropii de ea."},{"v":7,"t":"Și acum, dă înapoi soția bărbatului, căci el este profet, și se va ruga pentru tine, și vei trăi. Iar dacă n-o dai înapoi, să știi că vei muri negreșit, tu și tot ce este al tău.”"},{"v":8,"t":"Și Abimelec s-a sculat dis-de-dimineață și i-a chemat pe toți slujitorii lui și a spus toate aceste cuvinte înaintea lor; și oamenii s-au temut foarte mult."},{"v":9,"t":"Și Abimelec l-a chemat pe Avraam și i-a zis: „Ce ne-ai făcut? Și cu ce am păcătuit față de tine, de ai adus asupra mea și asupra împărăției mele un păcat mare? Fapte care nu se cuvine să fie făcute ai făcut cu mine.”"},{"v":10,"t":"Și Abimelec i-a zis lui Avraam: „Ce ai văzut, de ai făcut lucrul acesta?”"},{"v":11,"t":"Și Avraam a zis: „Pentru că am zis: «Numai că nu este frica Domnului în locul acesta, și mă vor ucide din pricina soției mele.»"},{"v":12,"t":"Și de altfel, cu adevărat, ea este sora mea, fiica tatălui meu, dar nu fiica mamei mele, și mi-a devenit soție."},{"v":13,"t":"Și a fost, când neamurile au rătăcit după lucrul mâinilor lor, Domnul m-a apropiat de frica Lui din casa tatălui meu; și i-am zis: «Aceasta este bunătatea pe care să mi-o faci: în orice loc în care vom merge, spune despre mine: Este fratele meu.»”"},{"v":14,"t":"Și Abimelec a luat oi și boi și robi și roabe și i-a dat lui Avraam și i-a dat înapoi pe Sara, soția lui."},{"v":15,"t":"Și Abimelec a zis: „Iată, țara mea este înaintea ta; locuiește unde este bine în ochii tăi.”"},{"v":16,"t":"Iar Sarei i-a zis: „Iată, am dat o mie de sicli de argint fratelui tău; iată, acesta îți este o haină de cinste pentru ochi, pentru că am trimis și te-am luat și te-am văzut, pe tine și tot ce este cu tine; și pentru tot ce ai spus, ai fost dovedită dreaptă.”","notes":["„o haină de cinste pentru ochi” (kesut di-yqar ʿenin): Onkelos redă astfel kesut ʿenayim („acoperământ al ochilor”)."]},{"v":17,"t":"Și Avraam s-a rugat înaintea Domnului, și Domnul l-a vindecat pe Abimelec și pe soția lui și pe roabele lui, și au avut ușurare."},{"v":18,"t":"Căci Domnul închisese cu totul fața oricărui pântec în casa lui Abimelec, din pricina Sarei, soția lui Avraam."}]},{"num":21,"title":"Pereq 21 - Capitolul 21","verses":[{"v":1,"t":"Și Domnul Și-a adus aminte de Sara, cum spusese; și Domnul a făcut Sarei cum vorbise."},{"v":2,"t":"Și Sara a rămas însărcinată și i-a născut lui Avraam un fiu la bătrânețea lui, la vremea despre care îi vorbise Domnul."},{"v":3,"t":"Și Avraam a pus fiului său care i se născuse, pe care i-l născuse Sara, numele Isaac."},{"v":4,"t":"Și Avraam l-a tăiat împrejur pe Isaac, fiul său, la vârsta de opt zile, așa cum îi poruncise Domnul."},{"v":5,"t":"Și Avraam era în vârstă de o sută de ani când i s-a născut Isaac, fiul său."},{"v":6,"t":"Și Sara a zis: „Bucurie mi-a făcut Domnul; oricine va auzi se va bucura cu mine.”"},{"v":7,"t":"Și a zis: „Cât de vrednic de încredere este Cel care i-a spus lui Avraam și a împlinit: că Sara va alăpta fii; căci am născut un fiu la bătrânețea lui!”","notes":["Versetul este o parafrază a lui Onkelos: „Cine i-ar fi spus lui Avraam…” devine „Cât de vrednic de încredere este Cel care i-a spus… și a împlinit”."]},{"v":8,"t":"Și copilul a crescut și a fost înțărcat; și Avraam a făcut un ospăț mare în ziua în care a fost înțărcat Isaac."},{"v":9,"t":"Și Sara l-a văzut pe fiul Agarei egipteanca, pe care i-l născuse lui Avraam, glumind.","notes":["„glumind” (meḥayekh): Onkelos folosește același verb ca ebraicul (meṣaḥeq) și nu dă o interpretare."]},{"v":10,"t":"Și i-a zis lui Avraam: „Alungă pe roaba aceasta și pe fiul ei, căci fiul roabei acesteia nu va moșteni împreună cu fiul meu, cu Isaac.”"},{"v":11,"t":"Și lucrul a fost foarte rău în ochii lui Avraam, din pricina fiului său."},{"v":12,"t":"Și Domnul i-a zis lui Avraam: „Să nu fie rău în ochii tăi din pricina tânărului și din pricina roabei tale; tot ce-ți va spune Sara, primește de la ea, căci prin Isaac ți se vor numi urmași."},{"v":13,"t":"Și pe fiul roabei îl voi face un popor, căci este fiul tău.”"},{"v":14,"t":"Și Avraam s-a sculat dis-de-dimineață și a luat pâine și un burduf cu apă și i-a dat Agarei, punându-le pe umărul ei, și copilul, și a trimis-o; și ea a plecat și a rătăcit în pustiul Beer-Șeba."},{"v":15,"t":"Și apa din burduf s-a sfârșit, și ea a lepădat copilul sub unul din copaci."},{"v":16,"t":"Și s-a dus și s-a așezat în fața lui, departe, cam cât bătaia unui arc, căci a zis: „Să nu văd moartea copilului.” Și s-a așezat în față și și-a ridicat glasul și a plâns."},{"v":17,"t":"Și s-a auzit înaintea Domnului glasul copilului; și îngerul Domnului a chemat-o pe Agar din ceruri și i-a zis: „Ce ai, Agar? Nu te teme, căci s-a auzit înaintea Domnului glasul copilului, acolo unde este el."},{"v":18,"t":"Scoală-te, ridică pe copil și ține-l strâns de mână, căci îl voi face un popor mare.”"},{"v":19,"t":"Și Domnul i-a deschis ochii, și ea a văzut o fântână de apă; și s-a dus și a umplut burduful cu apă și i-a dat copilului să bea."},{"v":20,"t":"Și Cuvântul Domnului a fost în ajutorul copilului; și el a crescut și a locuit în pustiu și a devenit un arcaș."},{"v":21,"t":"Și a locuit în pustiul Paran, și mama lui i-a luat o soție din țara Egiptului („Mițrayim”)."},{"v":22,"t":"Și a fost, în vremea aceea, că Abimelec și Picol, căpetenia oștirii lui, i-au zis lui Avraam: „Cuvântul Domnului este în ajutorul tău în tot ce faci."},{"v":23,"t":"Și acum, jură-mi pe Cuvântul Domnului, aici, că nu mă vei înșela pe mine, nici pe fiul meu, nici pe fiul fiului meu; după bunătatea pe care am făcut-o cu tine să faci cu mine și cu țara în care ai locuit ca străin.”"},{"v":24,"t":"Și Avraam a zis: „Eu voi jura.”"},{"v":25,"t":"Și Avraam l-a mustrat pe Abimelec din pricina fântânii de apă pe care o luaseră cu sila slujitorii lui Abimelec."},{"v":26,"t":"Și Abimelec a zis: „Nu știu cine a făcut lucrul acesta; nici tu nu mi-ai spus, nici eu n-am auzit decât azi.”"},{"v":27,"t":"Și Avraam a luat oi și boi și i-a dat lui Abimelec, și amândoi au încheiat un legământ."},{"v":28,"t":"Și Avraam a pus deoparte șapte mielușele din turmă."},{"v":29,"t":"Și Abimelec i-a zis lui Avraam: „Ce sunt aceste șapte mielușele pe care le-ai pus deoparte?”"},{"v":30,"t":"Și el a zis: „Să primești din mâna mea cele șapte mielușele, ca să-mi fie mărturie că eu am săpat fântâna aceasta.”"},{"v":31,"t":"De aceea a numit locul acela Beer-Șeba, căci acolo au jurat amândoi."},{"v":32,"t":"Și au încheiat un legământ la Beer-Șeba; și Abimelec s-a ridicat, și Picol, căpetenia oștirii lui, și s-au întors în țara filistenilor."},{"v":33,"t":"Și a sădit un sad la Beer-Șeba și s-a rugat acolo în numele Domnului, Dumnezeul lumii.","notes":["„un sad” (neṣba; o variantă din ediție are ilana, „un copac”): Onkelos redă astfel eșel („tamarisc”)."]},{"v":34,"t":"Și Avraam a locuit ca străin în țara filistenilor multe zile."}]},{"num":22,"title":"Pereq 22 - Capitolul 22","verses":[{"v":1,"t":"Și a fost, după lucrurile acestea, că Domnul l-a încercat pe Avraam și i-a zis: „Avraame!” Și el a zis: „Iată-mă.”"},{"v":2,"t":"Și a zis: „Ia, te rog, pe fiul tău, pe singurul tău, pe care îl iubești, pe Isaac, și du-te în țara închinării; și adu-l acolo înaintea Mea ca ardere-de-tot pe unul din munții pe care ți-l voi spune.”","notes":["„țara închinării” (arʿa pulḥana): Onkelos redă astfel „țara Moria”."]},{"v":3,"t":"Și Avraam s-a sculat dis-de-dimineață și și-a pregătit măgarul și i-a luat cu el pe cei doi tineri ai săi și pe Isaac, fiul său; și a despicat lemne pentru arderea-de-tot și s-a ridicat și a mers la locul despre care îi spusese Domnul."},{"v":4,"t":"În ziua a treia, Avraam și-a ridicat ochii și a văzut locul de departe."},{"v":5,"t":"Și Avraam a zis tinerilor săi: „Rămâneți aici cu măgarul, iar eu și tânărul vom ajunge până acolo și ne vom închina și ne vom întoarce la voi.”"},{"v":6,"t":"Și Avraam a luat lemnele pentru arderea-de-tot și le-a pus pe Isaac, fiul său, și a luat în mână focul și cuțitul; și au mers amândoi împreună."},{"v":7,"t":"Și Isaac i-a zis lui Avraam, tatăl său: „Tată!” Și el a zis: „Iată-mă, fiul meu.” Și el a zis: „Iată focul și lemnele, dar unde este mielul pentru arderea-de-tot?”"},{"v":8,"t":"Și Avraam a zis: „Înaintea Domnului este descoperit mielul pentru arderea-de-tot, fiul meu.” Și au mers amândoi împreună."},{"v":9,"t":"Și au ajuns la locul despre care îi spusese Domnul; și Avraam a zidit acolo altarul și a rânduit lemnele și l-a legat pe Isaac, fiul său, și l-a pus pe altar, deasupra lemnelor."},{"v":10,"t":"Și Avraam și-a întins mâna și a luat cuțitul ca să-l înjunghie pe fiul său."},{"v":11,"t":"Și îngerul Domnului l-a chemat din ceruri și a zis: „Avraame, Avraame!” Și el a zis: „Iată-mă.”"},{"v":12,"t":"Și a zis: „Nu-ți întinde mâna asupra tânărului și nu-i face nimic, căci acum știu că ești unul care se teme de Domnul și nu ai cruțat de la Mine pe fiul tău, pe singurul tău.”"},{"v":13,"t":"Și Avraam și-a ridicat ochii după acestea și a văzut, și iată, un berbec, după aceea, prins de copac cu coarnele; și Avraam s-a dus și a luat berbecul și l-a adus ca ardere-de-tot în locul fiului său."},{"v":14,"t":"Și Avraam s-a închinat și s-a rugat acolo, în locul acela, și a zis înaintea Domnului: „Aici se vor închina generațiile.” De aceea se va zice în ziua aceasta: „Pe muntele acesta s-a închinat Avraam înaintea Domnului.”","notes":["Versetul este o parafrază a lui Onkelos despre locul Templului; ebraica are „Domnul va vedea”."]},{"v":15,"t":"Și îngerul Domnului l-a chemat pe Avraam a doua oară din ceruri"},{"v":16,"t":"și a zis: „Pe Cuvântul Meu am jurat, zice Domnul, că, pentru că ai făcut lucrul acesta și nu ai cruțat pe fiul tău, pe singurul tău,"},{"v":17,"t":"te voi binecuvânta negreșit și voi înmulți foarte mult pe urmașii tăi ca stelele cerurilor și ca nisipul care este pe țărmul mării; și urmașii tăi vor moșteni cetățile dușmanilor lor."},{"v":18,"t":"Și prin urmașii tăi se vor binecuvânta toate neamurile pământului, pentru că ai ascultat de Cuvântul Meu.”"},{"v":19,"t":"Și Avraam s-a întors la tinerii săi, și s-au ridicat și au mers împreună la Beer-Șeba; și Avraam a locuit în Beer-Șeba."},{"v":20,"t":"Și a fost, după lucrurile acestea, că i s-a spus lui Avraam: „Iată, Milca a născut și ea fii lui Nahor, fratele tău:"},{"v":21,"t":"pe Uț, întâiul lui născut, și pe Buz, fratele lui, și pe Chemuel, tatăl lui Aram,"},{"v":22,"t":"și pe Chesed și pe Hazo și pe Pildaș și pe Idlaf și pe Betuel.”"},{"v":23,"t":"Și Betuel a născut-o pe Rebeca. Pe acești opt i-a născut Milca lui Nahor, fratele lui Avraam."},{"v":24,"t":"Și țiitoarea lui, al cărei nume era Reuma, a născut și ea pe Tebah și pe Gaham și pe Tahaș și pe Maaca."}]},{"num":23,"title":"Pereq 23 - Capitolul 23","verses":[{"v":1,"t":"Și viața Sarei a fost o sută douăzeci și șapte de ani; anii vieții Sarei."},{"v":2,"t":"Și Sara a murit în Chiriat-Arba, adică Hebron, în țara Canaan; și Avraam a venit s-o jelească pe Sara și s-o plângă."},{"v":3,"t":"Și Avraam s-a ridicat de lângă moarta lui și a vorbit cu fiii lui Het, zicând:"},{"v":4,"t":"„Străin și locuitor vremelnic sunt eu la voi; dați-mi o proprietate de mormânt la voi, ca să-mi îngrop moarta dinaintea mea.”"},{"v":5,"t":"Și fiii lui Het i-au răspuns lui Avraam, zicându-i:"},{"v":6,"t":"„Ascultă-ne, stăpâne: tu ești o căpetenie mare înaintea Domnului în mijlocul nostru; în cel mai bun dintre mormintele noastre îngroapă-ți moarta; niciunul dintre noi nu-și va opri mormântul de la tine, ca să nu-ți îngropi moarta.”"},{"v":7,"t":"Și Avraam s-a ridicat și s-a plecat înaintea poporului țării, înaintea fiilor lui Het."},{"v":8,"t":"Și a vorbit cu ei, zicând: „Dacă este voia voastră să-mi îngrop moarta dinaintea mea, ascultați-mă și rugați-vă pentru mine la Efron, fiul lui Țohar,"},{"v":9,"t":"să-mi dea peștera Macpela, care este a lui, care este la marginea câmpului lui; pentru argint deplin să mi-o dea în mijlocul vostru, ca proprietate de mormânt.”"},{"v":10,"t":"Și Efron ședea în mijlocul fiilor lui Het; și Efron hetitul i-a răspuns lui Avraam înaintea fiilor lui Het, înaintea tuturor celor care intrau pe poarta cetății lui, zicând:"},{"v":11,"t":"„Nu, stăpâne, ascultă-mă: câmpul ți-l dau, și peștera care este în el ți-o dau; în ochii fiilor poporului meu ți-o dau; îngroapă-ți moarta.”"},{"v":12,"t":"Și Avraam s-a plecat înaintea poporului țării."},{"v":13,"t":"Și i-a vorbit lui Efron înaintea poporului țării, zicând: „Numai, dacă vrei să-mi faci un bine, ascultă-mă: dau argintul, prețul câmpului; ia-l de la mine, și îmi voi îngropa moarta acolo.”"},{"v":14,"t":"Și Efron i-a răspuns lui Avraam, zicându-i:"},{"v":15,"t":"„Stăpâne, ascultă-mă: un pământ care valorează patru sute de sicli de argint, între mine și tine, ce este el? Îngroapă-ți moarta.”"},{"v":16,"t":"Și Avraam l-a ascultat pe Efron; și Avraam i-a cântărit lui Efron argintul despre care vorbise înaintea fiilor lui Het: patru sute de sicli de argint, primiți ca monedă de negoț în toată țara."},{"v":17,"t":"Și câmpul lui Efron din Macpela, care este în fața lui Mamre, câmpul și peștera care este în el și toți copacii din câmp, care erau în tot hotarul lui de jur împrejur, au fost întăriți"},{"v":18,"t":"lui Avraam ca proprietate cumpărată, în ochii fiilor lui Het, înaintea tuturor celor care intrau pe poarta cetății lui."},{"v":19,"t":"Și după aceea Avraam a îngropat-o pe Sara, soția lui, în peștera câmpului Macpela, în fața lui Mamre, adică Hebron, în țara Canaan."},{"v":20,"t":"Și câmpul și peștera care este în el au fost întărite lui Avraam ca proprietate de mormânt de la fiii lui Het."}]},{"num":24,"title":"Pereq 24 - Capitolul 24","verses":[{"v":1,"t":"Și Avraam era bătrân, înaintat în zile; și Domnul îl binecuvântase pe Avraam în toate."},{"v":2,"t":"Și Avraam i-a zis robului său, cel mai vechi din casa lui, care stăpânea peste tot ce era al lui: „Pune-ți, te rog, mâna sub coapsa mea,"},{"v":3,"t":"și te voi pune să juri pe Cuvântul Domnului, Dumnezeul cerurilor și Dumnezeul pământului, că nu vei lua soție fiului meu dintre fiicele canaaniților, în mijlocul cărora locuiesc,"},{"v":4,"t":"ci te vei duce în țara mea și la locul nașterii mele și vei lua soție fiului meu, lui Isaac.”"},{"v":5,"t":"Și robul i-a zis: „Poate femeia nu va voi să vină după mine în țara aceasta; să-l duc oare înapoi pe fiul tău în țara din care ai ieșit?”"},{"v":6,"t":"Și Avraam i-a zis: „Păzește-te să nu-l duci pe fiul meu acolo."},{"v":7,"t":"Domnul, Dumnezeul cerurilor, care m-a luat din casa tatălui meu și din țara în care m-am născut și care mi-a vorbit și mi-a jurat, zicând: «Urmașilor tăi le voi da țara aceasta», El va trimite pe îngerul Său înaintea ta, și vei lua de acolo soție fiului meu."},{"v":8,"t":"Iar dacă femeia nu va voi să vină după tine, vei fi dezlegat de jurământul meu acesta; numai pe fiul meu să nu-l duci înapoi acolo.”"},{"v":9,"t":"Și robul și-a pus mâna sub coapsa lui Avraam, stăpânul său, și i-a jurat în privința aceasta."},{"v":10,"t":"Și robul a luat zece cămile din cămilele stăpânului său și a plecat, având în mână tot ce era mai bun de la stăpânul său; și s-a ridicat și s-a dus în Aramul de lângă Eufrat, la cetatea lui Nahor."},{"v":11,"t":"Și a făcut cămilele să îngenuncheze afară din cetate, lângă fântâna de apă, spre vremea serii, la vremea când ies cele care scot apă."},{"v":12,"t":"Și a zis: „Doamne, Dumnezeul stăpânului meu Avraam, rânduiește, te rog, înaintea mea astăzi și fă bunătate cu stăpânul meu Avraam."},{"v":13,"t":"Iată, eu stau lângă izvorul de apă, și fiicele oamenilor cetății ies să scoată apă."},{"v":14,"t":"Și fata căreia îi voi zice: «Apleacă-ți, te rog, ulciorul, ca să beau», iar ea va zice: «Bea, și voi adăpa și cămilele tale», pe aceea ai rânduit-o robului Tău Isaac; și prin ea voi ști că ai făcut bunătate cu stăpânul meu.”"},{"v":15,"t":"Și a fost, înainte de a isprăvi el de vorbit, iată, Rebeca a ieșit, care i se născuse lui Betuel, fiul Milcăi, soția lui Nahor, fratele lui Avraam; și ulciorul ei era pe umăr."},{"v":16,"t":"Și fata era foarte frumoasă la înfățișare, fecioară, și niciun bărbat n-o cunoscuse; și a coborât la izvor și și-a umplut ulciorul și a urcat."},{"v":17,"t":"Și robul a alergat în întâmpinarea ei și a zis: „Dă-mi, te rog, să beau puțină apă din ulciorul tău.”"},{"v":18,"t":"Și ea a zis: „Bea, stăpâne”; și s-a grăbit și și-a coborât ulciorul pe mână și i-a dat să bea."},{"v":19,"t":"Și a isprăvit de dat să bea și a zis: „Și pentru cămilele tale voi scoate, până vor isprăvi de băut.”"},{"v":20,"t":"Și s-a grăbit și și-a golit ulciorul în adăpătoare și a alergat iar la fântână ca să scoată apă și a scos pentru toate cămilele lui."},{"v":21,"t":"Și omul se uita la ea, tăcând, ca să știe dacă Domnul i-a făcut drumul să izbutească sau nu."},{"v":22,"t":"Și a fost, când cămilele au isprăvit de băut, că omul a luat un inel de aur, cântărind o jumătate de siclu, și două brățări pentru mâinile ei, cântărind zece sicli de aur.","notes":["„o jumătate de siclu”: textul aramaic are „greutatea (beqaʿ)” fără unitate explicită; traducerea urmează sensul obișnuit al lui beqaʿ."]},{"v":23,"t":"Și a zis: „A cui fiică ești? Spune-mi, te rog: este în casa tatălui tău loc potrivit pentru noi ca să înnoptăm?”"},{"v":24,"t":"Și ea i-a zis: „Sunt fiica lui Betuel, fiul Milcăi, pe care i l-a născut lui Nahor.”"},{"v":25,"t":"Și i-a mai zis: „Și paie și nutreț avem din belșug, și loc potrivit ca să înnoptați.”"},{"v":26,"t":"Și omul s-a plecat și s-a închinat înaintea Domnului."},{"v":27,"t":"Și a zis: „Binecuvântat este Domnul, Dumnezeul stăpânului meu Avraam, care nu Și-a oprit bunătatea și adevărul de la stăpânul meu; pe calea cea dreaptă m-a condus Domnul la casa fratelui stăpânului meu.”"},{"v":28,"t":"Și fata a alergat și a povestit casei mamei ei după cuvintele acestea."},{"v":29,"t":"Și Rebeca avea un frate al cărui nume era Laban; și Laban a alergat la omul de afară, la izvor."},{"v":30,"t":"Și a fost, când a văzut inelul și brățările pe mâinile surorii lui și când a auzit cuvintele Rebecăi, sora lui, zicând: „Așa mi-a vorbit omul”, că a venit la om, și iată, el stătea lângă cămile, lângă izvor."},{"v":31,"t":"Și a zis: „Intră, binecuvântatul Domnului! De ce stai afară? Eu am pregătit casa și loc potrivit pentru cămile.”"},{"v":32,"t":"Și omul a intrat în casă; și a dezlegat cămilele și a dat paie și nutreț cămilelor și apă ca să-și spele picioarele, lui și picioarele oamenilor care erau cu el."},{"v":33,"t":"Și i s-a pus înainte de mâncare; dar el a zis: „Nu voi mânca până nu voi spune ce am de spus.” Și el a zis: „Vorbește.”"},{"v":34,"t":"Și a zis: „Eu sunt robul lui Avraam."},{"v":35,"t":"Și Domnul l-a binecuvântat foarte mult pe stăpânul meu, și el s-a făcut mare; și i-a dat oi și boi și argint și aur și robi și roabe și cămile și măgari."},{"v":36,"t":"Și Sara, soția stăpânului meu, i-a născut stăpânului meu un fiu după ce a îmbătrânit; și el i-a dat tot ce are."},{"v":37,"t":"Și stăpânul meu m-a pus să jur, zicând: «Să nu iei soție fiului meu dintre fiicele canaaniților, în țara cărora locuiesc,"},{"v":38,"t":"ci să te duci la casa tatălui meu și la familia mea și să iei soție fiului meu.»"},{"v":39,"t":"Și i-am zis stăpânului meu: «Poate femeia nu va veni după mine.»"},{"v":40,"t":"Și el mi-a zis: «Domnul, înaintea căruia am slujit, va trimite pe îngerul Său cu tine și va face să izbutească drumul tău, și vei lua soție fiului meu din familia mea și din casa tatălui meu."},{"v":41,"t":"Atunci vei fi dezlegat de jurământul meu, când vei merge la familia mea; și dacă nu ți-o vor da, vei fi dezlegat de jurământul meu.»"},{"v":42,"t":"Și am venit astăzi la izvor și am zis: «Doamne, Dumnezeul stăpânului meu Avraam, dacă este acum voia Ta să faci să izbutească drumul meu pe care merg,"},{"v":43,"t":"iată, eu stau lângă izvorul de apă; și fata care va ieși să scoată apă și căreia îi voi zice: Dă-mi, te rog, să beau puțină apă din ulciorul tău,"},{"v":44,"t":"iar ea îmi va zice: Bea și tu, și voi scoate și pentru cămilele tale, aceea este femeia pe care a rânduit-o Domnul pentru fiul stăpânului meu.»"},{"v":45,"t":"Înainte de a isprăvi eu de vorbit în inima mea, iată, Rebeca a ieșit cu ulciorul pe umăr și a coborât la izvor și a scos apă; și i-am zis: «Dă-mi, te rog, să beau.»"},{"v":46,"t":"Și ea s-a grăbit și și-a coborât ulciorul de pe ea și a zis: «Bea, și voi adăpa și cămilele tale.» Și am băut, și a adăpat și cămilele."},{"v":47,"t":"Și am întrebat-o și am zis: «A cui fiică ești?» Și ea a zis: «Fiica lui Betuel, fiul lui Nahor, pe care i l-a născut Milca.» Și i-am pus inelul pe nas și brățările pe mâini."},{"v":48,"t":"Și m-am plecat și m-am închinat înaintea Domnului și L-am binecuvântat pe Domnul, Dumnezeul stăpânului meu Avraam, care m-a condus pe calea adevărului ca să iau pe fiica fratelui stăpânului meu pentru fiul lui."},{"v":49,"t":"Și acum, dacă vreți să faceți bunătate și adevăr cu stăpânul meu, spuneți-mi; iar dacă nu, spuneți-mi, și mă voi întoarce la dreapta sau la stânga.”"},{"v":50,"t":"Și Laban și Betuel au răspuns și au zis: „De la Domnul a ieșit lucrul; noi nu putem să-ți spunem nici rău, nici bine."},{"v":51,"t":"Iată, Rebeca este înaintea ta; ia-o și du-te, și să fie soția fiului stăpânului tău, cum a vorbit Domnul.”"},{"v":52,"t":"Și a fost, când robul lui Avraam le-a auzit cuvintele, că s-a închinat până la pământ înaintea Domnului."},{"v":53,"t":"Și robul a scos obiecte de argint și obiecte de aur și haine și i le-a dat Rebecăi; și daruri de preț a dat fratelui ei și mamei ei."},{"v":54,"t":"Și au mâncat și au băut, el și oamenii care erau cu el, și au înnoptat; și s-au sculat dimineața, și el a zis: „Trimiteți-mă la stăpânul meu.”"},{"v":55,"t":"Și fratele ei și mama ei au zis: „Să mai rămână fata cu noi un timp, un an sau zece luni; după aceea va pleca.”","notes":["„un an sau zece luni” (ʿiddan be-ʿiddan o ʿasra yarḥin): Onkelos redă astfel ebraicul yamim o ʿasor."]},{"v":56,"t":"Și el le-a zis: „Nu mă întârziați, căci Domnul a făcut să izbutească drumul meu; trimiteți-mă, și voi merge la stăpânul meu.”"},{"v":57,"t":"Și ei au zis: „S-o chemăm pe fată și să auzim ce spune ea.”"},{"v":58,"t":"Și au chemat-o pe Rebeca și i-au zis: „Vrei să mergi cu omul acesta?” Și ea a zis: „Voi merge.”"},{"v":59,"t":"Și au trimis-o pe Rebeca, sora lor, și pe doica ei și pe robul lui Avraam și pe oamenii lui."},{"v":60,"t":"Și au binecuvântat-o pe Rebeca și i-au zis: „Sora noastră, fii mii și zeci de mii, și să moștenească fiii tăi cetățile dușmanilor lor!”"},{"v":61,"t":"Și Rebeca s-a ridicat, ea și fetele ei, și au încălecat pe cămile și au mers după om; și robul a luat-o pe Rebeca și a plecat."},{"v":62,"t":"Și Isaac venea de la drumul spre fântâna unde s-a arătat îngerul cel viu; și el locuia în țara sudului.","notes":["„venea de la drumul spre” (mi-matohi): ediția are o notă de variantă (ʿal be-mitohi). Sensul este că Isaac venea dinspre fântână."]},{"v":63,"t":"Și Isaac a ieșit să se roage în câmp spre înserare; și și-a ridicat ochii și a văzut, și iată, veneau cămile."},{"v":64,"t":"Și Rebeca și-a ridicat ochii și l-a văzut pe Isaac și s-a aplecat de pe cămilă."},{"v":65,"t":"Și i-a zis robului: „Cine este omul acela care merge prin câmp în întâmpinarea noastră?” Și robul a zis: „El este stăpânul meu.” Și ea și-a luat vălul și s-a acoperit."},{"v":66,"t":"Și robul i-a povestit lui Isaac toate lucrurile pe care le făcuse."},{"v":67,"t":"Și Isaac a dus-o în cort și a văzut, și iată, faptele ei erau drepte ca faptele Sarei, mama lui; și a luat-o pe Rebeca, și ea i-a fost soție, și a iubit-o; și Isaac s-a mângâiat după moartea mamei sale.","notes":["Onkelos adaugă „și a văzut, și iată, faptele ei erau drepte ca faptele Sarei, mama lui”, ca explicație a cuvintelor „cortul Sarei, mama lui”."]}]},{"num":25,"title":"Pereq 25 - Capitolul 25","verses":[{"v":1,"t":"Și Avraam și-a mai luat o soție, al cărei nume era Chetura."},{"v":2,"t":"Și ea i-a născut pe Zimran și pe Iocșan și pe Medan și pe Madian și pe Ișbac și pe Șuah."},{"v":3,"t":"Și Iocșan i-a născut pe Șeba și pe Dedan; și fiii lui Dedan au fost pentru tabere și pentru corturi și pentru insule.","notes":["Așurim, Letușim și Leumim sunt redați de Onkelos ca nume comune: „pentru tabere, pentru corturi și pentru insule”; traducerea urmează textul aramaic."]},{"v":4,"t":"Și fiii lui Madian: Efa și Efer și Enoh și Abida și Eldaa. Toți aceștia sunt fiii Cheturei."},{"v":5,"t":"Și Avraam i-a dat lui Isaac tot ce avea."},{"v":6,"t":"Iar fiilor țiitoarelor pe care le avea Avraam, Avraam le-a dat daruri și i-a trimis departe de Isaac, fiul său, pe când el era încă în viață, spre răsărit, în țara răsăritului."},{"v":7,"t":"Și acestea sunt zilele anilor vieții lui Avraam, pe care i-a trăit: o sută șaptezeci și cinci de ani."},{"v":8,"t":"Și Avraam și-a dat sufletul și a murit la o bătrânețe bună, bătrân și sătul de zile, și a fost adunat la poporul său."},{"v":9,"t":"Și Isaac și Ismael, fiii lui, l-au îngropat în peștera Macpela, în câmpul lui Efron, fiul lui Țohar hetitul, care este în fața lui Mamre,"},{"v":10,"t":"câmpul pe care Avraam îl cumpărase de la fiii lui Het; acolo a fost îngropat Avraam, și Sara, soția lui."},{"v":11,"t":"Și a fost, după ce a murit Avraam, că Domnul l-a binecuvântat pe Isaac, fiul lui; și Isaac a locuit lângă fântâna unde s-a arătat îngerul cel viu."},{"v":12,"t":"Și acestea sunt istorisirile lui Ismael, fiul lui Avraam, pe care i l-a născut lui Avraam Agar egipteanca, roaba Sarei."},{"v":13,"t":"Și acestea sunt numele fiilor lui Ismael, după numele lor, după istorisirile lor: întâiul născut al lui Ismael, Nebaiot; și Chedar și Adbeel și Mibsam"},{"v":14,"t":"și Mișma și Duma și Masa,"},{"v":15,"t":"Hadad și Tema, Ietur, Nafiș și Chedma."},{"v":16,"t":"Aceștia sunt fiii lui Ismael și acestea sunt numele lor, în satele lor și în cetățile lor: doisprezece căpetenii ale neamurilor lor.","notes":["„satele și cetățile lor” (be-paṣḥehon u-ve-kharkhehon): Onkelos redă astfel ebraicul „curțile și taberele lor”."]},{"v":17,"t":"Și aceștia sunt anii vieții lui Ismael: o sută treizeci și șapte de ani; și și-a dat sufletul și a murit și a fost adunat la poporul său."},{"v":18,"t":"Și au locuit de la Havila până la Hagra, care este în fața Egiptului („Mițrayim”), ajungând până la Asiria; în fața tuturor fraților lui s-a așezat."},{"v":19,"t":"Și acestea sunt istorisirile lui Isaac, fiul lui Avraam: Avraam l-a născut pe Isaac."},{"v":20,"t":"Și Isaac era în vârstă de patruzeci de ani când a luat-o pe Rebeca, fiica lui Betuel arameul din Padan-Aram, sora lui Laban arameul, să-i fie soție."},{"v":21,"t":"Și Isaac s-a rugat înaintea Domnului pentru soția lui, căci era stearpă; și Domnul i-a primit rugăciunea, și Rebeca, soția lui, a rămas însărcinată."},{"v":22,"t":"Și fiii se împingeau în pântecele ei; și ea a zis: „Dacă este așa, de ce sunt eu așa?” Și s-a dus să ceară învățătură dinaintea Domnului.","notes":["„să ceară învățătură dinaintea Domnului” (le-mitbaʿ ulpan): Onkelos redă astfel „să-L întrebe pe Domnul”."]},{"v":23,"t":"Și Domnul i-a zis: „Două neamuri sunt în pântecele tău și două împărății se vor despărți din pântecele tău; o împărăție va fi mai tare decât cealaltă împărăție, iar cel mare va fi supus celui mic.”"},{"v":24,"t":"Și s-au împlinit zilele ei ca să nască, și iată, erau gemeni în pântecele ei."},{"v":25,"t":"Și primul a ieșit roșcat, tot ca o manta de păr; și i-au pus numele Esau."},{"v":26,"t":"Și după aceea a ieșit fratele lui, cu mâna ținând călcâiul lui Esau; și i-a pus numele Iacov. Și Isaac era în vârstă de șaizeci de ani când i-a născut ea."},{"v":27,"t":"Și tinerii au crescut; și Esau era un om vânător, un om care ieșea la câmp, iar Iacov era un om desăvârșit, care slujea în casa de învățătură.","notes":["„slujea în casa de învățătură” (meșammeș bet ulpana): Onkelos redă astfel „locuia în corturi”."]},{"v":28,"t":"Și Isaac îl iubea pe Esau, căci mânca din vânatul lui; iar Rebeca îl iubea pe Iacov."},{"v":29,"t":"Și Iacov a fiert o fiertură; și Esau a venit de la câmp, și era istovit."},{"v":30,"t":"Și Esau i-a zis lui Iacov: „Dă-mi, te rog, să gust din roșul acesta, roșul acesta, căci sunt istovit.” De aceea i s-a pus numele Edom."},{"v":31,"t":"Și Iacov a zis: „Vinde-mi, ca în ziua aceasta, dreptul tău de întâi-născut.”"},{"v":32,"t":"Și Esau a zis: „Iată, eu merg spre moarte; și la ce-mi folosește dreptul de întâi-născut?”"},{"v":33,"t":"Și Iacov a zis: „Jură-mi, ca în ziua aceasta.” Și i-a jurat și i-a vândut lui Iacov dreptul său de întâi-născut."},{"v":34,"t":"Și Iacov i-a dat lui Esau pâine și fiertură de linte; și a mâncat și a băut și s-a ridicat și a plecat. Și Esau a disprețuit dreptul de întâi-născut."}]},{"num":26,"title":"Pereq 26 - Capitolul 26","verses":[{"v":1,"t":"Și a fost foamete în țară, în afară de foametea dintâi care fusese în zilele lui Avraam; și Isaac s-a dus la Abimelec, regele filistenilor, la Gherar."},{"v":2,"t":"Și Domnul i S-a descoperit și a zis: „Nu coborî în Egipt („Mițrayim”); locuiește în țara pe care ți-o voi spune."},{"v":3,"t":"Locuiește ca străin în țara aceasta, și Cuvântul Meu va fi în ajutorul tău și te voi binecuvânta; căci ție și urmașilor tăi îți voi da toate țările acestea și voi întări jurământul pe care l-am jurat lui Avraam, tatăl tău."},{"v":4,"t":"Și voi înmulți pe urmașii tăi ca stelele cerurilor și voi da urmașilor tăi toate țările acestea; și prin urmașii tăi se vor binecuvânta toate neamurile pământului,"},{"v":5,"t":"pentru că Avraam a ascultat de Cuvântul Meu și a păzit ce era de păzit din Cuvântul Meu, poruncile Mele, legămintele Mele și învățăturile Mele (Torot).”"},{"v":6,"t":"Și Isaac a locuit în Gherar."},{"v":7,"t":"Și oamenii locului au întrebat despre soția lui, și el a zis: „Este sora mea”, căci se temea să zică: „Soția mea”, ca nu cumva să-l ucidă oamenii locului din pricina Rebecăi, căci era frumoasă la înfățișare."},{"v":8,"t":"Și a fost, după ce zilele i s-au înmulțit acolo, că Abimelec, regele filistenilor, a privit pe fereastră și a văzut, și iată, Isaac glumea cu Rebeca, soția lui."},{"v":9,"t":"Și Abimelec l-a chemat pe Isaac și a zis: „Iată, de fapt este soția ta; și cum ai zis: «Este sora mea»?” Și Isaac i-a zis: „Pentru că am zis: «Ca nu cumva să mor din pricina ei.»”"},{"v":10,"t":"Și Abimelec a zis: „Ce ne-ai făcut? Cât pe ce s-ar fi culcat cel mai de seamă din popor cu soția ta, și ai fi adus asupra noastră vină.”"},{"v":11,"t":"Și Abimelec a poruncit întregului popor, zicând: „Cine va face rău omului acesta și soției lui va fi omorât negreșit.”"},{"v":12,"t":"Și Isaac a semănat în țara aceea și a găsit în anul acela de o sută de ori cât socotise; și Domnul l-a binecuvântat."},{"v":13,"t":"Și omul s-a făcut mare și a mers tot crescând, până s-a făcut foarte mare."},{"v":14,"t":"Și a avut turme de oi și cirezi de boi și multă slugărime; și filistenii l-au invidiat."},{"v":15,"t":"Și toate fântânile pe care le săpaseră robii tatălui său în zilele lui Avraam, tatăl său, filistenii le-au astupat și le-au umplut cu țărână."},{"v":16,"t":"Și Abimelec i-a zis lui Isaac: „Pleacă de la noi, căci ai ajuns mult mai puternic decât noi.”"},{"v":17,"t":"Și Isaac a plecat de acolo și și-a așezat tabăra în valea Gherarului și a locuit acolo."},{"v":18,"t":"Și Isaac a săpat din nou fântânile de apă care fuseseră săpate în zilele lui Avraam, tatăl său, și pe care filistenii le astupaseră după moartea lui Avraam; și le-a pus nume după numele pe care le dăduse tatăl său."},{"v":19,"t":"Și robii lui Isaac au săpat în vale și au găsit acolo o fântână cu apă izvorâtoare."},{"v":20,"t":"Și păstorii din Gherar s-au certat cu păstorii lui Isaac, zicând: „Apa este a noastră.” Și a pus fântânii numele Esec, căci se certaseră cu el."},{"v":21,"t":"Și au săpat altă fântână, și s-au certat și pentru ea; și i-a pus numele Sitna."},{"v":22,"t":"Și a plecat de acolo și a săpat altă fântână, și nu s-au mai certat pentru ea; și i-a pus numele Rehobot și a zis: „Căci acum Domnul ne-a făcut loc larg, și vom crește în țară.”"},{"v":23,"t":"Și a urcat de acolo la Beer-Șeba."},{"v":24,"t":"Și Domnul i S-a descoperit în noaptea aceea și a zis: „Eu sunt Dumnezeul lui Avraam, tatăl tău; nu te teme, căci Cuvântul Meu este în ajutorul tău; și te voi binecuvânta și voi înmulți pe urmașii tăi pentru Avraam, robul Meu.”"},{"v":25,"t":"Și a zidit acolo un altar și s-a rugat în numele Domnului și și-a întins acolo cortul; și robii lui Isaac au săpat acolo o fântână."},{"v":26,"t":"Și Abimelec a venit la el din Gherar, cu o ceată de prieteni ai lui, și Picol, căpetenia oștirii lui."},{"v":27,"t":"Și Isaac le-a zis: „De ce ați venit la mine, când voi m-ați urât și m-ați izgonit de la voi?”"},{"v":28,"t":"Și ei au zis: „Am văzut bine că a fost Cuvântul Domnului în ajutorul tău și am zis: Să se întărească, te rog, jurământul care a fost între părinții noștri, între noi și tine, și să încheiem un legământ cu tine,"},{"v":29,"t":"că nu ne vei face rău, așa cum nici noi nu te-am vătămat și așa cum ți-am făcut numai bine și te-am trimis în pace. Tu ești acum binecuvântatul Domnului.”"},{"v":30,"t":"Și le-a făcut un ospăț, și au mâncat și au băut."},{"v":31,"t":"Și s-au sculat dis-de-dimineață și și-au jurat unul altuia; și Isaac i-a trimis, și au plecat de la el în pace."},{"v":32,"t":"Și a fost, în ziua aceea, că robii lui Isaac au venit și i-au spus despre fântâna pe care o săpaseră și i-au zis: „Am găsit apă.”"},{"v":33,"t":"Și a numit-o Șiba; de aceea numele cetății este Beer-Șeba până în ziua aceasta."},{"v":34,"t":"Și Esau era în vârstă de patruzeci de ani și a luat de soție pe Iudit, fiica lui Beeri hetitul, și pe Basmat, fiica lui Elon hetitul."},{"v":35,"t":"Și ele erau răzvrătite și mânioase față de cuvântul lui Isaac și al Rebecăi.","notes":["„erau răzvrătite și mânioase față de cuvântul lui Isaac și al Rebecăi”: parafrază a lui Onkelos pentru „amărăciune de duh”."]}]},{"num":27,"title":"Pereq 27 - Capitolul 27","verses":[{"v":1,"t":"Și a fost, când Isaac a îmbătrânit și ochii i s-au întunecat de nu mai vedea, că l-a chemat pe Esau, fiul său cel mare, și i-a zis: „Fiul meu!” Și el i-a zis: „Iată-mă.”"},{"v":2,"t":"Și a zis: „Iată, acum am îmbătrânit; nu știu ziua în care voi muri."},{"v":3,"t":"Și acum, ia-ți, te rog, armele, sabia și arcul, și ieși la câmp și vânează-mi vânat."},{"v":4,"t":"Și fă-mi mâncăruri cum îmi plac și adu-mi-le, și voi mânca, pentru ca sufletul meu să te binecuvânteze înainte să mor.”"},{"v":5,"t":"Și Rebeca a auzit când a vorbit Isaac cu Esau, fiul său. Și Esau s-a dus la câmp să vâneze vânat ca să-l aducă."},{"v":6,"t":"Și Rebeca i-a vorbit lui Iacov, fiul ei, zicând: „Iată, l-am auzit pe tatăl tău vorbind cu Esau, fratele tău, zicând:"},{"v":7,"t":"«Adu-mi vânat și fă-mi mâncăruri, și voi mânca și te voi binecuvânta înaintea Domnului înainte de moartea mea.»"},{"v":8,"t":"Și acum, fiul meu, ascultă-mă în ce-ți poruncesc."},{"v":9,"t":"Du-te, te rog, la turmă și ia-mi de acolo doi iezi buni, și îi voi face mâncăruri pentru tatăl tău, cum îi plac."},{"v":10,"t":"Și le vei aduce tatălui tău, și va mânca, pentru ca să te binecuvânteze înainte de moartea lui.”"},{"v":11,"t":"Și Iacov i-a zis Rebecăi, mama lui: „Iată, Esau, fratele meu, este un om păros, iar eu sunt un om neted."},{"v":12,"t":"Poate tatăl meu mă va pipăi, și voi fi în ochii lui ca unul care își bate joc, și voi aduce asupra mea blesteme, și nu binecuvântări.”"},{"v":13,"t":"Și mama lui i-a zis: „Mie mi s-a spus prin profeție că blestemele nu vor veni asupra ta, fiul meu; numai ascultă-mă și du-te și ia-mi.”"},{"v":14,"t":"Și s-a dus și a luat și i-a adus mamei lui; și mama lui a făcut mâncăruri cum îi plăceau tatălui său."},{"v":15,"t":"Și Rebeca a luat hainele lui Esau, fiul ei cel mare, cele de preț, care erau la ea în casă, și l-a îmbrăcat pe Iacov, fiul ei cel mic."},{"v":16,"t":"Și pieile iezilor le-a pus pe mâinile lui și pe partea netedă a gâtului lui."},{"v":17,"t":"Și a dat mâncărurile și pâinea pe care le făcuse în mâna lui Iacov, fiul ei."},{"v":18,"t":"Și el a intrat la tatăl său și a zis: „Tată!” Și el a zis: „Iată-mă; cine ești tu, fiul meu?”"},{"v":19,"t":"Și Iacov i-a zis tatălui său: „Eu sunt Esau, întâiul tău născut; am făcut cum mi-ai spus. Ridică-te, te rog, așază-te și mănâncă din vânatul meu, pentru ca sufletul tău să mă binecuvânteze.”"},{"v":20,"t":"Și Isaac i-a zis fiului său: „Cum de te-ai grăbit să găsești, fiul meu?” Și el a zis: „Pentru că Domnul, Dumnezeul tău, a rânduit înaintea mea.”"},{"v":21,"t":"Și Isaac i-a zis lui Iacov: „Apropie-te, te rog, să te pipăi, fiul meu: ești tu fiul meu Esau sau nu?”"},{"v":22,"t":"Și Iacov s-a apropiat de Isaac, tatăl său, și el l-a pipăit și a zis: „Glasul este glasul lui Iacov, dar mâinile sunt mâinile lui Esau.”"},{"v":23,"t":"Și nu l-a recunoscut, căci mâinile lui erau ca mâinile lui Esau, fratele lui, păroase; și l-a binecuvântat."},{"v":24,"t":"Și a zis: „Tu ești fiul meu Esau?” Și el a zis: „Eu sunt.”"},{"v":25,"t":"Și a zis: „Apropie-mi, ca să mănânc din vânatul fiului meu, pentru ca sufletul meu să te binecuvânteze.” Și i-a apropiat, și a mâncat; și i-a adus vin, și a băut."},{"v":26,"t":"Și Isaac, tatăl său, i-a zis: „Apropie-te, te rog, și sărută-mă, fiul meu.”"},{"v":27,"t":"Și s-a apropiat și l-a sărutat; și el a mirosit mirosul hainelor lui și l-a binecuvântat și a zis: „Vezi, mirosul fiului meu este ca mirosul unui câmp pe care l-a binecuvântat Domnul."},{"v":28,"t":"Și să-ți dea Domnul din roua cerurilor și din belșugul pământului și mulțime de grâne și de vin."},{"v":29,"t":"Să-ți slujească popoarele și să ți se supună împărățiile; fii stăpân peste frații tăi, și să ți se plece fiii mamei tale. Cei care te blestemă să fie blestemați, iar cei care te binecuvântează să fie binecuvântați.”"},{"v":30,"t":"Și a fost, când Isaac a isprăvit de binecuvântat pe Iacov, și abia ieșise Iacov din fața lui Isaac, tatăl său, că Esau, fratele lui, a venit de la vânătoare."},{"v":31,"t":"Și a făcut și el mâncăruri și le-a adus tatălui său și i-a zis tatălui său: „Să se ridice tatăl meu și să mănânce din vânatul fiului său, pentru ca sufletul tău să mă binecuvânteze.”"},{"v":32,"t":"Și Isaac, tatăl lui, i-a zis: „Cine ești tu?” Și el a zis: „Eu sunt fiul tău, întâiul tău născut, Esau.”"},{"v":33,"t":"Și Isaac s-a cutremurat cu un cutremur mare, foarte mare, și a zis: „Cine este, deci, acela care a vânat vânat și mi l-a adus, și am mâncat din toate înainte să vii tu, și l-am binecuvântat? Și binecuvântat va fi!”"},{"v":34,"t":"Când a auzit Esau cuvintele tatălui său, a strigat cu un strigăt mare și amar, foarte amar, și i-a zis tatălui său: „Binecuvântează-mă și pe mine, tată!”"},{"v":35,"t":"Și el a zis: „Fratele tău a venit cu înțelepciune și a primit binecuvântarea ta.”"},{"v":36,"t":"Și el a zis: „Pe bună dreptate i s-a pus numele Iacov, căci m-a înșelat de două ori: dreptul meu de întâi-născut l-a luat, și iată, acum a primit binecuvântarea mea.” Și a zis: „Nu mi-ai păstrat o binecuvântare?”"},{"v":37,"t":"Și Isaac a răspuns și i-a zis lui Esau: „Iată, l-am pus stăpân peste tine și pe toți frații lui i i-am dat ca robi; cu grâne și cu vin l-am sprijinit; și pentru tine ce să mai fac, fiul meu?”"},{"v":38,"t":"Și Esau i-a zis tatălui său: „Ai tu numai o binecuvântare, tată? Binecuvântează-mă și pe mine, tată!” Și Esau și-a ridicat glasul și a plâns."},{"v":39,"t":"Și Isaac, tatăl lui, a răspuns și i-a zis: „Iată, din belșugul pământului va fi locuința ta și din roua cerurilor de sus."},{"v":40,"t":"Și cu sabia ta vei trăi și fratelui tău îi vei sluji; dar va fi, când fiii lui vor călca cuvintele Legii, că vei scutura jugul lui de pe grumazul tău.”","notes":["Onkelos adaugă: „când fiii lui (ai lui Iacov) vor călca cuvintele Legii”, ca o condiție a scuturării jugului."]},{"v":41,"t":"Și Esau a păstrat dușmănie împotriva lui Iacov din pricina binecuvântării cu care îl binecuvântase tatăl său; și Esau a zis în inima lui: „Se vor apropia zilele de doliu ale tatălui meu, și îl voi ucide pe Iacov, fratele meu.”"},{"v":42,"t":"Și Rebecăi i s-au spus cuvintele lui Esau, fiul ei cel mare; și a trimis și l-a chemat pe Iacov, fiul ei cel mic, și i-a zis: „Iată, Esau, fratele tău, stă la pândă împotriva ta ca să te ucidă."},{"v":43,"t":"Și acum, fiul meu, ascultă-mă: ridică-te și fugi la Laban, fratele meu, la Haran."},{"v":44,"t":"Și să locuiești cu el câteva zile, până se va potoli mânia fratelui tău,"},{"v":45,"t":"până se va abate mânia fratelui tău de la tine și va uita ce i-ai făcut; și voi trimite și te voi aduce de acolo. De ce să fiu lipsită de amândoi într-o singură zi?”"},{"v":46,"t":"Și Rebeca i-a zis lui Isaac: „Mi-e silă de viața mea din pricina fiicelor lui Het; dacă Iacov își ia soție dintre fiicele lui Het, ca acestea, dintre fiicele țării, la ce-mi mai este viața?”"}]},{"num":28,"title":"Pereq 28 - Capitolul 28","verses":[{"v":1,"t":"Și Isaac l-a chemat pe Iacov și l-a binecuvântat și i-a poruncit și i-a zis: „Să nu iei soție dintre fiicele Canaanului."},{"v":2,"t":"Ridică-te, du-te la Padan-Aram, la casa lui Betuel, tatăl mamei tale, și ia-ți de acolo soție dintre fiicele lui Laban, fratele mamei tale."},{"v":3,"t":"Și Dumnezeul Atotputernic (El Șadai) să te binecuvânteze și să te facă roditor și să te înmulțească, și să devii o adunare de seminții."},{"v":4,"t":"Și să-ți dea binecuvântarea lui Avraam, ție și urmașilor tăi cu tine, ca să moștenești țara în care locuiești ca străin, pe care Domnul a dat-o lui Avraam.”"},{"v":5,"t":"Și Isaac l-a trimis pe Iacov, și el s-a dus la Padan-Aram, la Laban, fiul lui Betuel arameul, fratele Rebecăi, mama lui Iacov și a lui Esau."},{"v":6,"t":"Și Esau a văzut că Isaac îl binecuvântase pe Iacov și îl trimisese la Padan-Aram ca să-și ia soție de acolo, și că, binecuvântându-l, îi poruncise, zicând: „Să nu iei soție dintre fiicele Canaanului”,"},{"v":7,"t":"și că Iacov ascultase de tatăl său și de mama sa și se dusese la Padan-Aram."},{"v":8,"t":"Și Esau a văzut că fiicele Canaanului erau rele în ochii lui Isaac, tatăl său."},{"v":9,"t":"Și Esau s-a dus la Ismael și a luat-o pe Mahalat, fiica lui Ismael, fiul lui Avraam, sora lui Nebaiot, pe lângă soțiile lui, să-i fie soție."},{"v":10,"t":"Și Iacov a ieșit din Beer-Șeba și s-a dus la Haran."},{"v":11,"t":"Și a dat de un loc și a înnoptat acolo, căci soarele apusese; și a luat dintre pietrele locului și și-a pus-o căpătâi și s-a culcat în locul acela."},{"v":12,"t":"Și a visat, și iată, o scară era înfiptă în pământ, iar vârful ei ajungea până la înălțimea cerurilor; și iată, îngerii Domnului urcau și coborau pe ea."},{"v":13,"t":"Și iată, Slava Domnului stătea deasupra lui și a zis: „Eu sunt Domnul, Dumnezeul lui Avraam, tatăl tău, și Dumnezeul lui Isaac; țara pe care ești culcat ți-o voi da ție și urmașilor tăi."},{"v":14,"t":"Și urmașii tăi vor fi mulți ca țărâna pământului, și te vei întări spre apus și spre răsărit, spre nord și spre sud; și prin tine și prin urmașii tăi se vor binecuvânta toate familiile pământului."},{"v":15,"t":"Și iată, Cuvântul Meu este în ajutorul tău, și te voi păzi oriunde vei merge și te voi aduce înapoi în țara aceasta, căci nu te voi părăsi până nu voi face ce ți-am spus.”"},{"v":16,"t":"Și Iacov s-a trezit din somnul lui și a zis: „Cu adevărat, (este) Slava Domnului care locuiește în locul acesta, și eu nu știam.”","notes":["„(este)”: ediția are cuvântul it („este, există”) între paranteze, ca variantă; traducerea îl păstrează în paranteze."]},{"v":17,"t":"Și s-a temut și a zis: „Cât de înfricoșător este locul acesta! Acesta nu este un loc obișnuit, ci un loc în care este bunăvoință dinaintea Domnului, și aceasta este poarta în fața cerurilor.”","notes":["„un loc obișnuit” (atar hedyoṭ): Onkelos redă astfel „casa lui Dumnezeu” prin opoziție: „nu este un loc obișnuit, ci un loc în care este bunăvoință dinaintea Domnului”."]},{"v":18,"t":"Și Iacov s-a sculat dis-de-dimineață și a luat piatra pe care și-o pusese căpătâi și a pus-o stâlp și a turnat untdelemn pe vârful ei."},{"v":19,"t":"Și a pus locului aceluia numele Betel; dar numele cetății fusese la început Luz."},{"v":20,"t":"Și Iacov a făcut un jurământ, zicând: „Dacă va fi Cuvântul Domnului în ajutorul meu și mă va păzi pe drumul acesta pe care merg și îmi va da pâine de mâncat și haină de îmbrăcat,"},{"v":21,"t":"și mă voi întoarce în pace la casa tatălui meu, atunci Cuvântul Domnului îmi va fi Dumnezeu."},{"v":22,"t":"Și piatra aceasta pe care am pus-o stâlp va fi un loc pe care voi sluji înaintea Domnului; și din tot ce-mi vei da, a zecea parte o voi pune deoparte înaintea Ta.”"}]},{"num":29,"title":"Pereq 29 - Capitolul 29","verses":[{"v":1,"t":"Și Iacov a pornit la drum și s-a dus în țara fiilor răsăritului."},{"v":2,"t":"Și a privit, și iată, o fântână în câmp, și iată, acolo trei turme de oi stăteau culcate lângă ea, căci din fântâna aceea se adăpau turmele; și piatra cea mare era pe gura fântânii."},{"v":3,"t":"Și acolo se adunau toate turmele, și rostogoleau piatra de pe gura fântânii și adăpau oile și puneau piatra înapoi pe gura fântânii, la locul ei."},{"v":4,"t":"Și Iacov le-a zis: „Frații mei, de unde sunteți?” Și ei au zis: „Suntem din Haran.”"},{"v":5,"t":"Și le-a zis: „Îl cunoașteți pe Laban, fiul lui Nahor?” Și ei au zis: „Îl cunoaștem.”"},{"v":6,"t":"Și le-a zis: „Este bine?” Și ei au zis: „Este bine; și iată, Rahela, fiica lui, vine cu oile.”"},{"v":7,"t":"Și el a zis: „Iată, este încă ziua mare; nu este vremea să se adune vitele; adăpați oile și duceți-vă de le pășteți.”"},{"v":8,"t":"Și ei au zis: „Nu putem, până nu se adună toate turmele și rostogolesc piatra de pe gura fântânii; atunci adăpăm oile.”"},{"v":9,"t":"Pe când el încă vorbea cu ei, Rahela a venit cu oile tatălui ei, căci ea era păstoriță."},{"v":10,"t":"Și a fost, când Iacov a văzut-o pe Rahela, fiica lui Laban, fratele mamei sale, și oile lui Laban, fratele mamei sale, că Iacov s-a apropiat și a rostogolit piatra de pe gura fântânii și a adăpat oile lui Laban, fratele mamei sale."},{"v":11,"t":"Și Iacov a sărutat-o pe Rahela și și-a ridicat glasul și a plâns."},{"v":12,"t":"Și Iacov i-a spus Rahelei că el este fiul surorii tatălui ei și că este fiul Rebecăi; și ea a alergat și i-a spus tatălui ei."},{"v":13,"t":"Și a fost, când Laban a auzit vestea despre Iacov, fiul surorii lui, că a alergat în întâmpinarea lui și l-a îmbrățișat și l-a sărutat și l-a adus în casa lui; și el i-a povestit lui Laban toate lucrurile acestea."},{"v":14,"t":"Și Laban i-a zis: „Într-adevăr, tu ești ruda mea și carnea mea.” Și a locuit cu el o lună de zile."},{"v":15,"t":"Și Laban i-a zis lui Iacov: „Pentru că ești ruda mea, să-mi slujești oare degeaba? Spune-mi care este plata ta.”"},{"v":16,"t":"Și Laban avea două fiice: numele celei mari era Lea, iar numele celei mici, Rahela."},{"v":17,"t":"Și ochii Leei erau frumoși, iar Rahela era frumoasă la chip și frumoasă la înfățișare."},{"v":18,"t":"Și Iacov o iubea pe Rahela și a zis: „Îți voi sluji șapte ani pentru Rahela, fiica ta cea mică.”"},{"v":19,"t":"Și Laban a zis: „Este mai bine să ți-o dau ție decât să o dau altui bărbat; locuiește cu mine.”"},{"v":20,"t":"Și Iacov a slujit pentru Rahela șapte ani, și au fost în ochii lui ca niște zile puține, pentru că o iubea."},{"v":21,"t":"Și Iacov i-a zis lui Laban: „Dă-mi soția, căci mi-am împlinit zilele slujbei, ca să intru la ea.”"},{"v":22,"t":"Și Laban i-a adunat pe toți oamenii locului și a făcut un ospăț."},{"v":23,"t":"Și a fost, seara, că a luat-o pe Lea, fiica lui, și a adus-o la el; și el a intrat la ea."},{"v":24,"t":"Și Laban i-a dat-o pe Zilpa, roaba lui, Leei, fiica lui, ca roabă."},{"v":25,"t":"Și a fost, dimineața, și iată, era Lea; și el i-a zis lui Laban: „Ce mi-ai făcut? Nu pentru Rahela am slujit la tine? Și de ce m-ai înșelat?”"},{"v":26,"t":"Și Laban a zis: „Nu se face așa în locul nostru, să se dea cea mică înaintea celei mari."},{"v":27,"t":"Împlinește săptămâna acesteia, și îți vom da și pe aceasta, pentru slujba pe care o vei sluji la mine încă alți șapte ani.”"},{"v":28,"t":"Și Iacov a făcut așa și a împlinit săptămâna acesteia; și i-a dat-o pe Rahela, fiica lui, să-i fie soție."},{"v":29,"t":"Și Laban i-a dat-o pe Bilha, roaba lui, Rahelei, fiica lui, ca roabă."},{"v":30,"t":"Și a intrat și la Rahela, și a iubit-o pe Rahela mai mult decât pe Lea; și a slujit la el încă alți șapte ani."},{"v":31,"t":"Și Domnul a văzut că Lea era neiubită și i-a dat sarcină; iar Rahela era stearpă."},{"v":32,"t":"Și Lea a rămas însărcinată și a născut un fiu și i-a pus numele Ruben, căci a zis: „Pentru că este descoperită înaintea Domnului umilința mea; căci acum mă va iubi bărbatul meu.”"},{"v":33,"t":"Și a rămas iar însărcinată și a născut un fiu și a zis: „Pentru că s-a auzit înaintea Domnului că sunt neiubită, mi l-a dat și pe acesta.” Și i-a pus numele Simeon."},{"v":34,"t":"Și a rămas iar însărcinată și a născut un fiu și a zis: „De data aceasta bărbatul meu se va alipi de mine, căci i-am născut trei fii.” De aceea i s-a pus numele Levi."},{"v":35,"t":"Și a rămas iar însărcinată și a născut un fiu și a zis: „De data aceasta voi aduce laudă înaintea Domnului.” De aceea i-a pus numele Iuda. Și a încetat să mai nască."}]},{"num":30,"title":"Pereq 30 - Capitolul 30","verses":[{"v":1,"t":"Și Rahela a văzut că nu-i năștea lui Iacov copii; și Rahela a pizmuit-o pe sora ei și i-a zis lui Iacov: „Dă-mi copii, altfel sunt moartă.”"},{"v":2,"t":"Și mânia lui Iacov s-a aprins împotriva Rahelei și a zis: „Oare de la mine ceri? Nu cumva de la Domnul trebuie să ceri, care ți-a oprit rodul pântecelui?”"},{"v":3,"t":"Și ea a zis: „Iată roaba mea, Bilha; intră la ea, și ea va naște, iar eu voi crește copilul și voi fi zidită și eu prin ea.”"},{"v":4,"t":"Și i-a dat-o pe Bilha, roaba ei, de soție; și Iacov a intrat la ea."},{"v":5,"t":"Și Bilha a rămas însărcinată și i-a născut lui Iacov un fiu."},{"v":6,"t":"Și Rahela a zis: „Domnul m-a judecat și mi-a și primit rugăciunea și mi-a dat un fiu.” De aceea i-a pus numele Dan."},{"v":7,"t":"Și Bilha, roaba Rahelei, a rămas iar însărcinată și i-a născut lui Iacov un al doilea fiu."},{"v":8,"t":"Și Rahela a zis: „Domnul a primit cererea mea, când am stăruit în rugăciunea mea; am dorit să am un copil ca sora mea, și mi s-a dat și mie.” Și i-a pus numele Neftali."},{"v":9,"t":"Și Lea a văzut că încetase să nască și a luat-o pe Zilpa, roaba ei, și i-a dat-o lui Iacov de soție."},{"v":10,"t":"Și Zilpa, roaba Leei, i-a născut lui Iacov un fiu."},{"v":11,"t":"Și Lea a zis: „A venit norocul (gad)!” Și i-a pus numele Gad.","notes":["„A venit norocul (gad)”: ediția are ata gad, așa cum se citește în ebraică (qeri: ba gad)."]},{"v":12,"t":"Și Zilpa, roaba Leei, i-a născut lui Iacov un al doilea fiu."},{"v":13,"t":"Și Lea a zis: „Laudă am avut, căci de acum mă vor lăuda femeile.” Și i-a pus numele Așer."},{"v":14,"t":"Și Ruben s-a dus în zilele secerișului grâului și a găsit mandragore în câmp și le-a adus Leei, mamei sale. Și Rahela i-a zis Leei: „Dă-mi, te rog, din mandragorele fiului tău.”"},{"v":15,"t":"Și ea i-a zis: „Puțin lucru este că mi-ai luat bărbatul, de vrei să iei și mandragorele fiului meu?” Și Rahela a zis: „Atunci să se culce cu tine la noapte, în schimbul mandragorelor fiului tău.”"},{"v":16,"t":"Și Iacov a venit de la câmp seara, și Lea a ieșit în întâmpinarea lui și a zis: „La mine vei intra, căci te-am tocmit cu mandragorele fiului meu.” Și s-a culcat cu ea în noaptea aceea."},{"v":17,"t":"Și Domnul a primit rugăciunea Leei, și ea a rămas însărcinată și i-a născut lui Iacov un al cincilea fiu."},{"v":18,"t":"Și Lea a zis: „Domnul mi-a dat plata, pentru că i-am dat roaba mea bărbatului meu.” Și i-a pus numele Isahar."},{"v":19,"t":"Și Lea a rămas iar însărcinată și i-a născut lui Iacov un al șaselea fiu."},{"v":20,"t":"Și Lea a zis: „Domnul mi-a dat o parte bună; de data aceasta locuința bărbatului meu va fi la mine, căci i-am născut șase fii.” Și i-a pus numele Zabulon."},{"v":21,"t":"Și după aceea a născut o fiică și i-a pus numele Dina."},{"v":22,"t":"Și amintirea Rahelei a ajuns înaintea Domnului, și Domnul i-a primit rugăciunea și i-a dat sarcină."},{"v":23,"t":"Și a rămas însărcinată și a născut un fiu și a zis: „Domnul a strâns ocara mea.”"},{"v":24,"t":"Și i-a pus numele Iosif, zicând: „Să-mi adauge Domnul un alt fiu.”"},{"v":25,"t":"Și a fost, după ce Rahela l-a născut pe Iosif, că Iacov i-a zis lui Laban: „Lasă-mă să plec, și mă voi duce la locul meu și în țara mea."},{"v":26,"t":"Dă-mi soțiile și copiii, pentru care ți-am slujit, și voi pleca; căci tu știi slujba cu care ți-am slujit.”"},{"v":27,"t":"Și Laban i-a zis: „Dacă am găsit acum îndurare înaintea ta… Am încercat și am văzut că Domnul m-a binecuvântat pentru tine.”","notes":["Fraza „Dacă am găsit acum îndurare înaintea ta…” este neterminată și în textul ebraic, și în cel aramaic."]},{"v":28,"t":"Și a zis: „Hotărăște-ți plata asupra mea, și ți-o voi da.”"},{"v":29,"t":"Și el i-a zis: „Tu știi cum ți-am slujit și cum au fost vitele tale la mine."},{"v":30,"t":"Căci puțin era ce aveai înainte de mine, și a crescut foarte mult; și Domnul te-a binecuvântat pentru mine. Și acum, când voi face și eu ceva pentru casa mea?”"},{"v":31,"t":"Și el a zis: „Ce să-ți dau?” Și Iacov a zis: „Să nu-mi dai nimic; dacă îmi vei face lucrul acesta, voi paște iar și voi păzi oile tale."},{"v":32,"t":"Voi trece astăzi prin toate oile tale; scoate de acolo orice miel pestriț și bălțat și orice miel cafeniu dintre miei și pe cele bălțate și pestrițe dintre capre; și aceasta va fi plata mea."},{"v":33,"t":"Și dreptatea mea va mărturisi pentru mine mâine, când vei veni să vezi plata mea înaintea ta: tot ce nu va fi pestriț și bălțat între capre și cafeniu între miei va fi furat la mine.”"},{"v":34,"t":"Și Laban a zis: „Bine, de-ar fi după cuvântul tău!”"},{"v":35,"t":"Și în ziua aceea a scos țapii vărgați și bălțați și toate caprele pestrițe și bălțate, tot ce avea alb pe el, și tot ce era cafeniu între miei, și le-a dat în mâna fiilor săi."},{"v":36,"t":"Și a pus o distanță de trei zile de mers între el și Iacov; iar Iacov păștea oile lui Laban care rămăseseră."},{"v":37,"t":"Și Iacov și-a luat nuiele verzi de plop, de migdal și de platan și a cojit în ele dungi albe, dezvelind albul care era pe nuiele."},{"v":38,"t":"Și a înfipt nuielele pe care le cojise în jgheaburi, în adăpătorile de apă, unde veneau oile să bea, în fața oilor; și ele se împerecheau când veneau să bea."},{"v":39,"t":"Și oile se împerecheau în fața nuielelor, și oile au fătat miei vărgați, pestriți și bălțați."},{"v":40,"t":"Și Iacov a despărțit mieii și a pus în fruntea oilor tot ce era vărgat și tot ce era cafeniu din oile lui Laban; și și-a făcut turme numai ale lui și nu le-a amestecat cu oile lui Laban."},{"v":41,"t":"Și era, de fiecare dată când se împerecheau oile cele timpurii, că Iacov punea nuielele în fața oilor, în jgheaburi, ca să se împerecheze în fața nuielelor."},{"v":42,"t":"Iar când oile erau târzii, nu le punea; și cele târzii erau ale lui Laban, iar cele timpurii ale lui Iacov."},{"v":43,"t":"Și omul s-a întărit foarte, foarte mult și a avut oi multe și roabe și robi și cămile și măgari."}]},{"num":31,"title":"Pereq 31 - Capitolul 31","verses":[{"v":1,"t":"Și a auzit cuvintele fiilor lui Laban, care ziceau: „Iacov a luat tot ce era al tatălui nostru, și din ce era al tatălui nostru și-a agonisit toată bogăția aceasta.”"},{"v":2,"t":"Și Iacov a văzut fața lui Laban, și iată, nu mai era față de el ca ieri și alaltăieri."},{"v":3,"t":"Și Domnul i-a zis lui Iacov: „Întoarce-te în țara părinților tăi și la locul nașterii tale, și Cuvântul Meu va fi în ajutorul tău.”"},{"v":4,"t":"Și Iacov a trimis și le-a chemat pe Rahela și pe Lea la câmp, la turma lui."},{"v":5,"t":"Și le-a zis: „Văd fața tatălui vostru, că nu mai este față de mine ca ieri și alaltăieri; dar Dumnezeul tatălui meu a fost în ajutorul meu."},{"v":6,"t":"Și voi știți că cu toată puterea mea i-am slujit tatălui vostru."},{"v":7,"t":"Iar tatăl vostru m-a înșelat și mi-a schimbat plata de zece ori; dar Domnul nu l-a lăsat să-mi facă rău."},{"v":8,"t":"Dacă zicea așa: «Cele pestrițe să-ți fie plata», toate oile fătau pestrițe; și dacă zicea așa: «Cele vărgate să-ți fie plata», toate oile fătau vărgate."},{"v":9,"t":"Și Domnul a luat vitele tatălui vostru și mi le-a dat mie."},{"v":10,"t":"Și a fost, la vremea când se împerecheau oile, că mi-am ridicat ochii și am văzut în vis, și iată, țapii care urcau pe oi erau vărgați, pestriți și bălțați."},{"v":11,"t":"Și îngerul Domnului mi-a zis în vis: «Iacove!» Și am zis: «Iată-mă.»"},{"v":12,"t":"Și a zis: «Ridică-ți, te rog, ochii și vezi: toți țapii care urcă pe oi sunt vărgați, pestriți și bălțați; căci este descoperit înaintea Mea tot ce ți-a făcut Laban."},{"v":13,"t":"Eu sunt Dumnezeul care M-am descoperit ție la Betel, unde ai uns un stâlp, unde Mi-ai făcut un jurământ. Acum, ridică-te, ieși din țara aceasta și întoarce-te în țara în care te-ai născut.»”"},{"v":14,"t":"Și Rahela și Lea au răspuns și i-au zis: „Mai avem oare (acum) parte și moștenire în casa tatălui nostru?","notes":["„(acum)”: ediția are kaʿan între paranteze, ca variantă."]},{"v":15,"t":"Nu cumva am fost socotite de el ca străine? Căci ne-a vândut și a mâncat chiar și argintul nostru."},{"v":16,"t":"Căci toată bogăția pe care a luat-o Domnul de la tatăl nostru este a noastră și a copiilor noștri. Și acum, fă tot ce ți-a spus Domnul.”"},{"v":17,"t":"Și Iacov s-a ridicat și și-a urcat copiii și soțiile pe cămile."},{"v":18,"t":"Și și-a dus toate vitele și toată averea pe care o agonisise, vitele agonisite de el, pe care le agonisise în Padan-Aram, ca să meargă la Isaac, tatăl său, în țara Canaan."},{"v":19,"t":"Și Laban se dusese să-și tundă oile; și Rahela a luat chipurile (sau „idolii”) care erau ale tatălui ei."},{"v":20,"t":"Și Iacov a ascuns de inima lui Laban arameul, prin aceea că nu i-a spus că pleacă.","notes":["„a ascuns de inima lui Laban”: traducere literală a aramaicului; sensul este „l-a înșelat pe Laban”."]},{"v":21,"t":"Și a plecat el și tot ce avea; și s-a ridicat și a trecut Eufratul și și-a îndreptat fața spre muntele Galaad."},{"v":22,"t":"Și i s-a spus lui Laban în ziua a treia că Iacov plecase."},{"v":23,"t":"Și i-a luat pe frații lui cu el și l-a urmărit cale de șapte zile și l-a ajuns în muntele Galaad."},{"v":24,"t":"Și a venit un cuvânt de la Domnul la Laban arameul într-un vis de noapte și i-a zis: „Păzește-te să nu-i vorbești lui Iacov nici bine, nici rău.”"},{"v":25,"t":"Și Laban l-a ajuns pe Iacov; și Iacov își întinsese cortul pe munte, iar Laban și-a așezat frații în muntele Galaad."},{"v":26,"t":"Și Laban i-a zis lui Iacov: „Ce ai făcut? Ai ascuns de mine și mi-ai dus fiicele ca pe niște prinse de sabie."},{"v":27,"t":"De ce te-ai ascuns ca să pleci și ai ascuns de mine și nu mi-ai spus? Te-aș fi trimis cu bucurie și cu cântări, cu tobe și cu harfe."},{"v":28,"t":"Și nu m-ai lăsat să-mi sărut fiii și fiicele; acum ai lucrat nechibzuit."},{"v":29,"t":"Este în puterea mâinii mele să vă fac rău; dar Dumnezeul tatălui vostru mi-a zis aseară: «Păzește-te să-i vorbești lui Iacov nici bine, nici rău.»"},{"v":30,"t":"Și acum, ai plecat, pentru că ai tânjit mult după casa tatălui tău; dar de ce mi-ai luat zeii mei?”"},{"v":31,"t":"Și Iacov a răspuns și i-a zis lui Laban: „Pentru că m-am temut, căci am zis: «Ca nu cumva să-mi iei cu sila fiicele tale.»"},{"v":32,"t":"Cel la care îți vei găsi zeii să nu rămână în viață; înaintea fraților noștri cercetează ce este al tău la mine și ia-ți.” Și Iacov nu știa că Rahela îi luase."},{"v":33,"t":"Și Laban a intrat în cortul lui Iacov și în cortul Leei și în cortul celor două roabe și n-a găsit; și a ieșit din cortul Leei și a intrat în cortul Rahelei."},{"v":34,"t":"Și Rahela luase chipurile și le pusese în șaua cămilei și ședea pe ele; și Laban a pipăit tot cortul și n-a găsit."},{"v":35,"t":"Și ea i-a zis tatălui ei: „Să nu se mânie stăpânul meu că nu pot să mă ridic înaintea ta, căci am rânduiala femeilor.” Și el a căutat și n-a găsit chipurile."},{"v":36,"t":"Și Iacov s-a mâniat și s-a certat cu Laban; și Iacov a răspuns și i-a zis lui Laban: „Care este vina mea, care este greșeala mea, de m-ai urmărit?"},{"v":37,"t":"Căci ai pipăit toate lucrurile mele: ce ai găsit din toate lucrurile casei tale? Pune-le aici înaintea fraților mei și a fraților tăi, și să judece ei între noi doi."},{"v":38,"t":"Douăzeci de ani sunt de când sunt la tine; oile tale și caprele tale n-au lepădat, și berbecii turmei tale nu i-am mâncat."},{"v":39,"t":"Ce era sfâșiat nu ți-am adus; ce lipsea la număr de la mine cereai; am păzit ziua și am păzit noaptea."},{"v":40,"t":"Ziua mă mânca arșița, iar gerul (era) cobora asupra mea noaptea, și somnul îmi fugea de pe ochi.","notes":["„(era)”: ediția are hava între paranteze, ca variantă."]},{"v":41,"t":"Iată, douăzeci de ani sunt de când sunt în casa ta: ți-am slujit paisprezece ani pentru cele două fiice ale tale și șase ani pentru oile tale, iar tu mi-ai schimbat plata de zece ori."},{"v":42,"t":"Dacă n-ar fi fost Dumnezeul tatălui meu, Dumnezeul lui Avraam și Cel de care se temea Isaac, în ajutorul meu, acum m-ai fi trimis cu mâna goală. Necazul meu și truda mâinilor mele sunt descoperite înaintea Domnului, și El te-a mustrat aseară.”"},{"v":43,"t":"Și Laban a răspuns și i-a zis lui Iacov: „Fiicele sunt fiicele mele și copiii sunt copiii mei și oile sunt oile mele, și tot ce vezi este al meu. Dar fiicelor mele ce le pot face azi, sau copiilor lor pe care i-au născut?"},{"v":44,"t":"Și acum, vino să încheiem un legământ, eu și tu, și să fie martor între mine și tine.”"},{"v":45,"t":"Și Iacov a luat o piatră și a ridicat-o stâlp."},{"v":46,"t":"Și Iacov le-a zis fraților săi: „Strângeți pietre.” Și au luat pietre și au făcut o movilă și au mâncat acolo, pe movilă."},{"v":47,"t":"Și Laban a numit-o Iegar-Sahaduta, iar Iacov a numit-o Galed.","notes":["Iegar-Sahaduta este forma aramaică pentru „movila mărturiei”, ca și în textul ebraic."]},{"v":48,"t":"Și Laban a zis: „Movila aceasta este martor între mine și tine astăzi.” De aceea i-a pus numele Galed;"},{"v":49,"t":"și Sakuta, căci a zis: „Să privească Cuvântul Domnului între mine și tine, când ne vom ascunde unul de altul.","notes":["„Sakuta” (sakhuta = loc de pază, de privit): așa redă Onkelos ebraicul Mițpa."]},{"v":50,"t":"Dacă vei asupri pe fiicele mele și dacă vei lua soții pe lângă fiicele mele, chiar dacă nu este nimeni cu noi, vezi, Cuvântul Domnului este martor între mine și tine.”"},{"v":51,"t":"Și Laban i-a zis lui Iacov: „Iată movila aceasta și iată stâlpul pe care l-am ridicat între mine și tine."},{"v":52,"t":"Martor este movila aceasta și martor este stâlpul: nici eu nu voi trece la tine dincolo de movila aceasta, nici tu nu vei trece la mine dincolo de movila aceasta și de stâlpul acesta, spre rău."},{"v":53,"t":"Dumnezeul lui Avraam și dumnezeul lui Nahor să judece între noi, dumnezeul tatălui lor.” Și Iacov a jurat pe Cel de care se temea tatăl său, Isaac."},{"v":54,"t":"Și Iacov a înjunghiat jertfe pe munte și i-a chemat pe frații lui să mănânce pâine; și au mâncat pâine și au înnoptat pe munte."}]},{"num":32,"title":"Pereq 32 - Capitolul 32","verses":[{"v":1,"t":"Și Laban s-a sculat dis-de-dimineață și i-a sărutat pe fiii și pe fiicele lui și i-a binecuvântat; și Laban a plecat și s-a întors la locul lui.","notes":["Numerotarea urmează Sefaria și textul ebraic: 32:1 aici corespunde lui 31:55 din unele traduceri românești."]},{"v":2,"t":"Și Iacov și-a văzut de drum, și l-au întâmpinat îngerii Domnului."},{"v":3,"t":"Și Iacov a zis, când i-a văzut: „Aceasta este o tabără de la Domnul.” Și a pus locului aceluia numele Mahanaim."},{"v":4,"t":"Și Iacov a trimis soli înaintea lui la Esau, fratele său, în țara Seir, în ținutul Edomului."},{"v":5,"t":"Și le-a poruncit, zicând: „Așa să-i spuneți stăpânului meu, lui Esau: Așa zice robul tău Iacov: «Am locuit ca străin la Laban și am zăbovit până acum."},{"v":6,"t":"Și am boi și măgari, oi și robi și roabe; și am trimis să-i dau de știre stăpânului meu, ca să găsesc îndurare în ochii tăi.»”"},{"v":7,"t":"Și solii s-au întors la Iacov, zicând: „Am ajuns la fratele tău, la Esau, și el vine în întâmpinarea ta, și patru sute de oameni sunt cu el.”"},{"v":8,"t":"Și Iacov s-a temut foarte mult și i-a fost strâmtorare; și a împărțit poporul care era cu el și oile și boii și cămilele în două tabere."},{"v":9,"t":"Și a zis: „Dacă va veni Esau la o tabără și o va lovi, tabăra care rămâne va fi spre scăpare.”"},{"v":10,"t":"Și Iacov a zis: „Dumnezeul tatălui meu Avraam și Dumnezeul tatălui meu Isaac, Doamne, care mi-ai zis: «Întoarce-te în țara ta și la locul nașterii tale, și îți voi face bine»,"},{"v":11,"t":"puține sunt meritele mele față de toate bunătățile și toate binefacerile pe care le-ai făcut robului Tău; căci singur am trecut Iordanul acesta, și acum am ajuns două tabere.","notes":["„singur” (yeḥidai): Onkelos redă astfel ebraicul „cu toiagul meu”, adică fără avere."]},{"v":12,"t":"Scapă-mă, te rog, din mâna fratelui meu, din mâna lui Esau, căci mă tem de el, ca nu cumva să vină și să mă lovească, pe mama împreună cu copiii."},{"v":13,"t":"Și Tu ai zis: «Îți voi face negreșit bine și voi face pe urmașii tăi ca nisipul mării, care nu poate fi numărat de mulțime.»”"},{"v":14,"t":"Și a înnoptat acolo în noaptea aceea; și a luat din ce avea la îndemână un dar pentru Esau, fratele său:"},{"v":15,"t":"două sute de capre și douăzeci de țapi, două sute de oi și douăzeci de berbeci,"},{"v":16,"t":"treizeci de cămile care alăptau, cu puii lor, patruzeci de vaci și zece tauri, douăzeci de măgărițe și zece măgăruși."},{"v":17,"t":"Și le-a dat în mâna robilor lui, fiecare turmă deosebi, și le-a zis robilor lui: „Treceți înaintea mea și lăsați un spațiu între turmă și turmă.”"},{"v":18,"t":"Și i-a poruncit celui dintâi, zicând: „Când te va întâlni Esau, fratele meu, și te va întreba, zicând: «Al cui ești, unde mergi și ale cui sunt acestea dinaintea ta?»,"},{"v":19,"t":"să zici: «Ale robului tău Iacov; este un dar trimis stăpânului meu, lui Esau; și iată, vine și el în urma noastră.»”"},{"v":20,"t":"Și i-a poruncit și celui de-al doilea și celui de-al treilea și tuturor celor care mergeau după turme, zicând: „După cuvântul acesta să-i vorbiți lui Esau, când îl veți găsi."},{"v":21,"t":"Și să ziceți: «Iată, și robul tău Iacov vine în urma noastră.»” Căci zicea: „Îi voi potoli mânia cu darul care merge înaintea mea, și după aceea îi voi vedea fața; poate mă va primi.”"},{"v":22,"t":"Și darul a trecut înaintea lui, iar el a înnoptat în noaptea aceea în tabără."},{"v":23,"t":"Și s-a sculat în noaptea aceea și le-a luat pe cele două soții ale lui și pe cele două roabe ale lui și pe cei unsprezece copii ai lui și a trecut vadul Iabocului."},{"v":24,"t":"Și i-a luat și i-a trecut pârâul, și a trecut ce avea."},{"v":25,"t":"Și Iacov a rămas singur; și un om s-a luptat cu el până s-au ridicat zorile."},{"v":26,"t":"Și a văzut că nu-l poate birui și s-a atins de încheietura coapsei lui; și încheietura coapsei lui Iacov s-a clintit când se lupta cu el."},{"v":27,"t":"Și a zis: „Lasă-mă să plec, căci s-au ridicat zorile.” Și el a zis: „Nu te las să pleci până nu mă binecuvântezi.”"},{"v":28,"t":"Și i-a zis: „Care este numele tău?” Și el a zis: „Iacov.”"},{"v":29,"t":"Și a zis: „Numele tău nu se va mai zice Iacov, ci Israel, căci ești o căpetenie înaintea Domnului și printre oameni, și ai biruit.”","notes":["„ești o căpetenie înaintea Domnului” (ravrevta qodam Adonai): Onkelos evită expresia „te-ai luptat cu Dumnezeu”."]},{"v":30,"t":"Și Iacov a întrebat și a zis: „Spune-mi, te rog, numele tău.” Și el a zis: „De ce întrebi de numele meu?” Și l-a binecuvântat acolo."},{"v":31,"t":"Și Iacov a pus locului numele Peniel: „Căci am văzut îngerii Domnului față în față, și sufletul meu a scăpat.”"},{"v":32,"t":"Și soarele a răsărit pentru el când a trecut de Penuel, și el șchiopăta din coapsă."},{"v":33,"t":"De aceea fiii lui Israel nu mănâncă tendonul nervului sciatic care este pe încheietura coapsei, până în ziua aceasta, căci s-a atins de încheietura coapsei lui Iacov, de tendonul nervului sciatic."}]},{"num":33,"title":"Pereq 33 - Capitolul 33","verses":[{"v":1,"t":"Și Iacov și-a ridicat ochii și a văzut, și iată, Esau venea, și cu el patru sute de oameni; și i-a împărțit pe copii între Lea, Rahela și cele două roabe."},{"v":2,"t":"Și a pus roabele și copiii lor în față, pe Lea și copiii ei după ele, iar pe Rahela și pe Iosif la urmă."},{"v":3,"t":"Și el a trecut înaintea lor și s-a plecat până la pământ de șapte ori, până s-a apropiat de fratele său."},{"v":4,"t":"Și Esau a alergat în întâmpinarea lui și l-a îmbrățișat și i-a căzut pe gât și l-a sărutat; și au plâns."},{"v":5,"t":"Și și-a ridicat ochii și a văzut femeile și copiii și a zis: „Cine sunt aceștia ai tăi?” Și el a zis: „Copiii cu care Domnul l-a dăruit pe robul tău.”"},{"v":6,"t":"Și roabele s-au apropiat, ele și copiii lor, și s-au plecat."},{"v":7,"t":"Și s-a apropiat și Lea cu copiii ei, și s-au plecat; și după aceea s-au apropiat Iosif și Rahela și s-au plecat."},{"v":8,"t":"Și a zis: „Ce este pentru tine toată tabăra aceasta pe care am întâlnit-o?” Și el a zis: „Ca să găsesc îndurare în ochii stăpânului meu.”"},{"v":9,"t":"Și Esau a zis: „Am destul, fratele meu; să-ți izbândească ție ce este al tău.”"},{"v":10,"t":"Și Iacov a zis: „Te rog, nu! Dacă am găsit acum îndurare în ochii tăi, primește darul meu din mâna mea; căci de aceea am văzut fața ta ca vederea feței celor mari, și ai fost binevoitor cu mine."},{"v":11,"t":"Primește, te rog, darul meu care ți-a fost adus, căci Domnul S-a îndurat de mine și am de toate.” Și a stăruit la el, și el a primit.","notes":["Ediția are qodam („înaintea”) între paranteze, ca variantă; sensul nu se schimbă."]},{"v":12,"t":"Și a zis: „Să pornim și să mergem, și voi merge alături de tine.”"},{"v":13,"t":"Și el i-a zis: „Stăpânul meu știe că copiii sunt fragezi și oile și vacile care alăptează sunt în grija mea; și dacă le vor mâna o singură zi, vor muri toate oile."},{"v":14,"t":"Să treacă, te rog, stăpânul meu înaintea robului său, iar eu voi merge încet, după pasul vitelor care sunt înaintea mea și după pasul copiilor, până voi ajunge la stăpânul meu, la Seir.”"},{"v":15,"t":"Și Esau a zis: „Să las, te rog, cu tine din oamenii care sunt cu mine.” Și el a zis: „La ce bun? Să găsesc îndurare în ochii stăpânului meu.”"},{"v":16,"t":"Și Esau s-a întors în ziua aceea pe drumul lui spre Seir."},{"v":17,"t":"Și Iacov a pornit spre Sucot și și-a zidit o casă, iar pentru vitele lui a făcut colibe; de aceea a pus locului numele Sucot."},{"v":18,"t":"Și Iacov a ajuns teafăr la cetatea Sihem, care este în țara Canaan, când venea din Padan-Aram, și și-a așezat tabăra în fața cetății.","notes":["Ediția are afe („fața”) între paranteze, ca variantă; sensul nu se schimbă."]},{"v":19,"t":"Și a cumpărat partea de câmp pe care își întinsese cortul de la fiii lui Hamor, tatăl lui Sihem, cu o sută de mielușele.","notes":["„o sută de mielușele” (be-maʾa ḥurfan): Onkelos redă astfel ebraicul qesița, înțeles ca o monedă sau ca miei."]},{"v":20,"t":"Și a ridicat acolo un altar și a slujit pe el înaintea lui Dumnezeu, Dumnezeul lui Israel."}]},{"num":34,"title":"Pereq 34 - Capitolul 34","verses":[{"v":1,"t":"Și Dina, fiica Leei, pe care i-o născuse lui Iacov, a ieșit să vadă fiicele țării."},{"v":2,"t":"Și a văzut-o Sihem, fiul lui Hamor hevitul, căpetenia țării, și a luat-o și s-a culcat cu ea și a necinstit-o."},{"v":3,"t":"Și sufletul lui s-a alipit de Dina, fiica lui Iacov; și a iubit-o pe fată și i-a vorbit pe inimă fetei."},{"v":4,"t":"Și Sihem i-a zis lui Hamor, tatăl său, zicând: „Ia-mi fata aceasta de soție.”"},{"v":5,"t":"Și Iacov a auzit că o pângărise pe Dina, fiica lui; iar fiii lui erau cu vitele lui la câmp; și Iacov a tăcut până la venirea lor."},{"v":6,"t":"Și Hamor, tatăl lui Sihem, a ieșit la Iacov ca să vorbească cu el."},{"v":7,"t":"Și fiii lui Iacov au venit de la câmp când au auzit; și oamenii s-au mâhnit și s-au mâniat foarte tare, căci făcuse o rușine în Israel culcându-se cu fiica lui Iacov, iar așa ceva nu se cuvine să se facă."},{"v":8,"t":"Și Hamor a vorbit cu ei, zicând: „Sufletul lui Sihem, fiul meu, s-a alipit de fiica voastră; dați-i-o, vă rog, de soție."},{"v":9,"t":"Și încuscriți-vă cu noi: fiicele voastre să ni le dați nouă, iar fiicele noastre să le luați voi."},{"v":10,"t":"Și cu noi veți locui, și țara va fi înaintea voastră; locuiți și faceți negoț în ea și dobândiți proprietăți în ea.”"},{"v":11,"t":"Și Sihem a zis tatălui ei și fraților ei: „Să găsesc îndurare în ochii voștri, și ce-mi veți spune voi da."},{"v":12,"t":"Cereți-mi foarte multă zestre și daruri, și voi da cum îmi veți spune; numai dați-mi fata de soție.”"},{"v":13,"t":"Și fiii lui Iacov i-au răspuns lui Sihem și lui Hamor, tatăl lui, cu iscusință (sau „viclenie”) și au vorbit, pentru că o pângărise pe Dina, sora lor."},{"v":14,"t":"Și le-au zis: „Nu putem face lucrul acesta, să dăm pe sora noastră unui om care are prepuț, căci aceasta este o rușine pentru noi."},{"v":15,"t":"Numai cu aceasta ne vom învoi cu voi: dacă veți fi ca noi, tăindu-vă împrejur orice parte bărbătească."},{"v":16,"t":"Atunci vă vom da fiicele noastre, iar fiicele voastre le vom lua noi, și vom locui cu voi și vom fi un singur popor."},{"v":17,"t":"Iar dacă nu ne veți asculta, ca să vă tăiați împrejur, ne vom lua fata și vom pleca.”"},{"v":18,"t":"Și cuvintele lor au plăcut lui Hamor și lui Sihem, fiul lui Hamor."},{"v":19,"t":"Și tânărul n-a întârziat să facă lucrul acesta, căci o îndrăgea pe fiica lui Iacov; și el era cel mai cinstit din toată casa tatălui său."},{"v":20,"t":"Și Hamor și Sihem, fiul lui, au venit la poarta cetății lor și au vorbit cu oamenii cetății lor, zicând:"},{"v":21,"t":"„Oamenii aceștia sunt pașnici cu noi; să locuiască în țară și să facă negoț în ea, căci iată, țara este largă înaintea lor; fiicele lor să ni le luăm de soții, iar fiicele noastre să le dăm lor."},{"v":22,"t":"Numai cu aceasta se vor învoi cu noi oamenii să locuiască cu noi, ca să fim un singur popor: să ne tăiem împrejur orice parte bărbătească, așa cum sunt ei tăiați împrejur."},{"v":23,"t":"Vitele lor și averea lor și toate dobitoacele lor, oare nu vor fi ale noastre? Numai să ne învoim cu ei, și vor locui cu noi.”"},{"v":24,"t":"Și toți cei care ieșeau pe poarta cetății lui i-au ascultat pe Hamor și pe Sihem, fiul lui; și s-a tăiat împrejur orice parte bărbătească, toți cei care ieșeau pe poarta cetății lui."},{"v":25,"t":"Și a fost, în ziua a treia, când durerile îi copleșeau, că doi dintre fiii lui Iacov, Simeon și Levi, frații Dinei, și-au luat fiecare sabia și au intrat în cetatea care stătea fără grijă și au ucis orice parte bărbătească."},{"v":26,"t":"Și pe Hamor și pe Sihem, fiul lui, i-au ucis cu ascuțișul sabiei și au luat-o pe Dina din casa lui Sihem și au ieșit."},{"v":27,"t":"Fiii lui Iacov au intrat să-i jefuiască pe cei uciși și au prădat cetatea, pentru că o pângăriseră pe sora lor."},{"v":28,"t":"Oile lor și boii lor și măgarii lor și ce era în cetate și ce era în câmp le-au prădat."},{"v":29,"t":"Și toată averea lor și pe toți copiii lor și pe femeile lor i-au luat prizonieri și i-au prădat, și tot ce era în casă."},{"v":30,"t":"Și Iacov le-a zis lui Simeon și lui Levi: „M-ați tulburat, punând dușmănie între noi și locuitorii țării, între canaaniți și ferezi; iar eu sunt un popor puțin la număr, și se vor aduna împotriva mea și mă vor lovi, și voi fi nimicit, eu și casa mea.”"},{"v":31,"t":"Și ei au zis: „Să fie tratată sora noastră ca o femeie din afară?”","notes":["„ca o femeie din afară” (ke-nafqat bara): Onkelos redă astfel ebraicul „ca pe o desfrânată”. Ediția are și o notă de variantă la verb, netradusă în text."]}]},{"num":35,"title":"Pereq 35 - Capitolul 35","verses":[{"v":1,"t":"Și Domnul i-a zis lui Iacov: „Ridică-te, urcă la Betel și locuiește acolo; și fă acolo un altar Dumnezeului care ți S-a descoperit când fugeai dinaintea lui Esau, fratele tău.”"},{"v":2,"t":"Și Iacov a zis casei sale și tuturor celor care erau cu el: „Îndepărtați idolii neamurilor care sunt în mijlocul vostru și curățați-vă și schimbați-vă hainele."},{"v":3,"t":"Și să ne ridicăm și să urcăm la Betel, și voi face acolo un altar Dumnezeului care mi-a primit rugăciunea în ziua strâmtorării mele, și Cuvântul Lui a fost în ajutorul meu pe drumul pe care am mers.”"},{"v":4,"t":"Și i-au dat lui Iacov toți idolii neamurilor care erau în mâinile lor și cerceii care erau în urechile lor; și Iacov i-a ascuns sub terebintul care este lângă Sihem."},{"v":5,"t":"Și au pornit; și frica Domnului a fost peste neamurile din cetățile dimprejurul lor, și n-au urmărit pe fiii lui Iacov."},{"v":6,"t":"Și Iacov a ajuns la Luz, care este în țara Canaan, adică Betel, el și tot poporul care era cu el."},{"v":7,"t":"Și a zidit acolo un altar și a pus locului numele El-Betel, căci acolo i Se descoperise Domnul când fugea dinaintea fratelui său."},{"v":8,"t":"Și Debora, doica Rebecăi, a murit și a fost îngropată mai jos de Betel, la poalele câmpiei; și i-a pus numele „Câmpia plânsului”.","notes":["„Câmpia plânsului”: ebraica are Alon-Bacut („stejarul plânsului”); Onkelos are mișar bekhita."]},{"v":9,"t":"Și Domnul i S-a descoperit iar lui Iacov, când venea din Padan-Aram, și l-a binecuvântat."},{"v":10,"t":"Și Domnul i-a zis: „Numele tău este Iacov; nu ți se va mai numi numele Iacov, ci Israel va fi numele tău.” Și i-a pus numele Israel."},{"v":11,"t":"Și Domnul i-a zis: „Eu sunt Dumnezeul Atotputernic (El Șadai); fii roditor și înmulțește-te; un popor și o adunare de seminții vor ieși din tine, și regi care stăpânesc peste neamuri vor ieși din tine."},{"v":12,"t":"Și țara pe care am dat-o lui Avraam și lui Isaac ți-o voi da ție, și urmașilor tăi după tine le voi da țara.”"},{"v":13,"t":"Și Slava Domnului S-a înălțat de la el, din locul unde vorbise cu el."},{"v":14,"t":"Și Iacov a ridicat un stâlp în locul unde vorbise cu el, un stâlp de piatră, și a turnat pe el turnări de jertfă și a vărsat pe el untdelemn."},{"v":15,"t":"Și Iacov a pus locului unde vorbise Domnul cu el numele Betel."},{"v":16,"t":"Și au pornit de la Betel; și mai era o bucată de drum până să ajungă la Efrata, când Rahela a născut, și nașterea i-a fost grea."},{"v":17,"t":"Și a fost, pe când nașterea îi era grea, că moașa i-a zis: „Nu te teme, căci și acesta este un fiu pentru tine.”"},{"v":18,"t":"Și a fost, când îi ieșea sufletul, căci murea, că i-a pus numele Bar-Doi („fiul durerii mele”); dar tatăl lui l-a numit Beniamin.","notes":["„Bar-Doi” (bar dewai/doi = „fiul durerii mele”): așa redă Onkelos numele ebraic Ben-Oni."]},{"v":19,"t":"Și Rahela a murit și a fost îngropată pe drumul spre Efrata, adică Betleem."},{"v":20,"t":"Și Iacov a ridicat un stâlp pe mormântul ei; acesta este stâlpul mormântului Rahelei până în ziua aceasta."},{"v":21,"t":"Și Israel a pornit și și-a întins cortul dincolo de Migdal-Eder."},{"v":22,"t":"Și a fost, când locuia Israel în țara aceea, că Ruben s-a dus și s-a culcat cu Bilha, țiitoarea tatălui său; și Israel a auzit. Și fiii lui Iacov erau doisprezece."},{"v":23,"t":"Fiii Leei: întâiul născut al lui Iacov, Ruben, și Simeon și Levi și Iuda și Isahar și Zabulon."},{"v":24,"t":"Fiii Rahelei: Iosif și Beniamin."},{"v":25,"t":"Și fiii Bilhei, roaba Rahelei: Dan și Neftali."},{"v":26,"t":"Și fiii Zilpei, roaba Leei: Gad și Așer. Aceștia sunt fiii lui Iacov, care i s-au născut în Padan-Aram."},{"v":27,"t":"Și Iacov a venit la Isaac, tatăl său, la Mamre, la Chiriat-Arba, adică Hebron, unde locuiseră ca străini Avraam și Isaac."},{"v":28,"t":"Și zilele lui Isaac au fost o sută optzeci de ani."},{"v":29,"t":"Și Isaac și-a dat sufletul și a murit și a fost adunat la poporul său, bătrân și sătul de zile; și l-au îngropat Esau și Iacov, fiii lui."}]},{"num":36,"title":"Pereq 36 - Capitolul 36","verses":[{"v":1,"t":"Și acestea sunt istorisirile lui Esau, adică Edom."},{"v":2,"t":"Esau și-a luat soțiile dintre fiicele Canaanului: pe Ada, fiica lui Elon hetitul, și pe Oholibama, fiica lui Ana, fiica lui Țibeon hevitul,"},{"v":3,"t":"și pe Basmat, fiica lui Ismael, sora lui Nebaiot."},{"v":4,"t":"Și Ada i l-a născut lui Esau pe Elifaz, iar Basmat l-a născut pe Reuel."},{"v":5,"t":"Și Oholibama i-a născut pe Ieuș și pe Ialam și pe Core. Aceștia sunt fiii lui Esau, care i s-au născut în țara Canaan."},{"v":6,"t":"Și Esau și-a luat soțiile și fiii și fiicele și toate sufletele casei lui și vitele și toate dobitoacele și toată averea pe care o agonisise în țara Canaan și s-a dus în altă țară, departe de Iacov, fratele său."},{"v":7,"t":"Căci averea lor era prea mare ca să locuiască împreună, și țara în care locuiau ca străini nu-i putea purta din pricina vitelor lor."},{"v":8,"t":"Și Esau a locuit în muntele Seir; Esau este Edom."},{"v":9,"t":"Și acestea sunt istorisirile lui Esau, tatăl edomiților, în muntele Seir."},{"v":10,"t":"Acestea sunt numele fiilor lui Esau: Elifaz, fiul Adei, soția lui Esau; Reuel, fiul Basmatei, soția lui Esau."},{"v":11,"t":"Și fiii lui Elifaz au fost: Teman, Omar, Țefo și Gaetam și Chenaz."},{"v":12,"t":"Și Timna era țiitoarea lui Elifaz, fiul lui Esau, și i l-a născut lui Elifaz pe Amalec. Aceștia sunt fiii Adei, soția lui Esau."},{"v":13,"t":"Și aceștia sunt fiii lui Reuel: Nahat și Zerah, Șama și Miza. Aceștia au fost fiii Basmatei, soția lui Esau."},{"v":14,"t":"Și aceștia au fost fiii Oholibamei, fiica lui Ana, fiica lui Țibeon, soția lui Esau: ea i-a născut lui Esau pe Ieuș și pe Ialam și pe Core."},{"v":15,"t":"Aceștia sunt căpeteniile fiilor lui Esau: fiii lui Elifaz, întâiul născut al lui Esau: căpetenia Teman, căpetenia Omar, căpetenia Țefo, căpetenia Chenaz,"},{"v":16,"t":"căpetenia Core, căpetenia Gaetam, căpetenia Amalec. Aceștia sunt căpeteniile lui Elifaz în țara Edom; aceștia sunt fiii Adei."},{"v":17,"t":"Și aceștia sunt fiii lui Reuel, fiul lui Esau: căpetenia Nahat, căpetenia Zerah, căpetenia Șama, căpetenia Miza. Aceștia sunt căpeteniile lui Reuel în țara Edom; aceștia sunt fiii Basmatei, soția lui Esau."},{"v":18,"t":"Și aceștia sunt fiii Oholibamei, soția lui Esau: căpetenia Ieuș, căpetenia Ialam, căpetenia Core. Aceștia sunt căpeteniile Oholibamei, fiica lui Ana, soția lui Esau."},{"v":19,"t":"Aceștia sunt fiii lui Esau și aceștia sunt căpeteniile lor; el este Edom."},{"v":20,"t":"Aceștia sunt fiii lui Seir horitul, locuitorii țării: Lotan și Șobal și Țibeon și Ana"},{"v":21,"t":"și Dișon și Ețer și Dișan. Aceștia sunt căpeteniile horiților, fiii lui Seir, în țara Edom."},{"v":22,"t":"Și fiii lui Lotan au fost Hori și Hemam; și sora lui Lotan era Timna."},{"v":23,"t":"Și aceștia sunt fiii lui Șobal: Alvan și Manahat și Ebal, Șefo și Onam."},{"v":24,"t":"Și aceștia sunt fiii lui Țibeon: Aia și Ana. Acesta este Ana care i-a găsit pe uriași în pustiu, când păștea măgarii lui Țibeon, tatăl său.","notes":["„uriașii” (gibbaraya): Onkelos redă astfel ebraicul nesigur yemim (după alții: „izvoare calde” sau „catâri”)."]},{"v":25,"t":"Și aceștia sunt copiii lui Ana: Dișon și Oholibama, fiica lui Ana."},{"v":26,"t":"Și aceștia sunt fiii lui Dișan: Hemdan și Eșban și Itran și Cheran."},{"v":27,"t":"Aceștia sunt fiii lui Ețer: Bilhan și Zaavan și Acan."},{"v":28,"t":"Aceștia sunt fiii lui Dișan: Uț și Aran."},{"v":29,"t":"Aceștia sunt căpeteniile horiților: căpetenia Lotan, căpetenia Șobal, căpetenia Țibeon, căpetenia Ana,"},{"v":30,"t":"căpetenia Dișon, căpetenia Ețer, căpetenia Dișan. Aceștia sunt căpeteniile horiților, după căpeteniile lor, în țara Seir."},{"v":31,"t":"Și aceștia sunt regii care au domnit în țara Edom înainte să domnească un rege peste fiii lui Israel."},{"v":32,"t":"Și în Edom a domnit Bela, fiul lui Beor; și numele cetății lui era Dinhaba."},{"v":33,"t":"Și Bela a murit, și în locul lui a domnit Iobab, fiul lui Zerah, din Boțra."},{"v":34,"t":"Și Iobab a murit, și în locul lui a domnit Hușam, din țara sudului."},{"v":35,"t":"Și Hușam a murit, și în locul lui a domnit Hadad, fiul lui Bedad, care i-a ucis pe madianiți în câmpul Moabului; și numele cetății lui era Avit."},{"v":36,"t":"Și Hadad a murit, și în locul lui a domnit Samla, din Masreca."},{"v":37,"t":"Și Samla a murit, și în locul lui a domnit Saul, din Rehobot de lângă Eufrat."},{"v":38,"t":"Și Saul a murit, și în locul lui a domnit Baal-Hanan, fiul lui Acbor."},{"v":39,"t":"Și Baal-Hanan, fiul lui Acbor, a murit, și în locul lui a domnit Hadar; și numele cetății lui era Pau, iar numele soției lui, Mehetabeel, fiica lui Matred, fiica unui topitor de aur.","notes":["„fiica unui topitor de aur” (bat meṣaref dahava): Onkelos explică numele Me-Zahav („ape de aur”)."]},{"v":40,"t":"Și acestea sunt numele căpeteniilor lui Esau, după familiile lor, după locurile lor, după numele lor: căpetenia Timna, căpetenia Alva, căpetenia Ietet,"},{"v":41,"t":"căpetenia Oholibama, căpetenia Ela, căpetenia Pinon,"},{"v":42,"t":"căpetenia Chenaz, căpetenia Teman, căpetenia Mibțar,"},{"v":43,"t":"căpetenia Magdiel, căpetenia Iram. Aceștia sunt căpeteniile Edomului, după locuințele lor, în țara moștenirii lor; el este Esau, tatăl edomiților."}]},{"num":37,"title":"Pereq 37 - Capitolul 37","verses":[{"v":1,"t":"Și Iacov a locuit în țara în care locuise ca străin tatăl său, în țara Canaan."},{"v":2,"t":"Acestea sunt istorisirile lui Iacov. Iosif, în vârstă de șaptesprezece ani, (când) păștea oile cu frații lui, era crescut împreună cu fiii Bilhei și cu fiii Zilpei, soțiile tatălui său; și Iosif aducea la tatăl lor vești rele despre ei.","notes":["„(când)”: ediția are kad între paranteze, ca variantă."]},{"v":3,"t":"Și Israel îl iubea pe Iosif mai mult decât pe toți fiii lui, căci era pentru el un fiu înțelept; și i-a făcut o tunică în dungi."},{"v":4,"t":"Și frații lui au văzut că pe el îl iubea tatăl lor mai mult decât pe toți frații lui, și l-au urât și nu voiau să-i vorbească în pace."},{"v":5,"t":"Și Iosif a visat un vis și l-a spus fraților lui, și l-au urât și mai mult."},{"v":6,"t":"Și le-a zis: „Ascultați, vă rog, visul acesta pe care l-am visat:"},{"v":7,"t":"iată, noi legam snopi în mijlocul câmpului, și iată, snopul meu s-a ridicat și chiar a stat drept; și iată, snopii voștri l-au înconjurat și s-au plecat înaintea snopului meu.”"},{"v":8,"t":"Și frații lui i-au zis: „Oare te gândești să domnești peste noi, sau crezi că vei stăpâni peste noi?” Și l-au urât și mai mult din pricina viselor lui și a cuvintelor lui."},{"v":9,"t":"Și a mai visat un alt vis și l-a povestit fraților lui și a zis: „Iată, am mai visat un vis: și iată, soarele și luna și unsprezece stele se plecau înaintea mea.”"},{"v":10,"t":"Și l-a povestit tatălui său și fraților săi; și tatăl lui l-a certat și i-a zis: „Ce este visul acesta pe care l-ai visat? Oare vom veni eu și mama ta și frații tăi să ne plecăm până la pământ înaintea ta?”"},{"v":11,"t":"Și frații lui l-au pizmuit, iar tatăl lui a păstrat lucrul acesta."},{"v":12,"t":"Și frații lui s-au dus să pască oile tatălui lor la Sihem."},{"v":13,"t":"Și Israel i-a zis lui Iosif: „Nu-i așa că frații tăi pasc la Sihem? Vino, și te voi trimite la ei.” Și el i-a zis: „Iată-mă.”"},{"v":14,"t":"Și i-a zis: „Du-te, te rog, vezi cum le merge fraților tăi și cum le merge oilor și adu-mi vești.” Și l-a trimis din câmpia Hebronului, și el a ajuns la Sihem."},{"v":15,"t":"Și un om l-a găsit, și iată, rătăcea pe câmp; și omul l-a întrebat, zicând: „Ce cauți?”"},{"v":16,"t":"Și el a zis: „Pe frații mei îi caut; spune-mi, te rog, unde pasc ei.”"},{"v":17,"t":"Și omul a zis: „Au plecat de aici, căci i-am auzit zicând: «Să mergem la Dotan.»” Și Iosif s-a dus după frații lui și i-a găsit la Dotan."},{"v":18,"t":"Și ei l-au văzut de departe și, înainte să se apropie de ei, au plănuit împotriva lui să-l ucidă."},{"v":19,"t":"Și au zis unul către altul: „Iată, vine stăpânul viselor acela."},{"v":20,"t":"Și acum, veniți să-l ucidem și să-l aruncăm într-una din gropi și să zicem: «O fiară rea l-a mâncat»; și să vedem ce se va alege de visele lui.”"},{"v":21,"t":"Și Ruben a auzit și l-a scăpat din mâinile lor și a zis: „Să nu-i luăm viața.”"},{"v":22,"t":"Și Ruben le-a zis: „Nu vărsați sânge; aruncați-l în groapa aceasta care este în pustiu, dar mâna să n-o întindeți asupra lui”, ca să-l scape din mâinile lor și să-l ducă înapoi la tatăl său."},{"v":23,"t":"Și a fost, când a ajuns Iosif la frații lui, că l-au dezbrăcat pe Iosif de tunica lui, de tunica în dungi care era pe el."},{"v":24,"t":"Și l-au luat și l-au aruncat în groapă; și groapa era goală, nu era apă în ea."},{"v":25,"t":"Și s-au așezat să mănânce pâine; și și-au ridicat ochii și au văzut, și iată, o caravană de arabi venea din Galaad, iar cămilele lor erau încărcate cu ceară, balsam și mastic, mergând să le coboare în Egipt („Mițrayim”).","notes":["„arabi” (ʿarvaʾe): Onkelos redă astfel „ismaeliți”, aici și în versetele următoare."]},{"v":26,"t":"Și Iuda le-a zis fraților lui: „Ce câștig vom avea dacă îl ucidem pe fratele nostru și îi acoperim sângele?"},{"v":27,"t":"Veniți să-l vindem arabilor, iar mâna noastră să nu fie asupra lui, căci este fratele nostru, carnea noastră.” Și frații lui l-au ascultat."},{"v":28,"t":"Și au trecut niște oameni madianiți, negustori, și l-au tras și l-au scos pe Iosif din groapă și l-au vândut pe Iosif arabilor pentru douăzeci de arginți; și ei l-au dus pe Iosif în Egipt („Mițrayim”)."},{"v":29,"t":"Și Ruben s-a întors la groapă, și iată, Iosif nu era în groapă; și și-a sfâșiat hainele."},{"v":30,"t":"Și s-a întors la frații lui și a zis: „Băiatul nu mai este; și eu, unde să mă duc?”"},{"v":31,"t":"Și au luat tunica lui Iosif și au înjunghiat un țap și au înmuiat tunica în sânge."},{"v":32,"t":"Și au trimis tunica în dungi și au adus-o la tatăl lor și au zis: „Aceasta am găsit-o; cercetează, te rog, dacă este tunica fiului tău sau nu.”"},{"v":33,"t":"Și a recunoscut-o și a zis: „Tunica fiului meu! O fiară rea l-a mâncat; Iosif a fost negreșit ucis.”","notes":["Ebraica are „a fost sfâșiat”; Onkelos are „a fost ucis”."]},{"v":34,"t":"Și Iacov și-a sfâșiat hainele și și-a pus sac pe coapse și a jelit pentru fiul său multe zile."},{"v":35,"t":"Și s-au ridicat toți fiii lui și toate fiicele lui să-l mângâie, dar el n-a voit să primească mângâiere și a zis: „Căci voi coborî la (pentru) fiul meu jelind în Șeol.” Și tatăl lui l-a plâns.","notes":["„la (pentru)”: ediția are lewat („la”) și ʿal („pentru”) între paranteze; traducerea le păstrează pe amândouă. Șeol = lumea morților."]},{"v":36,"t":"Iar madianiții l-au vândut în Egipt („Mițrayim”) lui Potifar, dregătorul lui Faraon, căpetenia călăilor.","notes":["„căpetenia călăilor” (rav qaṭolaya): așa este redat termenul aramaic (literal „căpetenia celor care ucid”); la fel la 39:1, 40:3, 40:4 și în continuare."]}]},{"num":38,"title":"Pereq 38 - Capitolul 38","verses":[{"v":1,"t":"Și a fost, în vremea aceea, că Iuda a coborât de la frații lui și s-a abătut la un om adulamit, al cărui nume era Hira."},{"v":2,"t":"Și Iuda a văzut acolo fiica unui negustor, al cărui nume era Șua; și a luat-o și a intrat la ea.","notes":["„un negustor” (gevar taggara): Onkelos redă astfel „un canaanit”."]},{"v":3,"t":"Și ea a rămas însărcinată și a născut un fiu, și el i-a pus numele Er."},{"v":4,"t":"Și a rămas iar însărcinată și a născut un fiu și i-a pus numele Onan."},{"v":5,"t":"Și a mai născut iar un fiu și i-a pus numele Șela; și el era la Chezib când l-a născut ea."},{"v":6,"t":"Și Iuda a luat o soție pentru Er, întâiul lui născut, al cărei nume era Tamar."},{"v":7,"t":"Și Er, întâiul născut al lui Iuda, era rău înaintea Domnului, și Domnul l-a făcut să moară."},{"v":8,"t":"Și Iuda i-a zis lui Onan: „Intră la soția fratelui tău și ia-o de soție prin levirat și ridică urmași fratelui tău.”"},{"v":9,"t":"Și Onan a știut că urmașii nu vor fi numiți după numele lui; și era, când intra la soția fratelui său, că își strica calea pe pământ, ca să nu ridice urmași fratelui său."},{"v":10,"t":"Și ce a făcut a fost rău înaintea Domnului, și l-a făcut și pe el să moară."},{"v":11,"t":"Și Iuda i-a zis Tamarei, nora lui: „Rămâi văduvă în casa tatălui tău până va crește Șela, fiul meu”; căci a zis: „Ca nu cumva să moară și el ca frații lui.” Și Tamar s-a dus și a locuit în casa tatălui ei."},{"v":12,"t":"Și zilele s-au înmulțit, și fiica lui Șua, soția lui Iuda, a murit; și Iuda s-a mângâiat și a urcat la tunzătorii oilor lui, el și Hira, prietenul lui adulamitul, la Timna."},{"v":13,"t":"Și i s-a spus Tamarei, zicând: „Iată, socrul tău urcă la Timna să-și tundă oile.”"},{"v":14,"t":"Și și-a scos hainele de văduvie și s-a acoperit cu un văl și s-a gătit și s-a așezat la răscrucea de la Enaim, care este pe drumul spre Timna; căci vedea că Șela crescuse, iar ea nu-i fusese dată de soție."},{"v":15,"t":"Și Iuda a văzut-o și a socotit-o o femeie din afară, căci își acoperise fața."},{"v":16,"t":"Și s-a abătut la ea, la drum, și a zis: „Lasă-mă, te rog, să intru la tine”; căci nu știa că era nora lui. Și ea a zis: „Ce-mi vei da, ca să intri la mine?”"},{"v":17,"t":"Și el a zis: „Îți voi trimite un ied din turmă.” Și ea a zis: „Dacă îmi dai un zălog până îl trimiți.”"},{"v":18,"t":"Și el a zis: „Ce zălog să-ți dau?” Și ea a zis: „Inelul tău cu sigiliu și mantia ta și toiagul tău din mâna ta.” Și i le-a dat și a intrat la ea, și ea a rămas însărcinată de la el."},{"v":19,"t":"Și s-a ridicat și a plecat și și-a scos vălul și s-a îmbrăcat cu hainele de văduvie."},{"v":20,"t":"Și Iuda a trimis iedul prin mâna prietenului său adulamitul, ca să ia zălogul din mâna femeii; dar el n-a găsit-o."},{"v":21,"t":"Și i-a întrebat pe oamenii locului ei, zicând: „Unde este desfrânata care era la Enaim, pe drum?” Și ei au zis: „N-a fost aici nicio desfrânată.”","notes":["„desfrânata” (meqaddešta): Onkelos păstrează termenul ebraic qedeșa."]},{"v":22,"t":"Și s-a întors la Iuda și a zis: „N-am găsit-o; și chiar oamenii locului au zis: «N-a fost aici nicio desfrânată.»”"},{"v":23,"t":"Și Iuda a zis: „Să le ia pentru ea, ca să nu ajungem de batjocură; iată, am trimis iedul acesta, iar tu n-ai găsit-o.”"},{"v":24,"t":"Și a fost, după vreo trei luni, că i s-a spus lui Iuda, zicând: „Tamar, nora ta, s-a desfrânat și, iată, a rămas chiar însărcinată din desfrânare.” Și Iuda a zis: „Scoateți-o, și să fie arsă.”"},{"v":25,"t":"Pe când era scoasă, ea a trimis la socrul ei, zicând: „De la omul ale cărui sunt acestea am rămas însărcinată.” Și a zis: „Cercetează, te rog, ale cui sunt inelul cu sigiliu, mantia și toiagul acestea.”"},{"v":26,"t":"Și Iuda le-a recunoscut și a zis: „Ea este nevinovată; de la mine a rămas însărcinată, căci de aceea nu i l-am dat pe Șela, fiul meu.” Și n-a mai cunoscut-o."},{"v":27,"t":"Și a fost, la vremea nașterii ei, și iată, erau gemeni în pântecele ei."},{"v":28,"t":"Și a fost, când năștea, că unul a scos mâna; și moașa a luat și a legat la mâna lui un fir de stacojiu, zicând: „Acesta a ieșit primul.”"},{"v":29,"t":"Și a fost, când și-a tras mâna înapoi, iată, a ieșit fratele lui; și ea a zis: „Ce putere mare ai avut, ca să te întărești!” Și i-a pus numele Pereț."},{"v":30,"t":"Și după aceea a ieșit fratele lui, care avea la mână firul de stacojiu; și i-a pus numele Zerah."}]},{"num":39,"title":"Pereq 39 - Capitolul 39","verses":[{"v":1,"t":"Și Iosif a fost coborât în Egipt („Mițrayim”); și Potifar, dregătorul lui Faraon, căpetenia călăilor, un om egiptean, l-a cumpărat din mâna arabilor care îl coborâseră acolo."},{"v":2,"t":"Și Cuvântul Domnului a fost în ajutorul lui Iosif, și el a fost un om căruia îi izbutea totul; și era în casa stăpânului său, egipteanul."},{"v":3,"t":"Și stăpânul lui a văzut că Cuvântul Domnului era în ajutorul lui și că tot ce făcea el, Domnul făcea să izbutească în mâna lui."},{"v":4,"t":"Și Iosif a găsit îndurare în ochii lui și îi slujea; și l-a pus peste casa lui și tot ce avea i-a dat în mână."},{"v":5,"t":"Și a fost, de când l-a pus peste casa lui și peste tot ce avea, că Domnul a binecuvântat casa egipteanului pentru Iosif; și binecuvântarea Domnului a fost peste tot ce avea, în casă și în câmp."},{"v":6,"t":"Și a lăsat tot ce avea în mâna lui Iosif și nu știa cu el de nimic, decât de pâinea pe care o mânca. Și Iosif era frumos la chip și frumos la înfățișare."},{"v":7,"t":"Și a fost, după lucrurile acestea, că soția stăpânului său și-a ridicat ochii spre Iosif și a zis: „Culcă-te cu mine.”"},{"v":8,"t":"Dar el a refuzat și i-a zis soției stăpânului său: „Iată, stăpânul meu nu știe cu mine ce este în casă, și tot ce are mi-a dat în mână."},{"v":9,"t":"Nu este nimeni mai mare în casa aceasta decât mine, și nu mi-a oprit nimic, decât pe tine, pentru că ești soția lui. Și cum să fac eu răul acesta mare și să păcătuiesc înaintea Domnului?”"},{"v":10,"t":"Și a fost, deși ea îi vorbea lui Iosif zi de zi, el n-a ascultat-o, ca să se culce lângă ea, ca să fie cu ea."},{"v":11,"t":"Și a fost, într-o astfel de zi, că el a intrat în casă ca să cerceteze socotelile lui, și nu era niciunul din oamenii casei acolo, în casă.","notes":["„ca să cerceteze socotelile lui”: Onkelos explică „să-și facă lucrul”."]},{"v":12,"t":"Și ea l-a apucat de haină, zicând: „Culcă-te cu mine.” Și el și-a lăsat haina în mâna ei și a fugit și a ieșit afară, în piață."},{"v":13,"t":"Și a fost, când a văzut că își lăsase haina în mâna ei și fugise în piață,"},{"v":14,"t":"că i-a chemat pe oamenii casei ei și le-a vorbit, zicând: „Vedeți, ne-a adus un om evreu ca să-și bată joc de noi; a intrat la mine ca să se culce cu mine, și am strigat cu glas tare."},{"v":15,"t":"Și a fost, când a auzit că mi-am ridicat glasul și am strigat, că și-a lăsat haina lângă mine și a fugit și a ieșit în piață.”"},{"v":16,"t":"Și ea i-a pus haina lângă ea, până a venit stăpânul lui acasă."},{"v":17,"t":"Și i-a vorbit după cuvintele acestea, zicând: „A intrat la mine robul evreu pe care ni l-ai adus, ca să-și bată joc de mine."},{"v":18,"t":"Și a fost, când mi-am ridicat glasul și am strigat, că și-a lăsat haina lângă mine și a fugit în piață.”"},{"v":19,"t":"Și a fost, când stăpânul lui a auzit cuvintele soției lui, pe care i le-a spus, zicând: „Așa mi-a făcut robul tău”, că mânia i s-a aprins."},{"v":20,"t":"Și stăpânul lui Iosif l-a luat și l-a pus în închisoare, locul unde erau închiși prizonierii regelui; și a fost acolo, în închisoare."},{"v":21,"t":"Și Cuvântul Domnului a fost în ajutorul lui Iosif și i-a întins bunătatea și i-a dat îndurare în ochii căpeteniei închisorii."},{"v":22,"t":"Și căpetenia închisorii a dat în mâna lui Iosif pe toți prizonierii din închisoare; și tot ce se făcea acolo, după cuvântul lui se făcea."},{"v":23,"t":"Căpetenia închisorii nu vedea nicio vină în mâna lui, pentru că Cuvântul Domnului era în ajutorul lui; și ce făcea el, Domnul făcea să izbutească."}]},{"num":40,"title":"Pereq 40 - Capitolul 40","verses":[{"v":1,"t":"Și a fost, după lucrurile acestea, că paharnicul regelui Egiptului („Mițrayim”) și pitarul au greșit față de stăpânul lor, față de regele Egiptului."},{"v":2,"t":"Și Faraon s-a mâniat pe cei doi dregători ai lui, pe căpetenia paharnicilor și pe căpetenia pitarilor."},{"v":3,"t":"Și i-a pus sub pază în casa căpeteniei călăilor, în închisoare, locul unde era închis Iosif."},{"v":4,"t":"Și căpetenia călăilor l-a pus pe Iosif cu ei, și el îi slujea; și au fost zile sub pază."},{"v":5,"t":"Și au visat amândoi un vis, fiecare visul lui, în aceeași noapte, fiecare după tâlcuirea visului său: paharnicul și pitarul regelui Egiptului („Mițrayim”), care erau închiși în închisoare."},{"v":6,"t":"Și Iosif a venit la ei dimineața și i-a văzut, și iată, erau mâhniți."},{"v":7,"t":"Și i-a întrebat pe dregătorii lui Faraon care erau cu el sub pază în casa stăpânului său, zicând: „De ce aveți fețele triste astăzi?”"},{"v":8,"t":"Și ei i-au zis: „Am visat un vis și nu este nimeni care să-l tâlcuiască.” Și Iosif le-a zis: „Nu oare de la Domnul sunt tâlcuirile viselor? Povestiți-mi, vă rog.”"},{"v":9,"t":"Și căpetenia paharnicilor i-a povestit lui Iosif visul său și i-a zis: „În visul meu, iată, o viță era înaintea mea."},{"v":10,"t":"Și în viță erau trei mlădițe; și ea, când a înmugurit, a scos muguri și a înflorit, iar ciorchinii ei s-au copt în struguri."},{"v":11,"t":"Și paharul lui Faraon era în mâna mea; și am luat strugurii și i-am stors în paharul lui Faraon și am dat paharul în mâna lui Faraon.”"},{"v":12,"t":"Și Iosif i-a zis: „Aceasta este tâlcuirea lui: cele trei mlădițe sunt trei zile."},{"v":13,"t":"La sfârșitul celor trei zile Faraon îți va pomeni capul (sau „îți va ridica capul”) și te va pune înapoi în slujba ta, și vei da paharul lui Faraon în mâna lui, după rânduiala dintâi, când îi erai paharnic."},{"v":14,"t":"Numai să-ți aduci aminte de mine când îți va fi bine, și fă-mi, te rog, o bunătate: pomenește-mă înaintea lui Faraon și scoate-mă din închisoarea aceasta."},{"v":15,"t":"Căci am fost furat din țara evreilor; și nici aici n-am făcut nimic, ca să mă pună în închisoare.”"},{"v":16,"t":"Și căpetenia pitarilor a văzut că tâlcuise bine și i-a zis lui Iosif: „Și eu, în visul meu, iată, trei coșuri cu pâine albă erau pe capul meu."},{"v":17,"t":"Și în coșul de sus erau din toate mâncărurile lui Faraon, lucrare de pitar; și păsările le mâncau din coș, de pe capul meu.”"},{"v":18,"t":"Și Iosif a răspuns și a zis: „Aceasta este tâlcuirea lui: cele trei coșuri sunt trei zile."},{"v":19,"t":"La sfârșitul celor trei zile Faraon îți va lua capul de pe tine și te va spânzura pe o spânzurătoare, și păsările îți vor mânca carnea de pe tine.”"},{"v":20,"t":"Și a fost, în ziua a treia, ziua nașterii lui Faraon, că a făcut un ospăț pentru toți slujitorii lui; și a pomenit capul căpeteniei paharnicilor și capul căpeteniei pitarilor în mijlocul slujitorilor lui."},{"v":21,"t":"Și pe căpetenia paharnicilor l-a pus înapoi în slujba de paharnic, și el a dat paharul în mâna lui Faraon."},{"v":22,"t":"Iar pe căpetenia pitarilor l-a spânzurat, cum le tâlcuise Iosif."},{"v":23,"t":"Și căpetenia paharnicilor nu și-a adus aminte de Iosif, ci l-a uitat."}]},{"num":41,"title":"Pereq 41 - Capitolul 41","verses":[{"v":1,"t":"Și a fost, la sfârșitul a doi ani, că Faraon a visat, și iată, stătea lângă râu."},{"v":2,"t":"Și iată, din râu urcau șapte vaci frumoase la vedere și grase la carne, și pășteau în pajiște."},{"v":3,"t":"Și iată, alte șapte vaci urcau după ele din râu, urâte la vedere și slabe la carne, și au stat lângă vaci, pe malul râului."},{"v":4,"t":"Și vacile urâte la vedere și slabe la carne au mâncat cele șapte vaci frumoase la vedere și grase. Și Faraon s-a trezit."},{"v":5,"t":"Și a adormit și a visat a doua oară, și iată, șapte spice urcau pe un singur pai, grase și bune."},{"v":6,"t":"Și iată, șapte spice slabe și pârlite de vântul de răsărit răsăreau după ele."},{"v":7,"t":"Și spicele slabe au înghițit cele șapte spice grase și pline. Și Faraon s-a trezit, și iată, era un vis."},{"v":8,"t":"Și a fost, dimineața, că duhul lui era tulburat; și a trimis și i-a chemat pe toți vrăjitorii Egiptului („Mițrayim”) și pe toți înțelepții lui; și Faraon le-a povestit visul său, dar nu era nimeni care să i-l tâlcuiască lui Faraon."},{"v":9,"t":"Și căpetenia paharnicilor a vorbit cu Faraon, zicând: „Greșeala mea mi-o aduc aminte astăzi.","notes":["Ediția are cuvintele „cu Faraon” de două ori (o dată între paranteze), ca variantă; traducerea le redă o singură dată."]},{"v":10,"t":"Faraon s-a mâniat pe slujitorii lui și m-a pus sub pază în casa căpeteniei gărzii, pe mine și pe căpetenia pitarilor."},{"v":11,"t":"Și am visat un vis în aceeași noapte, eu și el; fiecare după tâlcuirea visului său am visat."},{"v":12,"t":"Și acolo era cu noi un tânăr evreu, rob al căpeteniei gărzii; și i-am povestit, și ne-a tâlcuit visele; fiecăruia după visul lui i-a tâlcuit."},{"v":13,"t":"Și a fost așa cum ne-a tâlcuit: pe mine m-a pus înapoi în slujba mea, iar pe el l-a spânzurat.”"},{"v":14,"t":"Și Faraon a trimis și l-a chemat pe Iosif, și l-au scos în grabă din închisoare; și s-a bărbierit și și-a schimbat hainele și a intrat la Faraon."},{"v":15,"t":"Și Faraon i-a zis lui Iosif: „Am visat un vis și nu este nimeni care să-l tâlcuiască; și eu am auzit despre tine zicându-se că, auzind un vis, îl tâlcuiești.”"},{"v":16,"t":"Și Iosif i-a răspuns lui Faraon, zicând: „Nu din înțelepciunea mea, ci de la Domnul va fi dat răspuns spre binele lui Faraon.”"},{"v":17,"t":"Și Faraon i-a vorbit lui Iosif: „În visul meu, iată, stăteam pe malul râului."},{"v":18,"t":"Și iată, din râu urcau șapte vaci grase la carne și frumoase la vedere și pășteau în pajiște."},{"v":19,"t":"Și iată, alte șapte vaci urcau după ele, sărace și foarte urâte la vedere și slabe la carne; n-am văzut altele ca ele în toată țara Egiptului („Mițrayim”), de urâte."},{"v":20,"t":"Și vacile cele sărace și urâte au mâncat cele dintâi șapte vaci grase."},{"v":21,"t":"Și au intrat în pântecele lor, și nu se cunoștea că intraseră în pântecele lor, iar înfățișarea lor era urâtă ca la început. Și m-am trezit."},{"v":22,"t":"Și am văzut în visul meu, și iată, șapte spice urcau pe un singur pai, pline și bune."},{"v":23,"t":"Și iată, șapte spice uscate, slabe, pârlite de vântul de răsărit răsăreau după ele."},{"v":24,"t":"Și spicele slabe au înghițit cele șapte spice bune. Și am spus vrăjitorilor, dar nu este nimeni care să mi-l lămurească.”"},{"v":25,"t":"Și Iosif i-a zis lui Faraon: „Visul lui Faraon este unul singur; ce va face Domnul i-a vestit lui Faraon."},{"v":26,"t":"Cele șapte vaci bune sunt șapte ani, și cele șapte spice bune sunt șapte ani; visul este unul singur."},{"v":27,"t":"Și cele șapte vaci sărace și urâte, care urcau după ele, sunt șapte ani, iar cele șapte spice slabe, pârlite de vântul de răsărit, vor fi șapte ani de foamete."},{"v":28,"t":"Acesta este lucrul pe care i l-am spus lui Faraon: ce va face Domnul i-a arătat lui Faraon."},{"v":29,"t":"Iată, vin șapte ani de mare belșug în toată țara Egiptului („Mițrayim”)."},{"v":30,"t":"Și după ei se vor ridica șapte ani de foamete, și va fi uitat tot belșugul în țara Egiptului („Mițrayim”), și foametea va nimici (poporul) țării.","notes":["„(poporul)”: ediția are ʿamma de („poporul”) între paranteze, ca variantă; la fel la 41:36 (laʿamma de)."]},{"v":31,"t":"Și belșugul nu se va mai cunoaște în țară din pricina foametei aceleia care va fi după aceea, căci va fi foarte grea."},{"v":32,"t":"Și pentru că visul i s-a repetat lui Faraon de două ori, este pentru că lucrul este hotărât de la Domnul, și Domnul Se grăbește să-l facă."},{"v":33,"t":"Și acum, să caute Faraon un om priceput și înțelept și să-l pună peste țara Egiptului („Mițrayim”)."},{"v":34,"t":"Să facă Faraon și să pună oameni de încredere peste țară și să pregătească țara Egiptului („Mițrayim”) în cei șapte ani de belșug."},{"v":35,"t":"Și să adune toate grânele acestor ani buni care vin și să strângă grâne sub mâna oamenilor de încredere ai lui Faraon, grâne în cetăți, și să le păzească."},{"v":36,"t":"Și grânele să fie păstrate pentru (poporul) țării pentru cei șapte ani de foamete care vor fi în țara Egiptului („Mițrayim”), ca să nu piară poporul țării de foamete.”"},{"v":37,"t":"Și lucrul a plăcut în ochii lui Faraon și în ochii tuturor slujitorilor lui."},{"v":38,"t":"Și Faraon le-a zis slujitorilor lui: „Vom găsi oare un om ca acesta, în care este duhul profeției de la Domnul?”"},{"v":39,"t":"Și Faraon i-a zis lui Iosif: „După ce Domnul ți-a făcut cunoscut toate acestea, nu este nimeni priceput și înțelept ca tine."},{"v":40,"t":"Tu vei fi pus peste casa mea, și după cuvântul tău va fi hrănit tot poporul meu; numai prin tronul domniei acesteia voi fi mai mare decât tine.”"},{"v":41,"t":"Și Faraon i-a zis lui Iosif: „Vezi, te-am pus peste toată țara Egiptului („Mițrayim”).”"},{"v":42,"t":"Și Faraon și-a scos inelul cu sigiliu de pe mână și l-a pus pe mâna lui Iosif și l-a îmbrăcat cu haine de in subțire și i-a pus un lanț de aur la gât."},{"v":43,"t":"Și l-a pus să călărească în carul al doilea al lui și au strigat înaintea lui: „Acesta este tatăl regelui!” Și l-a pus peste toată țara Egiptului („Mițrayim”).","notes":["„Acesta este tatăl regelui!” (den aba le-malka): așa explică Onkelos strigătul ebraic avrekh. Ediția are și o notă de variantă la „al doilea”."]},{"v":44,"t":"Și Faraon i-a zis lui Iosif: „Eu sunt Faraon; dar fără cuvântul tău nimeni nu-și va ridica mâna ca să apuce arma, nici piciorul ca să încalece pe cal, în toată țara Egiptului („Mițrayim”).”"},{"v":45,"t":"Și Faraon i-a pus lui Iosif numele „Omul căruia i se descoperă cele ascunse” și i-a dat de soție pe Asenat, fiica lui Poti-Fera, căpetenia din On. Și Iosif a ieșit (stăpânitor) peste țara Egiptului („Mițrayim”).","notes":["„Omul căruia i se descoperă cele ascunse” (gavra di-mṭamran galyan leh): Onkelos traduce numele egiptean Țafnat-Paneah. „căpetenia din On” (rabba de-On): Onkelos redă astfel „preotul din On”."]},{"v":46,"t":"Și Iosif era în vârstă de treizeci de ani când a stat înaintea lui Faraon, regele Egiptului („Mițrayim”). Și Iosif a ieșit dinaintea lui Faraon și a trecut (stăpânitor) prin toată țara Egiptului.","notes":["„(stăpânitor)”: la 41:45 și 41:46 ediția are cuvântul șallit între paranteze, ca variantă; traducerea îl păstrează în paranteze."]},{"v":47,"t":"Și locuitorii țării au strâns în cei șapte ani de belșug grâne în hambare."},{"v":48,"t":"Și a strâns toate grânele celor șapte ani care au fost în țara Egiptului („Mițrayim”) și a pus grâne în cetăți; grânele câmpului cetății, care erau de jur împrejurul ei, le-a pus în ea."},{"v":49,"t":"Și Iosif a strâns grâne ca nisipul mării, foarte multe, până a încetat să le mai numere, căci nu mai aveau număr."},{"v":50,"t":"Și lui Iosif i s-au născut doi fii, înainte să vină anul foametei, pe care i i-a născut Asenat, fiica lui Poti-Fera, căpetenia din On."},{"v":51,"t":"Și Iosif i-a pus întâiului născut numele Manase, „căci Domnul m-a făcut să uit toată truda mea și toată casa tatălui meu”."},{"v":52,"t":"Și celui de-al doilea i-a pus numele Efraim, „căci Domnul m-a făcut roditor în țara robiei mele”."},{"v":53,"t":"Și s-au sfârșit cei șapte ani de belșug care au fost în țara Egiptului („Mițrayim”)."},{"v":54,"t":"Și au început să vină cei șapte ani de foamete, cum spusese Iosif; și a fost foamete în toate țările, dar în toată țara Egiptului („Mițrayim”) era pâine."},{"v":55,"t":"Și toată țara Egiptului („Mițrayim”) a flămânzit, și poporul a strigat înaintea lui Faraon după pâine; și Faraon a zis tuturor egiptenilor: „Duceți-vă la Iosif; ce vă va spune, să faceți.”"},{"v":56,"t":"Și foametea era pe toată fața pământului; și Iosif a deschis toate locurile în care erau grâne și a vândut egiptenilor; și foametea s-a întărit în țara Egiptului („Mițrayim”)."},{"v":57,"t":"Și toți locuitorii pământului au venit în Egipt („Mițrayim”) să cumpere grâne de la Iosif, căci foametea se întărise pe tot pământul."}]},{"num":42,"title":"Pereq 42 - Capitolul 42","verses":[{"v":1,"t":"Și Iacov a văzut că se vindeau grâne în Egipt („Mițrayim”); și Iacov le-a zis fiilor lui: „De ce vă tot uitați unul la altul?”"},{"v":2,"t":"Și a zis: „Iată, am auzit că se vând grâne în Egipt („Mițrayim”); coborâți acolo și cumpărați-ne de acolo, ca să trăim și să nu murim.”"},{"v":3,"t":"Și zece frați ai lui Iosif au coborât să cumpere grâne din Egipt („Mițrayim”)."},{"v":4,"t":"Dar pe Beniamin, fratele lui Iosif, Iacov nu l-a trimis cu frații lui, căci a zis: „Ca nu cumva să-l ajungă moartea.”"},{"v":5,"t":"Și fiii lui Israel au venit să cumpere grâne printre cei care veneau, căci era foamete în țara Canaan."},{"v":6,"t":"Și Iosif era stăpânitorul țării; el era cel care vindea grâne întregului popor al țării. Și frații lui Iosif au venit și s-au plecat înaintea lui cu fața la pământ."},{"v":7,"t":"Și Iosif i-a văzut pe frații lui și i-a recunoscut; și a chibzuit ce să le spună și le-a vorbit aspru și le-a zis: „De unde ați venit?” Și ei au zis: „Din țara Canaan, ca să cumpărăm grâne.”"},{"v":8,"t":"Și Iosif i-a recunoscut pe frații lui, dar ei nu l-au recunoscut."},{"v":9,"t":"Și Iosif și-a adus aminte de visele pe care le visase despre ei și le-a zis: „Sunteți iscoade; ați venit să vedeți părțile slabe ale țării.”","notes":["„părțile slabe ale țării” (bidqa de-arʿa): Onkelos redă astfel „goliciunea țării”."]},{"v":10,"t":"Și ei i-au zis: „Nu, stăpâne; robii tăi au venit să cumpere grâne."},{"v":11,"t":"Toți suntem fiii unui singur om; suntem oameni cinstiți; robii tăi n-au fost iscoade.”"},{"v":12,"t":"Și el le-a zis: „Nu, ci ați venit să vedeți părțile slabe ale țării.”"},{"v":13,"t":"Și ei au zis: „Noi, robii tăi, suntem doisprezece frați, fiii unui singur om în țara Canaan; și iată, cel mic este astăzi cu tatăl nostru, iar unul nu mai este.”"},{"v":14,"t":"Și Iosif le-a zis: „Este ce v-am spus, zicând: Sunteți iscoade."},{"v":15,"t":"Prin aceasta veți fi încercați: pe viața lui Faraon, nu veți ieși de aici decât dacă va veni aici fratele vostru cel mic."},{"v":16,"t":"Trimiteți pe unul dintre voi să-l aducă pe fratele vostru, iar voi veți fi ținuți legați, și cuvintele voastre vor fi încercate, dacă spuneți adevărul; iar dacă nu, pe viața lui Faraon, sunteți iscoade.”"},{"v":17,"t":"Și i-a adunat în închisoare trei zile."},{"v":18,"t":"Și Iosif le-a zis în ziua a treia: „Faceți aceasta și veți trăi: eu mă tem de Domnul."},{"v":19,"t":"Dacă sunteți oameni cinstiți, unul dintre frații voștri să rămână legat în casa în care sunteți păziți, iar voi duceți-vă, duceți grâne pentru lipsa din casele voastre."},{"v":20,"t":"Și pe fratele vostru cel mic aduceți-l la mine, și cuvintele voastre se vor adeveri, și nu veți muri.” Și au făcut așa."},{"v":21,"t":"Și au zis unul către altul: „Cu adevărat suntem vinovați față de fratele nostru, căci am văzut strâmtorarea sufletului lui când ne implora, și nu l-am ascultat; de aceea a venit asupra noastră strâmtorarea aceasta.”"},{"v":22,"t":"Și Ruben le-a răspuns, zicând: „Nu v-am spus eu, zicând: Nu păcătuiți față de băiat? Dar n-ați ascultat; și iată, și sângele lui ne este cerut.”"},{"v":23,"t":"Și ei nu știau că Iosif înțelegea, căci era un tălmaci între ei."},{"v":24,"t":"Și s-a întors de la ei și a plâns; și s-a întors la ei și le-a vorbit; și l-a luat dintre ei pe Simeon și l-a legat în fața ochilor lor."},{"v":25,"t":"Și Iosif a poruncit să li se umple sacii (sau „vasele”) cu grâne și să li se pună argintul înapoi, fiecăruia în sacul lui, și să li se dea merinde pentru drum; și li s-a făcut așa."},{"v":26,"t":"Și și-au încărcat grânele pe măgari și au plecat de acolo."},{"v":27,"t":"Și unul și-a deschis sacul ca să dea nutreț măgarului său la locul de popas și și-a văzut argintul, și iată, era la gura sacului (sau „poverii”) său.","notes":["„sacului (sau poverii)” (ṭoʿena): cuvântul aramaic înseamnă „povară, încărcătură”; Onkelos îl folosește pentru sacul de grâne; la fel în versetele următoare unde apare „sac”."]},{"v":28,"t":"Și le-a zis fraților săi: „Argintul meu mi-a fost dat înapoi; și iată, este chiar în sacul meu.” Și inima li s-a dus și s-au uitat cu groază unul la altul, zicând: „Ce este aceasta pe care ne-a făcut-o Domnul?”"},{"v":29,"t":"Și au venit la Iacov, tatăl lor, în țara Canaan și i-au povestit toate cele întâmplate lor, zicând:"},{"v":30,"t":"„Omul, stăpânul țării, ne-a vorbit aspru și ne-a socotit ca pe niște iscoade ale țării."},{"v":31,"t":"Și i-am zis: Suntem oameni cinstiți; n-am fost iscoade."},{"v":32,"t":"Suntem doisprezece frați, fiii tatălui nostru; unul nu mai este, iar cel mic este astăzi cu tatăl nostru în țara Canaan."},{"v":33,"t":"Și omul, stăpânul țării, ne-a zis: «Prin aceasta voi ști că sunteți oameni cinstiți: lăsați la mine pe unul dintre frații voștri, iar grânele pentru lipsa din casele voastre luați-le și duceți-vă."},{"v":34,"t":"Și aduceți-l la mine pe fratele vostru cel mic, și voi ști că nu sunteți iscoade, ci oameni cinstiți; pe fratele vostru vi-l voi da, iar în țară veți face negoț.»”"},{"v":35,"t":"Și a fost, pe când își goleau sacii, iată, fiecare avea legătura cu argintul lui în sacul lui; și au văzut legăturile cu argintul lor, ei și tatăl lor, și s-au temut."},{"v":36,"t":"Și Iacov, tatăl lor, le-a zis: „M-ați lăsat fără copii: Iosif nu mai este, Simeon nu este aici (nu mai este), și pe Beniamin vreți să-l luați. Asupra mea au venit toate acestea!”","notes":["„(nu mai este)”: ediția are leteh între paranteze, ca variantă; traducerea îl păstrează în paranteze."]},{"v":37,"t":"Și Ruben i-a zis tatălui său, zicând: „Pe cei doi fii ai mei să-i omori, dacă nu ți-l voi aduce înapoi; dă-l în mâna mea, și eu ți-l voi aduce înapoi.”"},{"v":38,"t":"Și el a zis: „Fiul meu nu va coborî cu voi, căci fratele lui a murit și el a rămas singur; și dacă îl va ajunge moartea pe drumul pe care veți merge, veți coborî cu întristare bătrânețea mea în Șeol.”"}]},{"num":43,"title":"Pereq 43 - Capitolul 43","verses":[{"v":1,"t":"Și foametea era grea în țară."},{"v":2,"t":"Și a fost, când au isprăvit de mâncat grânele pe care le aduseseră din Egipt („Mițrayim”), că tatăl lor le-a zis: „Întoarceți-vă și cumpărați-ne puține grâne.”"},{"v":3,"t":"Și Iuda i-a zis, zicând: „Omul ne-a dat de știre cu tărie, zicând: «Să nu-mi vedeți fața decât dacă fratele vostru va fi cu voi.»"},{"v":4,"t":"Dacă îl trimiți pe fratele nostru cu noi, vom coborî și îți vom cumpăra grâne."},{"v":5,"t":"Dar dacă nu-l trimiți, nu vom coborî, căci omul ne-a zis: «Să nu-mi vedeți fața decât dacă fratele vostru va fi cu voi.»”"},{"v":6,"t":"Și Israel a zis: „De ce mi-ați făcut rău, spunându-i omului că mai aveți un frate?”"},{"v":7,"t":"Și ei au zis: „Omul ne-a întrebat cu de-amănuntul despre noi și despre rudenia noastră, zicând: «Mai trăiește tatăl vostru? Aveți un frate?» Și i-am spus după cuvintele acestea. Oare puteam ști că va zice: «Coborâți-l pe fratele vostru»?”"},{"v":8,"t":"Și Iuda i-a zis lui Israel, tatăl său: „Trimite băiatul cu mine, și ne vom ridica și vom merge, și vom trăi și nu vom muri, nici noi, nici tu, nici copiii noștri."},{"v":9,"t":"Eu sunt chezaș pentru el; din mâna mea să-l ceri. Dacă nu ți-l voi aduce și nu-l voi pune înaintea ta, voi fi vinovat față de tine în toate zilele."},{"v":10,"t":"Căci, dacă n-am fi zăbovit, acum ne-am fi întors de două ori.”"},{"v":11,"t":"Și Israel, tatăl lor, le-a zis: „Dacă este așa, faceți aceasta: luați din ce este mai lăudat în țară în vasele voastre și coborâți omului un dar: puțin balsam și puțină miere, ceară și mastic, fistic și migdale."},{"v":12,"t":"Și luați în mâinile voastre argint îndoit; iar argintul care v-a fost dat înapoi la gura sacilor voștri duceți-l înapoi cu mâna voastră; poate a fost o greșeală."},{"v":13,"t":"Și luați-l pe fratele vostru și ridicați-vă, întoarceți-vă la om."},{"v":14,"t":"Și Dumnezeul Atotputernic (El Șadai) să vă dea îndurare înaintea omului, ca să vă lase pe celălalt frate al vostru și pe Beniamin. Iar eu, așa cum am fost lăsat fără copii, voi fi lăsat fără copii.”"},{"v":15,"t":"Și oamenii au luat darul acesta și au luat în mâinile lor argint îndoit și pe Beniamin; și s-au ridicat și au coborât în Egipt („Mițrayim”) și au stat înaintea lui Iosif."},{"v":16,"t":"Și Iosif l-a văzut pe Beniamin cu ei și i-a zis celui care era pus peste casa lui: „Du-i pe oamenii aceștia în casă și înjunghie vite și pregătește, căci cu mine vor mânca oamenii aceștia la amiază.”"},{"v":17,"t":"Și omul a făcut cum spusese Iosif; și omul i-a dus pe oameni în casa lui Iosif."},{"v":18,"t":"Și oamenii s-au temut că fuseseră duși în casa lui Iosif și au zis: „Din pricina argintului care ne-a fost pus înapoi în saci data trecută suntem duși, ca să se înalțe asupra noastră și să ne învinuiască pe nedrept și să ne ia ca robi, și pe măgarii noștri.”","notes":["„să ne învinuiască pe nedrept” (le-istaqqafa ʿalana): așa redă Onkelos ebraicul „să se năpustească asupra noastră”, adică „să pună asupra noastră lucruri care n-au fost”."]},{"v":19,"t":"Și s-au apropiat de omul care era pus peste casa lui Iosif și i-au vorbit la intrarea casei"},{"v":20,"t":"și au zis: „Te rugăm, stăpâne, am coborât data trecută să cumpărăm grâne."},{"v":21,"t":"Și a fost, când am ajuns la locul de popas și ne-am deschis sacii, iată, argintul fiecăruia era la gura sacului său, argintul nostru după greutatea lui; și l-am adus înapoi cu mâna noastră."},{"v":22,"t":"Și alt argint am coborât în mâna noastră ca să cumpărăm grâne; nu știm cine ne-a pus argintul în saci.”"},{"v":23,"t":"Și el a zis: „Pace vouă, nu vă temeți! Dumnezeul vostru și Dumnezeul tatălui vostru v-a dat o comoară în sacii voștri; argintul vostru a ajuns la mine.” Și l-a scos la ei pe Simeon."},{"v":24,"t":"Și omul i-a dus pe oameni în casa lui Iosif și le-a dat apă, și și-au spălat picioarele; și a dat nutreț măgarilor lor."},{"v":25,"t":"Și au pregătit darul până să vină Iosif la amiază, căci auziseră că acolo vor mânca pâine."},{"v":26,"t":"Și Iosif a intrat în casă, și i-au adus darul care era în mâinile lor, în casă, și s-au plecat înaintea lui până la pământ."},{"v":27,"t":"Și i-a întrebat de sănătate și a zis: „Este bine tatăl vostru, bătrânul despre care ați vorbit? Mai trăiește?”"},{"v":28,"t":"Și ei au zis: „Este bine robul tău, tatăl nostru; mai trăiește.” Și s-au plecat și s-au închinat."},{"v":29,"t":"Și și-a ridicat ochii și l-a văzut pe Beniamin, fratele său, fiul mamei sale, și a zis: „Acesta este fratele vostru cel mic, despre care mi-ați vorbit?” Și a zis: „Domnul să se îndure de tine, fiul meu.”"},{"v":30,"t":"Și Iosif s-a grăbit, căci i se înduioșase inima pentru fratele său, și voia să plângă; și a intrat în odaia de culcare și a plâns acolo."},{"v":31,"t":"Și și-a spălat fața și a ieșit și s-a stăpânit și a zis: „Puneți pâine.”"},{"v":32,"t":"Și i-au pus lui deosebi, și lor deosebi, și egiptenilor care mâncau cu el deosebi; căci egiptenii nu pot mânca pâine cu evreii, pentru că animalul de care se tem egiptenii îl mănâncă evreii.","notes":["Onkelos explică „căci este o urâciune pentru egipteni” prin „animalul de care se tem (pe care îl venerează) egiptenii îl mănâncă evreii”."]},{"v":33,"t":"Și au șezut înaintea lui, cel mare după vârsta lui și cel mic după tinerețea lui; și oamenii se mirau unul către altul."},{"v":34,"t":"Și le-a trimis porții dinaintea lui; și porția lui Beniamin era mai mare decât porțiile tuturor, de cinci ori. Și au băut și s-au îmbătat cu el."}]},{"num":44,"title":"Pereq 44 - Capitolul 44","verses":[{"v":1,"t":"Și i-a poruncit celui care era pus peste casa lui, zicând: „Umple sacii oamenilor cu grâne, cât pot duce, și pune argintul fiecăruia la gura sacului său."},{"v":2,"t":"Și paharul meu, paharul de argint, pune-l la gura sacului celui mic, împreună cu argintul grânelor lui.” Și a făcut după cuvântul pe care îl spusese Iosif."},{"v":3,"t":"Dimineața s-a luminat, și oamenii au fost lăsați să plece, ei și măgarii lor."},{"v":4,"t":"Ei ieșiseră din cetate, nu se depărtaseră, când Iosif i-a zis celui care era pus peste casa lui: „Ridică-te, urmărește-i pe oameni, și când îi vei ajunge, să le zici: «De ce ați răsplătit binele cu rău?"},{"v":5,"t":"Nu este acesta paharul din care bea stăpânul meu și cu care cercetează el cu de-amănuntul? Rău ați făcut ce ați făcut.»”","notes":["„cercetează cu de-amănuntul” (badqa mevadeq): Onkelos evită sensul de „ghicește” al ebraicului niḥeș; la fel la 44:15."]},{"v":6,"t":"Și i-a ajuns și le-a spus cuvintele acestea."},{"v":7,"t":"Și ei i-au zis: „De ce vorbește stăpânul meu astfel de cuvinte? Departe de robii tăi să facă un astfel de lucru!"},{"v":8,"t":"Iată, argintul pe care l-am găsit la gura sacilor noștri ți l-am adus înapoi din țara Canaan; și cum să furăm din casa stăpânului tău argint sau aur (obiecte de argint sau obiecte de aur)?","notes":["„(obiecte de argint sau obiecte de aur)”: ediția are această variantă între paranteze; traducerea o păstrează."]},{"v":9,"t":"Cel dintre robii tăi la care se va găsi să moară, și chiar noi să-i fim robi stăpânului meu.”"},{"v":10,"t":"Și el a zis: „Și acum, să fie după cuvintele voastre: cel la care se va găsi să-mi fie rob, iar voi veți fi nevinovați.”"},{"v":11,"t":"Și s-au grăbit și fiecare și-a coborât sacul la pământ, și fiecare și-a deschis sacul."},{"v":12,"t":"Și a căutat, începând de la cel mare și sfârșind cu cel mic; și paharul s-a găsit în sacul lui Beniamin."},{"v":13,"t":"Și și-au sfâșiat hainele, și fiecare și-a încărcat măgarul, și s-au întors în cetate."},{"v":14,"t":"Și Iuda și frații lui au intrat în casa lui Iosif, iar el era încă acolo; și au căzut înaintea lui la pământ."},{"v":15,"t":"Și Iosif le-a zis: „Ce faptă este aceasta pe care ați făcut-o? Nu știați că un om ca mine cercetează cu de-amănuntul?”"},{"v":16,"t":"Și Iuda a zis: „Ce să-i spunem stăpânului meu? Ce să vorbim și cum să ne dezvinovățim? De la Domnul a fost aflată vina robilor tăi. Iată, suntem robi stăpânului meu, și noi, și cel în mâna căruia s-a găsit paharul.”"},{"v":17,"t":"Și el a zis: „Departe de mine să fac aceasta! Omul în mâna căruia s-a găsit paharul, el să-mi fie rob, iar voi urcați în pace la tatăl vostru.”"},{"v":18,"t":"Și Iuda s-a apropiat de el și a zis: „Te rog, stăpâne, să vorbească acum robul tău un cuvânt înaintea stăpânului meu, și să nu se aprindă mânia ta asupra robului tău, căci tu ești ca Faraon."},{"v":19,"t":"Stăpânul meu i-a întrebat pe robii lui, zicând: «Aveți un tată sau un frate?»"},{"v":20,"t":"Și i-am zis stăpânului meu: «Avem un tată bătrân și un fiu al bătrâneților, mic; și fratele lui a murit, și el a rămas singur de la mama lui, și tatăl lui îl iubește.»"},{"v":21,"t":"Și ai zis robilor tăi: «Coborâți-l la mine, ca să-mi pun ochii asupra lui.»"},{"v":22,"t":"Și i-am zis stăpânului meu: «Băiatul nu-și poate lăsa tatăl; și dacă își va lăsa tatăl, acesta va muri.»"},{"v":23,"t":"Și ai zis robilor tăi: «Dacă fratele vostru cel mic nu va coborî cu voi, nu veți mai vedea fața mea.»"},{"v":24,"t":"Și a fost, când am urcat la robul tău, tatăl meu, că i-am spus cuvintele stăpânului meu."},{"v":25,"t":"Și tatăl nostru a zis: «Întoarceți-vă, cumpărați-ne puține grâne.»"},{"v":26,"t":"Și am zis: «Nu putem coborî; dacă fratele nostru cel mic va fi cu noi, vom coborî, căci nu putem vedea fața omului dacă fratele nostru cel mic nu este cu noi.»"},{"v":27,"t":"Și robul tău, tatăl meu, ne-a zis: «Voi știți că soția mea mi-a născut doi."},{"v":28,"t":"Și unul a ieșit de la mine, și am zis: Negreșit a fost ucis; și nu l-am mai văzut până acum."},{"v":29,"t":"Și dacă îl veți lua și pe acesta dinaintea mea și îl va ajunge moartea, veți coborî bătrânețea mea cu rău în Șeol.»"},{"v":30,"t":"Și acum, când voi veni la robul tău, tatăl meu, și băiatul nu va fi cu noi, iar sufletul lui îi este drag ca sufletul lui însuși,"},{"v":31,"t":"va fi, când va vedea că băiatul nu este, că va muri; și robii tăi vor coborî bătrânețea robului tău, tatăl nostru, cu întristare în Șeol."},{"v":32,"t":"Căci robul tău s-a pus chezaș pentru băiat la tatăl meu, zicând: «Dacă nu ți-l voi aduce, voi fi vinovat față de tatăl meu în toate zilele.»"},{"v":33,"t":"Și acum, să rămână, te rog, robul tău în locul băiatului, rob stăpânului meu, iar băiatul să urce cu frații lui."},{"v":34,"t":"Căci cum să urc la tatăl meu, dacă băiatul nu este cu mine? Ca nu cumva să văd răul care îl va ajunge pe tatăl meu.”"}]},{"num":45,"title":"Pereq 45 - Capitolul 45","verses":[{"v":1,"t":"Și Iosif n-a mai putut să se stăpânească înaintea tuturor celor care stăteau lângă el și a strigat: „Scoateți pe toți oamenii de lângă mine!” Și n-a rămas nimeni cu el când Iosif s-a făcut cunoscut fraților lui."},{"v":2,"t":"Și și-a ridicat glasul cu plâns; și egiptenii au auzit, și casa lui Faraon a auzit."},{"v":3,"t":"Și Iosif le-a zis fraților lui: „Eu sunt Iosif. Mai trăiește tatăl meu?” Și frații lui nu i-au putut răspunde, căci se tulburaseră dinaintea lui."},{"v":4,"t":"Și Iosif le-a zis fraților lui: „Apropiați-vă, vă rog, de mine.” Și s-au apropiat. Și a zis: „Eu sunt Iosif, fratele vostru, pe care m-ați vândut în Egipt („Mițrayim”)."},{"v":5,"t":"Și acum, nu vă mâhniți și să nu fie rău în ochii voștri că m-ați vândut aici, căci ca să păstrez viața m-a trimis Domnul înaintea voastră."},{"v":6,"t":"Căci iată, de doi ani este foamete în țară, și mai sunt încă cinci ani în care nu va fi nici semănat, nici seceriș."},{"v":7,"t":"Și Domnul m-a trimis înaintea voastră ca să vă pun o rămășiță pe pământ și să vă păstrez în viață printr-o mare scăpare."},{"v":8,"t":"Și acum, nu voi m-ați trimis aici, ci de la Domnul; și m-a pus tată pentru Faraon și stăpân peste toată casa lui și stăpânitor în toată țara Egiptului („Mițrayim”)."},{"v":9,"t":"Grăbiți-vă și urcați la tatăl meu și spuneți-i: Așa zice fiul tău Iosif: «Domnul m-a pus stăpân peste tot Egiptul („Mițrayim”); coboară la mine, nu zăbovi."},{"v":10,"t":"Și vei locui în țara Goșen și vei fi aproape de mine, tu și fiii tăi și fiii fiilor tăi și oile tale și boii tăi și tot ce ai."},{"v":11,"t":"Și te voi hrăni acolo, căci mai sunt cinci ani de foamete, ca să nu sărăcești tu și casa ta și tot ce ai.»"},{"v":12,"t":"Și iată, ochii voștri văd, și ochii fratelui meu Beniamin, că eu vă vorbesc în limba voastră."},{"v":13,"t":"Și să-i spuneți tatălui meu toată slava mea în Egipt („Mițrayim”) și tot ce ați văzut; și grăbiți-vă și coborâți-l pe tatăl meu aici.”"},{"v":14,"t":"Și i-a căzut pe gât lui Beniamin, fratele său, și a plâns; și Beniamin a plâns pe gâtul lui."},{"v":15,"t":"Și i-a sărutat pe toți frații lui și a plâns asupra lor; și după aceea frații lui au vorbit cu el."},{"v":16,"t":"Și vestea s-a auzit în casa lui Faraon, zicând: „Au venit frații lui Iosif.” Și a plăcut în ochii lui Faraon și în ochii slujitorilor lui."},{"v":17,"t":"Și Faraon i-a zis lui Iosif: „Spune fraților tăi: Faceți aceasta: încărcați-vă dobitoacele și duceți-vă, mergeți în țara Canaan."},{"v":18,"t":"Și luați-l pe tatăl vostru și casele voastre și veniți la mine, și vă voi da ce este mai bun în țara Egiptului („Mițrayim”), și veți mânca belșugul țării."},{"v":19,"t":"Iar ție ți se poruncește: Faceți aceasta: luați-vă din țara Egiptului („Mițrayim”) căruțe pentru copiii voștri și pentru soțiile voastre și aduceți-l pe tatăl vostru și veniți."},{"v":20,"t":"Și ochiul vostru să nu le pară rău de lucrurile voastre, căci ce este mai bun în toată țara Egiptului („Mițrayim”) al vostru este.”"},{"v":21,"t":"Și fiii lui Israel au făcut așa; și Iosif le-a dat căruțe, după cuvântul lui Faraon, și le-a dat merinde pentru drum."},{"v":22,"t":"Tuturor le-a dat, fiecăruia, câte un rând de haine; iar lui Beniamin i-a dat trei sute de sicli de argint și cinci rânduri de haine."},{"v":23,"t":"Și tatălui său i-a trimis astfel: zece măgari încărcați cu cele mai bune lucruri ale Egiptului („Mițrayim”) și zece măgărițe încărcate cu grâne și pâine și merinde pentru tatăl său, pentru drum."},{"v":24,"t":"Și i-a trimis pe frații lui, și au plecat; și le-a zis: „Nu vă certați pe drum.”"},{"v":25,"t":"Și au urcat din Egipt („Mițrayim”) și au ajuns în țara Canaan, la Iacov, tatăl lor."},{"v":26,"t":"Și i-au spus, zicând: „Iosif încă trăiește și el este stăpânitor în toată țara Egiptului („Mițrayim”).” Și cuvintele au rămas fără efect asupra inimii lui, căci nu i-a crezut.","notes":["„cuvintele au rămas fără efect asupra inimii lui” (havu melaya fiygan ʿal libbeh): literal „cuvintele au fost slăbite pe inima lui”; Onkelos redă astfel „i-a slăbit inima”."]},{"v":27,"t":"Și i-au spus toate cuvintele lui Iosif, pe care le spusese către ei; și a văzut căruțele pe care le trimisese Iosif ca să-l ducă; și duhul profeției s-a sălășluit asupra lui Iacov, tatăl lor.","notes":["Onkelos redă „și a reînviat duhul lui Iacov” prin „duhul profeției s-a sălășluit asupra lui Iacov”."]},{"v":28,"t":"Și Israel a zis: „Multă bucurie am: Iosif, fiul meu, încă trăiește; mă voi duce și-l voi vedea înainte să mor.”"}]},{"num":46,"title":"Pereq 46 - Capitolul 46","verses":[{"v":1,"t":"Și Israel a pornit, cu tot ce avea, și a ajuns la Beer-Șeba și a adus jertfe Dumnezeului tatălui său Isaac."},{"v":2,"t":"Și Domnul i-a zis lui Israel într-o vedenie de noapte și a zis: „Iacove, Iacove!” Și el a zis: „Iată-mă.”"},{"v":3,"t":"Și a zis: „Eu sunt Dumnezeu, Dumnezeul tatălui tău; nu te teme să cobori în Egipt („Mițrayim”), căci acolo te voi face un popor mare."},{"v":4,"t":"Eu voi coborî cu tine în Egipt („Mițrayim”) și Eu te voi și urca negreșit; și Iosif își va pune mâinile pe ochii tăi.”"},{"v":5,"t":"Și Iacov s-a ridicat de la Beer-Șeba; și fiii lui Israel l-au dus pe Iacov, tatăl lor, și pe copiii lor și pe soțiile lor în căruțele pe care le trimisese Faraon ca să-l ducă."},{"v":6,"t":"Și și-au luat vitele și averea pe care o agoniseau în țara Canaan și au venit în Egipt („Mițrayim”), Iacov și toți fiii lui cu el:"},{"v":7,"t":"fiii lui și fiii fiilor lui cu el, fiicele lui și fiicele fiilor lui; și pe toți urmașii lui i-a adus cu el în Egipt („Mițrayim”)."},{"v":8,"t":"Și acestea sunt numele fiilor lui Israel care au venit în Egipt („Mițrayim”), Iacov și fiii lui: întâiul născut al lui Iacov, Ruben."},{"v":9,"t":"Și fiii lui Ruben: Enoh și Palu și Hețron și Carmi."},{"v":10,"t":"Și fiii lui Simeon: Iemuel și Iamin și Ohad și Iachin și Țohar și Saul, fiul canaanitei."},{"v":11,"t":"Și fiii lui Levi: Gherșon, Chehat și Merari."},{"v":12,"t":"Și fiii lui Iuda: Er și Onan și Șela și Pereț și Zerah; și Er și Onan au murit în țara Canaan. Și fiii lui Pereț au fost Hețron și Hamul."},{"v":13,"t":"Și fiii lui Isahar: Tola și Puva și Iob și Șimron."},{"v":14,"t":"Și fiii lui Zabulon: Sered și Elon și Iahleel."},{"v":15,"t":"Aceștia sunt fiii Leei, pe care i-a născut lui Iacov în Padan-Aram, și Dina, fiica lui; toate sufletele fiilor și fiicelor lui: treizeci și trei."},{"v":16,"t":"Și fiii lui Gad: Țifion și Haghi, Șuni și Ețbon, Eri și Arodi și Areli."},{"v":17,"t":"Și fiii lui Așer: Imna și Ișva și Ișvi și Beria, și Serah, sora lor; și fiii lui Beria: Heber și Malchiel."},{"v":18,"t":"Aceștia sunt fiii Zilpei, pe care Laban o dăduse Leei, fiica lui; și ea i-a născut pe aceștia lui Iacov: șaisprezece suflete."},{"v":19,"t":"Fiii Rahelei, soția lui Iacov: Iosif și Beniamin."},{"v":20,"t":"Și lui Iosif i s-au născut în țara Egiptului („Mițrayim”), pe care i i-a născut Asenat, fiica lui Poti-Fera, căpetenia din On: Manase și Efraim."},{"v":21,"t":"Și fiii lui Beniamin: Bela și Becher și Așbel, Ghera și Naaman, Ehi și Roș, Mupim și Hupim și Ard."},{"v":22,"t":"Aceștia sunt fiii Rahelei, care i s-au născut lui Iacov; toate sufletele: paisprezece."},{"v":23,"t":"Și fiii lui Dan: Hușim."},{"v":24,"t":"Și fiii lui Neftali: Iahțeel și Guni și Ițer și Șilem."},{"v":25,"t":"Aceștia sunt fiii Bilhei, pe care Laban o dăduse Rahelei, fiica lui; și ea i-a născut pe aceștia lui Iacov; toate sufletele: șapte."},{"v":26,"t":"Toate sufletele care au venit cu Iacov în Egipt („Mițrayim”), ieșite din coapsa lui, în afară de soțiile fiilor lui Iacov, toate sufletele: șaizeci și șase."},{"v":27,"t":"Și fiii lui Iosif, care i s-au născut în Egipt („Mițrayim”): două suflete. Toate sufletele casei lui Iacov care au venit în Egipt: șaptezeci."},{"v":28,"t":"Și l-a trimis pe Iuda înaintea lui la Iosif, ca să pregătească locul înaintea lui în Goșen; și au ajuns în țara Goșen."},{"v":29,"t":"Și Iosif și-a înhămat carele și a urcat în întâmpinarea lui Israel, tatăl său, la Goșen; și i s-a arătat și i-a căzut pe gât și a plâns îndelung pe gâtul lui."},{"v":30,"t":"Și Israel i-a zis lui Iosif: „Dacă aș muri de data aceasta, aș fi mângâiat, după ce ți-am văzut fața, că încă trăiești.”"},{"v":31,"t":"Și Iosif le-a zis fraților lui și casei tatălui său: „Voi urca și îi voi spune lui Faraon și îi voi zice: «Frații mei și casa tatălui meu, care erau în țara Canaan, au venit la mine."},{"v":32,"t":"Și oamenii sunt păstori de oi, căci au fost oameni stăpâni de vite; și și-au adus oile și boii și tot ce au.»"},{"v":33,"t":"Și va fi, când vă va chema Faraon și va zice: «Care este îndeletnicirea voastră?»,"},{"v":34,"t":"să ziceți: «Robii tăi au fost oameni stăpâni de vite din tinerețea noastră până acum, și noi, și părinții noștri», ca să locuiți în țara Goșen, căci egiptenii îi țin departe pe toți păstorii de oi.”","notes":["„îi țin departe” (meraḥaqin): Onkelos redă astfel „este o urâciune pentru egipteni”."]}]},{"num":47,"title":"Pereq 47 - Capitolul 47","verses":[{"v":1,"t":"Și Iosif a venit și i-a spus lui Faraon și a zis: „Tatăl meu și frații mei, cu oile lor și boii lor și tot ce au, au venit din țara Canaan, și iată, sunt în țara Goșen.”"},{"v":2,"t":"Și dintre frații lui a luat cinci oameni și i-a pus înaintea lui Faraon."},{"v":3,"t":"Și Faraon le-a zis fraților lui: „Care este îndeletnicirea voastră?” Și ei i-au zis lui Faraon: „Robii tăi sunt păstori de oi, și noi, și părinții noștri.”"},{"v":4,"t":"Și i-au zis lui Faraon: „Am venit să locuim ca străini în țară, căci nu este pășune pentru oile robilor tăi, pentru că foametea este grea în țara Canaan; și acum, să locuiască, te rog, robii tăi în țara Goșen.”"},{"v":5,"t":"Și Faraon i-a zis lui Iosif, zicând: „Tatăl tău și frații tăi au venit la tine."},{"v":6,"t":"Țara Egiptului („Mițrayim”) este înaintea ta; așază-i pe tatăl tău și pe frații tăi în partea cea mai bună a țării; să locuiască în țara Goșen. Și dacă știi că sunt între ei oameni destoinici, pune-i căpetenii peste vitele mele.”"},{"v":7,"t":"Și Iosif l-a adus pe Iacov, tatăl său, și l-a pus înaintea lui Faraon; și Iacov l-a binecuvântat pe Faraon."},{"v":8,"t":"Și Faraon i-a zis lui Iacov: „Câte sunt zilele anilor vieții tale?”"},{"v":9,"t":"Și Iacov i-a zis lui Faraon: „Zilele anilor pribegiei mele sunt o sută treizeci de ani; puține și rele au fost zilele anilor vieții mele și n-au ajuns la zilele anilor vieții părinților mei, în zilele pribegiei lor.”"},{"v":10,"t":"Și Iacov l-a binecuvântat pe Faraon și a ieșit dinaintea lui Faraon."},{"v":11,"t":"Și Iosif i-a așezat pe tatăl său și pe frații săi și le-a dat o moștenire în țara Egiptului („Mițrayim”), în partea cea mai bună a țării, în ținutul Ramses, cum poruncise Faraon."},{"v":12,"t":"Și Iosif i-a hrănit pe tatăl său și pe frații săi și toată casa tatălui său cu pâine, după numărul copiilor."},{"v":13,"t":"Și nu era pâine în toată țara, căci foametea era foarte grea; și poporul din țara Egiptului („Mițrayim”) și poporul din țara Canaan sleiau din pricina foametei."},{"v":14,"t":"Și Iosif a strâns tot argintul care se afla în țara Egiptului („Mițrayim”) și în țara Canaan, pentru grânele pe care le cumpărau; și Iosif a adus argintul în casa lui Faraon."},{"v":15,"t":"Și s-a sfârșit argintul din țara Egiptului („Mițrayim”) și din țara Canaan; și toți egiptenii au venit la Iosif, zicând: „Dă-ne pâine; de ce să murim înaintea ta? Căci s-a sfârșit argintul.”"},{"v":16,"t":"Și Iosif a zis: „Dați-vă vitele, și vă voi da pâine pentru vitele voastre, dacă s-a sfârșit argintul.”"},{"v":17,"t":"Și și-au adus vitele la Iosif; și Iosif le-a dat pâine pentru cai și pentru turmele de oi și pentru cirezile de boi și pentru măgari; și i-a hrănit cu pâine pentru toate vitele lor în anul acela."},{"v":18,"t":"Și s-a sfârșit anul acela, și au venit la el în anul al doilea și i-au zis: „Nu vom ascunde de stăpânul meu că s-a sfârșit argintul, iar turmele de dobitoace sunt ale stăpânului meu; n-a mai rămas înaintea stăpânului meu decât trupurile noastre și pământul nostru."},{"v":19,"t":"De ce să murim înaintea ochilor tăi, și noi, și pământul nostru? Cumpără-ne pe noi și pământul nostru pentru pâine, și vom fi noi și pământul nostru robi lui Faraon; și dă sămânță, ca să trăim și să nu murim, iar pământul să nu rămână pustiu.”"},{"v":20,"t":"Și Iosif a cumpărat tot pământul Egiptului („Mițrayim”) pentru Faraon, căci egiptenii și-au vândut fiecare câmpul, pentru că foametea se întărise asupra lor; și țara a fost a lui Faraon."},{"v":21,"t":"Iar pe popor l-a mutat din cetate în cetate, de la un capăt al hotarului Egiptului („Mițrayim”) până la celălalt capăt."},{"v":22,"t":"Numai pământul preoților nu l-a cumpărat, căci preoții aveau o parte de la Faraon și mâncau partea lor pe care le-o dădea Faraon; de aceea nu și-au vândut pământul."},{"v":23,"t":"Și Iosif a zis poporului: „Iată, v-am cumpărat astăzi pe voi și pământul vostru pentru Faraon; iată, aveți sămânță, și să semănați pământul."},{"v":24,"t":"Și va fi, la strângerea recoltei, că veți da a cincea parte lui Faraon, iar patru părți vor fi ale voastre, ca sămânță pentru câmp și ca hrană pentru voi și pentru cei din casele voastre și ca hrană pentru copiii voștri.”"},{"v":25,"t":"Și ei au zis: „Ne-ai păstrat în viață; să găsim îndurare în ochii stăpânului meu, și vom fi robi lui Faraon.”"},{"v":26,"t":"Și Iosif a făcut din aceasta o hotărâre până în ziua aceasta asupra țării Egiptului („Mițrayim”), ca să dea a cincea parte lui Faraon; numai pământul preoților, numai al lor, n-a fost al lui Faraon."},{"v":27,"t":"Și Israel a locuit în țara Egiptului („Mițrayim”), în țara Goșen; și au dobândit proprietăți în ea și au fost roditori și s-au înmulțit foarte mult."},{"v":28,"t":"Și Iacov a trăit în țara Egiptului („Mițrayim”) șaptesprezece ani; și zilele lui Iacov, anii vieții lui, au fost o sută patruzeci și șapte de ani."},{"v":29,"t":"Și zilele lui Israel s-au apropiat de moarte; și l-a chemat pe fiul său Iosif și i-a zis: „Dacă am găsit acum îndurare în ochii tăi, pune-ți, te rog, mâna sub coapsa mea și fă-mi bunătate și adevăr: să nu mă îngropi, te rog, în Egipt („Mițrayim”)."},{"v":30,"t":"Și să mă culc cu părinții mei; și să mă duci din Egipt („Mițrayim”) și să mă îngropi în mormântul lor.” Și el a zis: „Eu voi face după cuvântul tău.”"},{"v":31,"t":"Și a zis: „Jură-mi.” Și i-a jurat. Și Israel s-a închinat la căpătâiul patului."}]},{"num":48,"title":"Pereq 48 - Capitolul 48","verses":[{"v":1,"t":"Și a fost, după lucrurile acestea, că i s-a zis lui Iosif: „Iată, tatăl tău este bolnav la pat.” Și i-a luat cu el pe cei doi fii ai săi, pe Manase și pe Efraim."},{"v":2,"t":"Și i s-a spus lui Iacov și i s-a zis: „Iată, fiul tău Iosif vine la tine.” Și Israel s-a întărit și s-a așezat pe pat."},{"v":3,"t":"Și Iacov i-a zis lui Iosif: „Dumnezeul Atotputernic (El Șadai) mi S-a descoperit la Luz, în țara Canaan, și m-a binecuvântat."},{"v":4,"t":"Și mi-a zis: «Iată, te voi face roditor și te voi înmulți și te voi face o adunare de seminții; și voi da țara aceasta urmașilor tăi după tine ca moștenire veșnică.»"},{"v":5,"t":"Și acum, cei doi fii ai tăi, care ți s-au născut în țara Egiptului („Mițrayim”) înainte să vin la tine în Egipt, sunt ai mei: Efraim și Manase vor fi înaintea mea ca Ruben și Simeon."},{"v":6,"t":"Iar copiii pe care îi vei naște după ei vor fi ai tăi; după numele fraților lor se vor numi în moștenirea lor."},{"v":7,"t":"Iar eu, când veneam din Padan, mi-a murit Rahela în țara Canaan, pe drum, când mai era o bucată de drum până să ajung la Efrata; și am îngropat-o acolo, pe drumul spre Efrata, adică Betleem.”"},{"v":8,"t":"Și Israel i-a văzut pe fiii lui Iosif și a zis: „Cine sunt aceștia?”"},{"v":9,"t":"Și Iosif i-a zis tatălui său: „Sunt fiii mei, pe care mi i-a dat Domnul aici.” Și a zis: „Apropie-i, te rog, de mine, și îi voi binecuvânta.”"},{"v":10,"t":"Și ochii lui Israel erau îngreuiați de bătrânețe; nu putea să vadă. Și i-a apropiat de el, și el i-a sărutat și i-a îmbrățișat."},{"v":11,"t":"Și Israel i-a zis lui Iosif: „Nu mă așteptam să-ți mai văd fața, și iată, Domnul m-a făcut să văd și pe copiii tăi.”"},{"v":12,"t":"Și Iosif i-a scos dinaintea lui și s-a plecat cu fața la pământ."},{"v":13,"t":"Și Iosif i-a luat pe amândoi, pe Efraim cu dreapta lui, la stânga lui Israel, și pe Manase cu stânga lui, la dreapta lui Israel, și i-a apropiat de el."},{"v":14,"t":"Și Israel și-a întins dreapta și a pus-o pe capul lui Efraim, care era cel mic, și stânga pe capul lui Manase; și-a încrucișat mâinile cu înțelepciune, căci Manase era întâiul născut."},{"v":15,"t":"Și l-a binecuvântat pe Iosif și a zis: „Domnul, înaintea căruia au slujit părinții mei, Avraam și Isaac, Domnul care m-a hrănit de când sunt până în ziua aceasta,"},{"v":16,"t":"îngerul care m-a răscumpărat din tot răul, să binecuvânteze pe tineri, și să se numească în ei numele meu și numele părinților mei, Avraam și Isaac; și ca peștii mării să se înmulțească în mijlocul fiilor oamenilor pe pământ.”"},{"v":17,"t":"Și Iosif a văzut că tatăl său și-a pus mâna dreaptă pe capul lui Efraim, și i s-a părut rău în ochii lui; și a sprijinit mâna tatălui său ca s-o ia de pe capul lui Efraim și s-o pună pe capul lui Manase."},{"v":18,"t":"Și Iosif i-a zis tatălui său: „Nu așa, tată, căci acesta este întâiul născut; pune-ți dreapta pe capul lui.”"},{"v":19,"t":"Dar tatăl său a refuzat și a zis: „Știu, fiul meu, știu; și el va deveni un popor și și el va fi mare; dar fratele lui cel mic va fi mai mare decât el, iar fiii lui vor fi stăpânitori peste neamuri.”"},{"v":20,"t":"Și i-a binecuvântat în ziua aceea, zicând: „Prin tine va binecuvânta Israel, zicând: «Să te facă Domnul ca Efraim și ca Manase.»” Și l-a pus pe Efraim înaintea lui Manase."},{"v":21,"t":"Și Israel i-a zis lui Iosif: „Iată, eu mor; și Cuvântul Domnului va fi în ajutorul vostru și vă va aduce înapoi în țara părinților voștri."},{"v":22,"t":"Și eu ți-am dat o parte mai mult decât fraților tăi, pe care am luat-o din mâna amoritului prin rugăciunea mea și prin cererea mea.”","notes":["„prin rugăciunea mea și prin cererea mea”: Onkelos redă astfel „cu sabia mea și cu arcul meu”."]}]},{"num":49,"title":"Pereq 49 - Capitolul 49","verses":[{"v":1,"t":"Și Iacov i-a chemat pe fiii săi și a zis: „Adunați-vă, și vă voi spune ce vi se va întâmpla la sfârșitul zilelor."},{"v":2,"t":"Adunați-vă și ascultați, fii ai lui Iacov, și primiți învățătură de la Israel, tatăl vostru."},{"v":3,"t":"Ruben, tu ești întâiul meu născut, puterea mea și începutul tăriei mele; ție ți s-ar fi cuvenit să iei trei părți: dreptul de întâi-născut, preoția și domnia.","notes":["Capitolul 49 (binecuvântările lui Iacov) este în Onkelos o parafrază amplă; traducerea redă exact textul aramaic, nu textul ebraic al Torei."]},{"v":4,"t":"Pentru că ai mers după capul tău, iată, ca apa, n-ai avut folos; o parte în plus nu vei lua, căci ai urcat în locul de culcare al tatălui tău; atunci ai pângărit patul meu, fiul meu, la care ai urcat."},{"v":5,"t":"Simeon și Levi sunt frați, oameni viteji; în țara în care locuiau ca străini au săvârșit fapte de vitejie."},{"v":6,"t":"La taina lor n-a fost sufletul meu; când se adunau să meargă, nu m-am coborât din cinstea mea; căci în mânia lor au ucis ucidere și, după voia lor, au surpat zidul dușmanului."},{"v":7,"t":"Blestemată fie mânia lor, căci este aprigă, și furia lor, căci este aspră! Îi voi împărți în Iacov și îi voi risipi în Israel."},{"v":8,"t":"Iuda, tu ai mărturisit și nu te-ai rușinat; pe tine te vor lăuda frații tăi. Mâna ta se va întări asupra vrăjmașilor tăi; dușmanii tăi se vor risipi, își vor întoarce spatele înaintea ta; și fiii tatălui tău se vor grăbi să te întrebe de sănătate."},{"v":9,"t":"Stăpânirea va fi la început, și la sfârșit va fi uns regele din casa lui Iuda; căci de la judecata de ucidere, fiul meu, ți-ai înălțat sufletul. Se va odihni, va locui în putere ca un leu și ca o leoaică, și nu este împărăție care să-l clatine.","notes":["„de la judecata de ucidere, fiul meu, ți-ai înălțat sufletul”: Onkelos înțelege „de la pradă” ca referire la rolul lui Iuda în salvarea lui Iosif și în episodul cu Tamar."]},{"v":10,"t":"Nu va înceta cel care are stăpânire din casa lui Iuda, nici cărturarul dintre fiii fiilor lui, în veac, până va veni Mesia, a căruia este împărăția, și de el vor asculta popoarele.","notes":["„cel care are stăpânire” și „cărturarul” (safra): Onkelos redă astfel „sceptrul” și „legiuitorul”. Silo este interpretat ca „Mesia”."]},{"v":11,"t":"Israel va înconjura cetatea lui, poporul va zidi templul lui; drepții vor fi de jur împrejurul lui, și cei ce împlinesc Legea vor fi în învățătură cu el. Purpură bună va fi îmbrăcămintea lui; haina lui, lână fină de cea mai bună, vopsită în stacojiu și în culori."},{"v":12,"t":"Munții lui se vor înroși de viile lui, teascurile lui vor curge de vin; văile lui se vor albi de grâne și de turme de oi."},{"v":13,"t":"Zabulon va locui pe țărmul mărilor și va cuceri ținuturi cu corăbii; și va mânca belșugul mării, iar hotarul lui va ajunge până la Sidon."},{"v":14,"t":"Isahar este bogat în averi, iar moștenirea lui este între hotare."},{"v":15,"t":"Și a văzut partea lui, că este bună, și țara, că face roade; și va cuceri ținuturile popoarelor și va nimici pe locuitorii lor, iar cei care vor rămâne dintre ei îi vor fi slujitori și vor plăti biruri."},{"v":16,"t":"Din casa lui Dan va fi ales și se va ridica un om; în zilele lui își va răscumpăra poporul, și în anii lui se vor odihni împreună semințiile lui Israel."},{"v":17,"t":"Omul care va fi ales și se va ridica din casa lui Dan, groaza lui va cădea peste popoare, și lovitura lui va fi puternică asupra filistenilor; ca o viperă va sta pe drum și ca un șarpe va pândi pe cărare; va ucide pe vitejii taberei filistenilor, călăreți împreună cu pedeștri; va tăia vinele cailor și carelor și îi va răsturna pe călăreții lor pe spate."},{"v":18,"t":"Mântuirea Ta o aștept, Doamne."},{"v":19,"t":"Din casa lui Gad, oștiri înarmate vor trece Iordanul înaintea fraților lor la luptă și se vor întoarce cu averi multe în țara lor."},{"v":20,"t":"Bună este țara lui Așer, și ea crește desfătări de regi."},{"v":21,"t":"Lui Neftali îi va cădea sorțul într-o țară bună, și moștenirea lui va face roade; ei vor aduce mulțumire și vor binecuvânta pentru ele."},{"v":22,"t":"Fiul meu care se înmulțește, Iosif, fiul meu care este binecuvântat ca o viță sădită lângă un izvor de apă; două seminții vor ieși din fiii lui, vor primi parte și moștenire."},{"v":23,"t":"Și l-au amărât și l-au urât și l-au asuprit oameni viteji, oameni ai dezbinării (sau „părtași cu el”).","notes":["„oameni care împart cu el” (gavrin baʿale pelaguta): Onkelos redă astfel „arcașii” (baʿale ḥiṣṣim), ca oameni care au parte egală cu el, adică frații lui."]},{"v":24,"t":"Dar profeția lui s-a întors asupra lor, pentru că a împlinit Legea în ascuns și și-a pus încrederea în putere; atunci aurul a fost așezat pe brațele lui și a moștenit domnia și s-a întărit. Aceasta i-a venit de la Dumnezeul cel puternic al lui Iacov, care prin Cuvântul Său hrănește pe părinți și pe fii, sămânța lui Israel."},{"v":25,"t":"Cuvântul Dumnezeului tatălui tău va fi în ajutorul tău, și Cel Atotputernic (Șadai) te va binecuvânta cu binecuvântări care coboară din roua cerurilor de sus, binecuvântări care curg din adâncurile pământului de jos, binecuvântarea tatălui tău și a mamei tale."},{"v":26,"t":"Binecuvântările tatălui tău se vor adăuga la binecuvântările cu care m-au binecuvântat părinții mei, pe care le-au dorit cei mari care sunt din veac; toate acestea vor fi pe capul lui Iosif și pe creștetul bărbatului deosebit dintre frații lui."},{"v":27,"t":"Beniamin: în țara lui se va sălășlui Prezența divină (Șechina), și în moștenirea lui va fi zidit Templul; dimineața și seara preoții vor aduce jertfa, iar la vremea serii vor împărți rămășița părții lor din celelalte lucruri sfinte.","notes":["Onkelos interpretează „Beniamin este un lup care sfâșie” ca referire la Templul din teritoriul lui Beniamin și la jertfele de dimineață și de seară."]},{"v":28,"t":"Toate acestea sunt semințiile lui Israel, douăsprezece; și aceasta este ce le-a spus tatăl lor și i-a binecuvântat; pe fiecare, după binecuvântarea lui, i-a binecuvântat."},{"v":29,"t":"Și le-a poruncit și le-a zis: „Eu sunt adunat la poporul meu; îngropați-mă la părinții mei, în peștera din câmpul lui Efron hetitul,"},{"v":30,"t":"în peștera din câmpul Macpela, care este în fața lui Mamre, în țara Canaan, pe care Avraam a cumpărat-o, cu câmpul, de la Efron hetitul ca proprietate de mormânt."},{"v":31,"t":"Acolo i-au îngropat pe Avraam și pe Sara, soția lui; acolo i-au îngropat pe Isaac și pe Rebeca, soția lui; și acolo am îngropat-o pe Lea:"},{"v":32,"t":"câmpul și peștera care este în el, cumpărate de la fiii lui Het.”"},{"v":33,"t":"Și Iacov a isprăvit de dat porunci fiilor săi și și-a strâns picioarele în pat și și-a dat sufletul și a fost adunat la poporul său."}]},{"num":50,"title":"Pereq 50 - Capitolul 50","verses":[{"v":1,"t":"Și Iosif a căzut pe fața tatălui său și a plâns asupra lui și l-a sărutat."},{"v":2,"t":"Și Iosif le-a poruncit slujitorilor săi, doctorilor, să-l îmbălsămeze pe tatăl său; și doctorii l-au îmbălsămat pe Israel."},{"v":3,"t":"Și i s-au împlinit patruzeci de zile, căci atâtea se împlinesc zilele celor îmbălsămați; și egiptenii l-au plâns șaptezeci de zile."},{"v":4,"t":"Și au trecut zilele plânsului său, și Iosif a vorbit cu casa lui Faraon, zicând: „Dacă am găsit acum îndurare în ochii voștri, vorbiți, vă rog, înaintea lui Faraon, zicând:"},{"v":5,"t":"«Tatăl meu m-a pus să jur, zicând: Iată, eu mor; în mormântul pe care mi l-am pregătit în țara Canaan, acolo să mă îngropi. Și acum, să urc, te rog, și să-l îngrop pe tatăl meu, și mă voi întoarce.»”"},{"v":6,"t":"Și Faraon a zis: „Urcă și îngroapă-l pe tatăl tău, cum te-a pus să juri.”"},{"v":7,"t":"Și Iosif a urcat să-l îngroape pe tatăl său; și au urcat cu el toți slujitorii lui Faraon, bătrânii casei lui și toți bătrânii țării Egiptului („Mițrayim”),"},{"v":8,"t":"și toată casa lui Iosif și frații lui și casa tatălui său; numai copiii lor și oile lor și boii lor i-au lăsat în țara Goșen."},{"v":9,"t":"Și au urcat cu el și care și călăreți, și tabăra a fost foarte mare."},{"v":10,"t":"Și au ajuns la aria lui Atad, care este dincolo de Iordan, și au jelit acolo o jelanie mare și foarte grea; și a ținut pentru tatăl său doliu șapte zile."},{"v":11,"t":"Și locuitorii țării, canaaniții, au văzut doliul la aria lui Atad și au zis: „Acesta este un doliu greu pentru egipteni.” De aceea i s-a pus numele Abel-Mițraim, care este dincolo de Iordan."},{"v":12,"t":"Și fiii lui i-au făcut așa cum le poruncise."},{"v":13,"t":"Și fiii lui l-au dus în țara Canaan și l-au îngropat în peștera câmpului Macpela, pe care Avraam o cumpărase cu câmpul ca proprietate de mormânt de la Efron hetitul, în fața lui Mamre."},{"v":14,"t":"Și Iosif s-a întors în Egipt („Mițrayim”), el și frații lui și toți cei care urcaseră cu el ca să-l îngroape pe tatăl său, după ce l-a îngropat pe tatăl său."},{"v":15,"t":"Și frații lui Iosif au văzut că tatăl lor murise și au zis: „Poate Iosif ne va purta dușmănie și ne va răsplăti tot răul pe care i l-am făcut.”"},{"v":16,"t":"Și au trimis să i se spună lui Iosif: „Tatăl tău a poruncit înainte de moartea lui, zicând:"},{"v":17,"t":"«Așa să-i spuneți lui Iosif: Te rog, iartă acum vina fraților tăi și păcatul lor, căci ți-au făcut rău.» Și acum, iartă, te rog, vina robilor Dumnezeului tatălui tău.” Și Iosif a plâns când i-au vorbit."},{"v":18,"t":"Și au venit și frații lui și au căzut înaintea lui și au zis: „Iată, suntem robii tăi.”"},{"v":19,"t":"Și Iosif le-a zis: „Nu vă temeți, căci eu mă tem de Domnul."},{"v":20,"t":"Voi ați plănuit rău împotriva mea, dar de la Domnul a fost socotit spre bine, ca să facă cum este în ziua aceasta, să păstreze în viață un popor mare."},{"v":21,"t":"Și acum, nu vă temeți: eu vă voi hrăni pe voi și pe copiii voștri.” Și i-a mângâiat și le-a vorbit cuvinte de mângâiere pe inimă."},{"v":22,"t":"Și Iosif a locuit în Egipt („Mițrayim”), el și casa tatălui său; și Iosif a trăit o sută zece ani."},{"v":23,"t":"Și Iosif a văzut copiii lui Efraim până la a treia generație; și fiii lui Machir, fiul lui Manase, s-au născut, și Iosif i-a crescut."},{"v":24,"t":"Și Iosif le-a zis fraților săi: „Eu mor; dar Domnul Își va aduce negreșit aminte de voi și vă va face să urcați din țara aceasta în țara pe care a jurat-o lui Avraam, lui Isaac și lui Iacov.”"},{"v":25,"t":"Și Iosif i-a pus pe fiii lui Israel să jure, zicând: „Domnul Își va aduce negreșit aminte de voi, și să-mi urcați oasele de aici.”"},{"v":26,"t":"Și Iosif a murit, în vârstă de o sută zece ani; și l-au îmbălsămat și l-au pus într-un sicriu în Egipt („Mițrayim”)."}]}]};
